/* 平成23年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h23.committeeSessions.push(...[{"id":"h23-20110301-9","meetingId":"h23-cm03","date":"2011年3月1日","dateIso":"2011-03-01","committee":"文教委員会","time":"午前１０時０２分～午後１時４３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"の校舎改築事業の進捗状況","agenda":"の校舎改築事業の進捗状況","exchanges":[{"speaker":"井上委員","kind":"確認","question":"品川地区小中一貫校についてお伺いしたいと思います。そのことについては、真摯に受けとめていかなければいけないと思っているんですが、そういった声に対して、教育委員会事務局はどのような受けとめ方をされているのか、まず１点確認させてください。","respondent":"田村庶務課長","answer":"お金をかけ過ぎているという声があるというのは、私どもにはちょっとわかりませんが、予算編成権については区長にあるので、今の財政状況ですから、改築ですとか、小中一貫校はできるだけ経費をかけないで、先ほどバスの中でもちょっとお話ししたように。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"改築計画の現況報告ということとはずれてしまうかもしれないんですけれども、ちょっとだけ、そういう声はないという理解しているということなので、今までの学校改築の中で、小中一貫校とほかの学校との坪単価を比較できるものというか、ああ、そうですねとわかるところをお知らせいただきたいんですが、それについてちょっと教えてください。","respondent":"田村庶務課長","answer":"校舎の敷地状態が全く違うのと、限られた敷地の中で建てているので、１平米当たり２５万円という１つの目安がありますが、今回の擁壁もそうですけれども、特殊要因があまりにあるので、一概にどういう平米単価でやっているというのは、具体的にそれぞれの学校によって異なるので。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"目安でそういう検討材料があるということはよくわかるんですけれども、それは結果的に公にして、でも、こういうところがいろいろ条件が違うんですという説明がまずは、学校も特別区債を発行しつつ、教育部門というのは今すごく特別区債が多いというところで、みんなに借金しながら、つくっているので、それは予算決算の委員会とおっしゃるのかもしれないんだけれども、格差とは言わないけれども。","respondent":"田村庶務課長","answer":"文教委員会で説明しているのは、工事まで含めてではなく、ある程度の基本設計ができた段階で、こういう建物を中につくります、こういうスペースにしますというのをご説明しているので、平米単価が幾らなのか、あるいは外構工事が幾らで。","id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"わかりました。でも、文教委員会でいろいろな声が上がってくるということなので、ご存じないわけはないと思いますので、そういう資料はともに総務委員会と連携しているということはあると思うので、なるべくそういった話もしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"金野委員","kind":"意見","question":"そこで、今使っている土地のほかに、さらに、先ほどご説明いただきました第一三共の土地を含めると、一気に１万２,０００m2になってくるということで、地域開放も多分考えていらっしゃるんだろうとは思うんですけれども、そうなると、このグラウンド、あるいは校舎の裏側にある公園も活用するという説明をいただきまして、例えば、地域の方がここへ来たときの駐輪場だとか、駐車場だとか。","respondent":"田村庶務課長","answer":"更地引き渡しのときには、今の品川学園の校庭と若干時期をずらして、場合によっては再来年度にかかってしまう工事になるかなということで、具体的にどこに駐車場ですとか、どこに駐輪場ですとか、地域が利用するところはまだ検討俎上であって。","id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"状況はよくわかりました。では、要望で、もし、その段階に入りましたら、ぜひこういったことも考えられればいいかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"午前中の視察、ありがとうございました。平成２３年度はいいと思うんですけれども、平成２４年度になったときに、３歳から４歳に上がるときには、今の定数は、３歳児は２０人だとして、４歳児の定数が３５人になるわけですから、当然定数が下がるわけですよね。品川区の今後の、これに乗っていない学校に対して、どういう計画を持って改築を考えていくのか、その辺をちょっとお聞きしたいと思います。","respondent":"冠木指導課長、吉岡保育課長、田村庶務課長","answer":"そういうところも含めて、今後の教育課程の中に活かしてまいりたいと考えています。当初の幼保一体施設の一番初めの形は、年齢区分型で、ゼロ歳から３歳までが保育園で、４歳から５歳が幼稚園という形でございましたので。ただ、今計画に乗っているのはそこまでですけれども、今後就学人口の動向などを見て、また別途そのときになれば検討するということで。","id":"exchange-007"},{"speaker":"西本委員","kind":"意見","question":"ほかの学校の子どもたちと、環境教育という意味では、自分たちの学校ではできないものを品川学園は持っているわけなので、そこでうらやましいと思ってしまうかもしれないですけれども、教育という観点ではそれを利用できるものだと思いますし、教育委員会だけでなくて、ほかの部署との連携を図るとか、地域の方たちとの連携を図るとか、もっと何か環境を身近に感じられるような、縦割りではなくて。","respondent":"市川教育次長","answer":"そういったことで、委員からご発言のあった趣旨は、できる限り実現できることを考えてまいりたいということでお願いいたします。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういったもので、人の声とか、いろいろな物音とか、そういった音の面での規制というか、レベル的なものは、何かあるんですか、それを１つお伺い、広いので、騒音がいっぱい起こったり、そういうところにおいての対策がもし何か基準があるんだったら、教えていただきたいと思ったのが１点です。","respondent":"和氣学務課長兼小中一貫教育担当課長","answer":"基本的に３クラスで考えていますが、もし４クラスになった場合、４クラスにも対応できるという設計をしておりますので、それぞれの学年、それぞれ特別活動教室という名目で、増えなければ、特別活動で使いたいんですが、万が一増えた場合は。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ工夫していただきたいのと、今後また設計するときには、ぜひ考慮していただきたいということを言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"伊藤副委員長","kind":"質問","question":"今日の視察で１つ気になったところが、保育園と幼稚園の合同の施設と、近隣のマンション、あそこから非常に見通しがいいので、言葉はいけないでしょうけれども、子どもの写真を意図的に撮られたり、そういう二次的なものが起こる可能性があるような感じがしましたので、例えば、当該の建物の改良などは少し大変なんでしょうけれども、保育園側のところだけをすりガラスにしていくとか。","respondent":"吉岡保育課長","answer":"それで、新築の建物であれば、建物の計画の時点ですりガラス化するですとか、目隠しを設けるですとか、いろいろできるんですけれども、既存の形で建っている中では、新たに対策をとってくださいと言うのも難しいかなと思いますので、実際運営する中で。","id":"exchange-011"},{"speaker":"伊藤副委員長","kind":"提案","question":"となれば、例えば、イメージビデオをつくって、ほかの都市に紹介するとか、私もほかの地方自治体から要望があって、小中一貫教育のことを視察してもらったことがありますけれども、目に見える形ができているわけですから、ここで当該の内容を説明するのもいいんだけれども、あわせてそのときに象徴的な形として、小中一貫校の品川学園を取り上げていく、そのほうが目に見える形で、今何というのかな。","respondent":"和氣学務課長兼小中一貫教育担当課長","answer":"さまざま注目されていまして、かつて小中一貫教育を始めたときもビデオをつくりまして、その後もＤＶＤをつくりまして、ご覧いただけるようにしましたので、それについてはまた検討させていただいて、ご提案として受けとめたいと思います。","id":"exchange-012"}]},{"id":"topic-02","title":"の「職員の退職手当に関する条例」改正の概要","agenda":"の「職員の退職手当に関する条例」改正の概要","exchanges":[{"speaker":"西本委員","kind":"質問","question":"２年間措置ということなのですが、この後はなくなるという理解でよろしいんでしょうか。","respondent":"冠木指導課長","answer":"平成２５年度につきましては、もう本則化されるということになります。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/409126?Template=document&Id=4726#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":15875,"voices":50}},{"id":"h23-20110301-5","meetingId":"h23-cm03","date":"2011年3月1日","dateIso":"2011-03-01","committee":"総務委員会","time":"午前１０時０２分～午前１１時４３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"今、具体化の方向に向かってどう進んでいくかというところなんだろうと思うんですけれども、本会議での質問にお答えがあって、なかなか進まない理由についてのお話だったんですけれども、少し要約してもう１回聞かせていただきたいことと、今、なぜ遅くなっているかということと、これから打開していくためにはどうしたらいいかということで、何かお考え等ありましたらお聞かせください。","respondent":"濱野区長","answer":"向こう側の理由です。それからもう一つは、これは事務配分だけがあり方検討委員会の検討課題ではなくて、区域の問題等についても検討課題なのだから、これだけ進めるわけにもいかないでしょうという趣旨の発言が会議の中でありました。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"今時点でも、そういう方向での検討というレベルの話なのか、もっと突っ込んだところに行っているのかということ。ああいう事件があって、これは区の方で担当しないとちゃんとできないんだというような説明だったんですけれども、例えば江戸川区の虐待の事件で行くと、都区制度との絡みで行くとどういうふうに見えるのかということを伺いたいと思います。","respondent":"濱野区長","answer":"ただ、私は、これはご記憶にあるかどうかわからないですけれども、主要５課題の検討課題が残ったときに、財源の問題で、例えば任意共管でやっているんだけれども、これは財源は大都市財源ですよというふうに言って、考え方としてですけれども。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"意見","question":"この資料を見ると、東京都の方が反対すればそのままずっといわゆるペンディングになっていくような気がするんです。そうすると、５３項目というのは東京都の方がオーケーしたものというふうになっているような気がするんですが、都が異論を持っているものというのは、これからどういうふうに進んでいくのかなと思うんですが、その辺についてはどうでしょう。","respondent":"濱野区長","answer":"役割分担を見直すというのは、今、都がやっているけれども、将来的にこれをそっくり区に移すというのではないけれども、将来的に都と区の線引きをもう１回見直す必要があるということが、この役割の検討というところであります。","id":"exchange-003"},{"speaker":"林委員","kind":"質問","question":"内容の話ではなくて、この検討委員会というか、都と区の協議会の形で、リードしているのはどっちなんですか。何をというよりも、全体的に、このいただいた資料で行くと、「こういうことをやろうね。やってほしいよ」と言いながら、次になると、それがすっ飛んでしまっているようなところが見えるんだけれども、都がリードしているのか、区長会というか区がリードしているのか、どっちなんですか。","respondent":"濱野区長","answer":"ですので、地域主権戦略大綱というようなことが出ましたけれども、これは当初のあれからすると随分しぼんでしまいましたが、地域主権というか、あるいは地方分権というのをどんどん進めていく中で。","id":"exchange-004"},{"speaker":"林委員","kind":"質問","question":"２３区として、どっちかというと攻めているつもりで、それぞれの区体制を守ろうとすると攻めていけないというような感じを受けるんですよね。いわゆる、この問題を解決するのに、年数的にはどのぐらいのことを考えているんですか。区側のこれからの考えはここなんだという、徹底した念押しをしておく必要があるのではないのかなというふうに私には聞こえるんだけど、いかがでしょうか。","respondent":"濱野区長","answer":"あれも、今の形からすれば１歩も２歩も先に進んだ形態でありますけれども、そういうものになっていくべきだということはお話として十分にわかりますし、そういう方向で行かなければいけないというのはありますけれども、それはこれの後だろう。","id":"exchange-005"},{"speaker":"林委員","kind":"質問","question":"品川区の、一国一城の城主なんだ。区民がにこにこ輝きを持つためには必要なんだということで、東京都から出てきている部長か課長かよくわかりませんけれども、「あなたたちは東京都のことだけ考えていて、こっちは２３区というそれぞれの領主が相談をして君たちに頼んでいるんだから、君たちは先延ばしの答えはやめろ」という、今、そういうのが首長のはやりじゃないですか。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問・要望","question":"今の選挙の話も含めて、それから区の立場、都の立場はどういう立場なのか。今は参勤交代の状況ではなくなっているだろうと思うんだけれども、そういう中でどうしていくのか。要するに、「我々のこれを認めるんですか、いかがなんですか」というアンケートを出せる立場になるわけですから。それが１点。もう１点は、先ほど大阪維新の会からアンケートがあったと。これは答える必要がないものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問・要望","question":"要するに、１８４項目は都だと。さらに今度は、この役割の検討と是非の検討も含めて、さらに煮詰めて、この中の部分が区になるのか都になるのかという結論が出るものなのか、あるいはこれと同じような形で、最終的にはどうしても結論が出ないで行くということになるのか、その辺の思いというんですかね、区に移管するべき事務がどの程度まで行けば成功したというような判断をされるんでしょうか。","respondent":"濱野区長","answer":"５３項目というと件数は少ないように見えますけれども、もともとほかでは府県がやっている仕事も、かなりの部分については検討対象にしたということと、任意共管が１０８項目もあるということでありますので、５３件というのは。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、さっきもお話に出ておりましたように、４月１０日の都知事選が終わる、新たな知事が決まると、今までに積み上げたことを前提にしながら、一気に話を進めていく、ある意味ではチャンスかなという気もするので、あまり年数をかけないで、これで２年、３年かけていってしまうとエネルギーを消耗していくような気がするので、チャンスのときに一気に攻め込んでしまうという形で都に臨むというか。","respondent":"濱野区長","answer":"かなり細かいものでありますので、とにかくその２件については、先行して具体化に向けて取り組んでいこうというのは、区長会で決めたことでありますので、そこはまず、この後、少なくともこの２件については実務レベルの検討委員会を立ち上げて進んでいこうよということを。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"実際に区民に対して直接いろいろな支援、サービス等を行っているのは区なんですから、それはいずれわかってくれるのではないかなと思うし、区民もきっと理解してくれるのではないか。１点だけお聞きしたいんですが、この都区制度の中で、権限を移譲すると、そこには必ず予算、事業費がついて回るものなんですか。そこだけ知識として教えていただければありがたいと思います。","respondent":"濱野区長","answer":"そのことは、事務配分の話が全部終わった段階で、今度は具体化の中で税財政については話をしていこうということですので、ここのところが終わらないと、税財政のところにはまだ進めないということであります。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問・要望","question":"このあり方をいろいろ検討していくわけですが、今までの都とのいろいろな関係を推しはかるための大きな部分が財政調整の部分であったろうと思います。みんなでまとめよう」という思いがないとまとまっていかない可能性もあるものですから、そういうものの醸成のためにぜひ頑張っていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"私の思う感想なんですが、都の教育長は、自分が教育長にいる間には、統治を続けたいという思いがあるように感じまして、それは一種の統治というか、ガバナンスで、それはそれであれなのかもしれませんけれども、多分、独自性を持つ人事権というのはすごく理解されているようには思うんですが、どうも自分が教育長をやっているうちには無理だみたいな部分を感じましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"平成２３年度都区財政調整","agenda":"平成２３年度都区財政調整","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"１点だけ。平成２２年度の総額の減ですけれども、その理由を教えてください。","respondent":"金子企画財政課長","answer":"そこでは、固定資産税、それから市町村民税が減額になっております。固定資産税は微減なんですけれども、市町村民税法人分につきまして、大体マイナス２.５％ほどです。マイナス２％前後と申しますか、そのぐらい減になっておりますので、それの反映がここに来ているものです。","id":"exchange-013"},{"speaker":"林委員","kind":"質問","question":"今、手元にないんですけれども、平成２３年度の品川区の予算書を我々にもいただいているんですけれども、特別区民税が、財調の中ではマイナスになっているんです。これは東京都全体の話なんだろうけれども。品川区の予算ではプラスになっていますよね。前年度が計算のもとにあるからという話だったんだけれども、これは財調をやるのに東京都はうそを書いてあるんですか。","respondent":"金子企画財政課長","answer":"品川区の平成２３年度の当初予算では、当然品川区の事情で計算して見込んでありますが、これは特別区全体で見た場合には、全体としてはマイナスになるということですから、これは各区の事情がそれぞれ違いますので。","id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"さっきの都区の検討会ではないけれども、また予算特別委員会でやりますが、全体が沈んでいるという流れがあって、品川区だけプラスになっているという理由があるはずだろうと思うので、東京都がうそを書いていないとすれば、東京都全体ではマイナス傾向にあるのに、品川区はプラスになっている、その理由を予算特別委員会でまたお聞きしていこうと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-03","title":"「品川区配偶者暴力対策基本計画」の策定","agenda":"「品川区配偶者暴力対策基本計画」の策定","exchanges":[{"speaker":"林委員","kind":"意見","question":"この配偶者暴力という言葉が何となく引っかかるんです。ずっと前からこういうことを進めていっていたんだろうけれども、こうやっていざでき上がってみると、何か配偶者になっている人間にとっては、配偶者が暴力をふるったときの備えですよという感じに聞こえてならないんです。","respondent":"中山人権啓発課長","answer":"ですから、基本計画自体の名称は、配偶者暴力対策基本計画をつくらなければならないというようなところで横引きはされているんですけれども、一方で、この言葉のイメージから違った印象であったり、中には拒否感を持たれる方もいらっしゃると思うので。","id":"exchange-016"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"私の方からは、今回パブリックコメントを行いまして、１１月２１日の「広報しながわ」で、区のホームページですとか男女共同参画センターですとか、いろいろなところでこれを見ることができますよというふうにされているんですが、果たしてどのぐらいの方がこの全文を見に来られたかというのはなかなかわからないと思うんですけれども、ホームページぐらいは、クリックする回数が多分とれると思うので。","respondent":"中山人権啓発課長","answer":"ホームページの方も、改めまして広報の方に、男女共同参画のところのクリック回数というんですか、どのぐらいの方が見てくださったかというのを数値として確認させていただければと考えています。","id":"exchange-017"},{"speaker":"土井委員","kind":"意見","question":"そこのところで、来やすい雰囲気をどうつくるかというところにぜひ腐心をしてもらいたいということと、それには、このコメント等にもありましたけれども、要するに相談に行ったのが原因でまたひどいことになってしまったというような形になった、あるいはそういう思いが起こるということがあってはいけないわけで、相談機能も含めた中での、ある意味では相談者の時間的な問題、回数的な問題。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"これから進めていくということでよろしくお願いいたします。一つ質問したいんですが、相談機能の充実ということで、それはよくわかります。「ここに電話をしてくださいよ」「相談する連絡場所がありますよ」という表示が、町の中を歩いていてわかるようになるんでしょうか。そのような対策というのは、何か具体的にあるんでしょうか。それだけお聞かせください。","respondent":"中山人権啓発課長","answer":"ですから、できるだけ人の目に多く触れるようなところで、しながわ見守りホットラインの周知をしながら、同時にしっかりとした「ＤＶの相談がここでできます」というチラシやパンフレット等を、区の窓口等に置いていければと考えています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"今のご努力はもちろんわかりますし、これからもそういうふうにやっていただきたいんですが、できれば公共施設等々もあると思うんですが、一般の方がチラシ、パンフレットを入手するのはなかなか難しい。品川区ではいっぱいいろいろな取り組みをされているんですが、なかなかパソコンを見る方も限られてしまうし、チラシを見るという方も限られる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"堺委員","kind":"質問・要望","question":"こういうことに当てはまるかどうかわかりませんが、病気なんかで言う早期発見・早期治療ではありませんが、早い時期、中学生のころからこういうことについてはきちっと教育をしておくというか、大人になってからではなくてそういうところから、ないことが一番いいんだけれども、仮にあった場合はこういうところに相談に行くんだよというふうに教育していく。","respondent":"中山人権啓発課長","answer":"逆に、都立の高校、高校・大学といったところにおいては、今度は区の人権啓発課の方が出張講座みたいなものを行いまして、その中でデートＤＶについての理解を深めていただいたり、こういう相談窓口がありますよというのを生徒に直接伝える場を、今度。","id":"exchange-021"},{"speaker":"堺委員","kind":"質問","question":"そこのところは教育委員会と直接意見の食い違いがあるかと思うんです。特に成長していく過程で必要なことですから、教育委員会のおっしゃっている、その段階では人権尊重というようなことを表に立ててやっていると、それも一理かなと思います。いずれにいたしましても、教育というのは早い時期に必要なことは教えておくということが大切かなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297212?Template=document&Id=1880#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":30173,"voices":57}},{"id":"h23-20110302-14","meetingId":"h23-cm03","date":"2011年3月2日","dateIso":"2011-03-02","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","topics":[{"id":"topic-01","title":"平成２３年請願第６号、第一日野小移転後跡地をＴＯＣの駐車場として貸し出すのを見直し、特養ホーム、認可保育園、公園などへの活用を求める請願","agenda":"平成２３年請願第６号、第一日野小移転後跡地をＴＯＣの駐車場として貸し出すのを見直し、特養ホーム、認可保育園、公園などへの活用を求める請願","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"理事者も特別に２月２５日以降に何か変わったことがあればお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"今の発言なんですけれども、それは議員にとってはそうかもしれませんけれども、今度はこういったところで傍聴者もおり、また議事録も残ってその評価を区民の方がちゃんとできるという議会のそういう審議を狭めるということは非常に問題だと思いますので、何度繰り返しても、行政としてきちんと説明をすることは当然のことだと思いますので、しっかりとこの中で説明を聞いて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"菊地委員","kind":"意見","question":"今の意見に私も同感です。ここでは住民の皆さんがこうしてほしいという願いを持って出された請願ですので、それに真摯にこたえていくという立場で考えれば、やはりきちんと今の理事者の説明があり、議員同士での議論ということが必要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"今の理事者の説明というのは、私は極めて不十分なものだと思いますので、改めてお聞きしたいのですけれども、ＴＯＣに貸し付ける理由は本会議などでも、あるいはこの委員会でも答弁をされていますけれども、まず、この理由についてお聞かせ願います。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、私どもとしましては五反田地域の経済の活性化といった点を考えまして、そういった営業を継続しながら建て替え計画をしていくといったところの計画に協力をしていきたいと考えまして、地域経済の活性化、まちのにぎわいといったことを理由に、今回。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"地域経済の活性化に寄与しているというのは、確かに本会議やこれまでの委員会での答弁の中でお聞きをしています。私はそこがよくわからないのですけれども、具体的にどのように地域経済の活性化に寄与しているのか、それを具体的にお聞かせを願えますか。","respondent":"久保田行財政改革担当課長","answer":"そうした方がやはり五反田のまちを訪れまして、ＴＯＣへ行く、そういったもの、また周辺でお買い物とか飲食をされるといったところで考えますと、そういう意味では五反田地域の地域経済の活性化にも十分寄与しているといったところが１点あります。","id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"４００社のテナント、数千人の働く皆さんがいらっしゃるということなんですけれども、経済の活性化に寄与しているというのであれば、当然その数字上のデータも取りそろえておられるのだと思うんです。その辺の数字上のデータもお聞かせを願いたいと思います。それから４００社のテナントということですけれども、実質的にはテナントそのものも空いている状況なんかもありますよね。","respondent":"久保田行財政改革担当課長","answer":"そうした中では１万人を超える方が来場することもあるということもありますので、そういった方も帰り等には五反田のまちでいろいろなお買い物をされたり、飲食等されるといったところもありますので、そうした意味では、具体的な数字で何億円という数字ではございませんけれども。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"今、言われた最後のところは推定でしかないんですよね。地域経済の活性化に寄与すると言う以上ははっきりした数字があるはずなんです。一体、ＴＯＣがあることで年間何十億、何百億円の経済効果があるか、こうした数字があるはずなんです。それもなくて、これまでの答弁の中で活性化に寄与しているということを言っていることになるんですか。そういう数字をお聞きしているんです。","respondent":"久保田行財政改革担当課長","answer":"八丁目、ＴＯＣの周辺ですけれども、それだけでも約９０億円ほどの年間の販売額があるといったところで、その多くはＴＯＣでのそういった販売額がかなり含まれているのではないかと認識をしています。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"今の数字がＴＯＣだけのものなのかどうかもよくわからないんですけれども、４００社のテナントがあって、実際にその中で企業が生き残りをかけて営業をしているわけですから、これだけのテナントが入っているという状況であれば、当然のことながらそれぐらいの数字というのは生まれてくるんだと思うんです。そこのところをもう少しご説明願えますか。","respondent":"久保田行財政改革担当課長","answer":"特別養護老人ホームにつきましても、これは地域ごとにつくればいいというものでなくて、区全体としてどうするかといったところがありますので、区全体として、私どものほうも学校跡地等を活用しながら現在整備を進めているところでございまして。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問・要望","question":"地域バランスという点で言えば、例えば保育園はこの地域は少ないと言える。ですから、やはり今までの課長のご説明だけで考えれば、このＴＯＣが本当に地域経済の活性化に寄与しているとは思えないし、ましてこういう区民の願い、こういう請願によって直接出てくる区民の願いを取り入れずに、ＴＯＣに強引に貸していくという態勢はやはりもう一度考え直すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"この請願が出された背景というものをちょっと区に確認をさせていただきたいと思うんです。ですから率直にこういった区民の要望を聞く機会をつくってくださいという請願が出されているということについて、区はどのような感想を持たれているのかなということをちょっとお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"その際に、周知に当たりましては町会の方が掲示板を使うなり、自分たちの町会の掲示板にそういった説明に区が来るということを広く周知していただいたり、周辺の方にはポスティング等もやっていただいたというふうに聞いておりますので。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"これは委員会の中でも再三、町会だけ、そして町会の皆さんがそれを周知する責任はないんだということで言ってきたと思いますので、そこのところはこれからも検討していただきたいと思います。ですから改めて、ここを園舎として活用できない、貸していくという前提の前にそういう判断をされているはずですので、なぜ、そこが使えないのかということを改めて説明をいただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"ただ、その後、世界同時不況等の経済的な影響もございまして、当初の予定では平成２２年の４月からＴＯＣのほうに貸し付けるといった予定で話を進めてきたところですけれども、そういった諸般の事情によりまして、計画が若干おくれているといったところもあります。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"ここの建物の第一日野小学校を移転し、文化センターを併設して建てるに当たって文部科学省から交付金をいただいているということで、その交付金があって建物を活用できないというところがあるかと思うんですけれども、そのことについて正確な説明をお願いします。","respondent":"久保田行財政改革担当課長","answer":"ただ、その取り壊しの時期につきましても、ＴＯＣへの貸し付けと、あとその解体の経費等についてもＴＯＣのほうでご負担いただくということで、今、協議を進めてありますので、その企業としての支出の関係等もありますので、現在、速やかに取り壊しをしなければならないところ。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問・要望","question":"そのときに、２年間の暫定というところで、もしこれが経済状況、あるいは企業の側の判断で、いつも答弁は「２年で計画がされると思っています」ということしかないので、そのときには契約変更であるとか、そういった、そこに対する契約の変更あるいは解除、あるいはそういったものを検討するべきだと思うんですが、そういうお心づもりがあるのかどうなのか、お伺いします。","respondent":"日下部企画部長","answer":"ただ、これは仮にと、いろいろな経済情勢とかいろいろ、それはそれで全く抜きにはできない要素があります。ただ、少なくとも私どもはやはり２年以内に一定のめどが立つべきだと考えていますし、そういう方向でこれから調整する、このように考えます。","id":"exchange-013"},{"speaker":"井上委員","kind":"確認","question":"改めて確認します。そういう方向でということで、もし、いろいろな状況があってできなかった場合には、区としてはどうされるのか、そういった検討も含めて、されておくべきだというふうに思いますので、信頼関係とは別に、そういう経済状況とともに、企業としてはそういう判断というのもあるかもしれない。","respondent":"日下部企画部長","answer":"あまり仮定の話ということは私どもはしたくないんですが、少なくともそれはその時点、区としても適切な判断というのをやはりしていく必要があると考えております。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほかの企業というのは持ちビルの建て替えというのはもちろん自分の努力でやっていますし、それだけ地域に貢献した企業であればそれだけの収益を上げているわけですから、これまで地域からいただいたその利益を自分で使って、自分の自助努力で建て替えするというのはごく当たり前のことだと思うんですけれども、なぜＴＯＣだけ特別扱いになるのか、ほかの並ぶ区内経済に貢献した企業と、ＴＯＣがなぜ。","respondent":"久保田行財政改革担当課長","answer":"営業を継続することで、そういったテナントに入っている方々も営業を続けながらできるといったところは、非常にこの計画に協力する大きなメリットの１つであると考えているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"この移転経費というのは学校建築費なのか、第一日野小学校の建築費なのか、それとも旧校舎の建て壊しの費用なのか、今、どこまで交渉しているのか、そもそもこの移転経費なるものは、企業がちょっとお金出してくださいよと言って、やった、出してくれたという、そういう性質のものなのか、そこら辺がちょっとわからないのでお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"移転経費のお尋ねですけれども、こちらにつきましては、旧第一日野小学校につきましては立地も高速道路の横にあるといったところもありますし、校舎自体も築５０年を超える築年数を経ているということでございまして、いずれは改築、または移転等も必要であったということは。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと金額は協議中ということなんですけれども、その移転経費というのは何なのかというのが、だってもう既に新しい校舎が建っているわけですから、その建設にかかった費用を後から請求するということなのか、それともこれから建て壊しするところの費用なのか、そこら辺がちょっとわからないので教えていただきたいのと、あと、そもそもこういうＴＯＣをなぜ優先するんだという問題もありますけれども。","respondent":"久保田行財政改革担当課長","answer":"ＴＯＣの計画についてですけれども、概要につきましてはこれまでご説明はさせていただきましたけれども、営業を継続しながら建て替え計画を進めていくというところでございまして、それで、まず代替の駐車場が必要ということで。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"あわせていつから始まるんですか。それはさっきわからない、２年を越えることはないだろうと受けとめているということでしたけれども、明確にお伺いしたいのは、先ほどの質疑にもありましたように、ＴＯＣの建て替えが延びる可能性ももちろん否定はしなかったということだと思うんですけれども、２年過ぎてもだめだったら、いつまで、何年待つつもりなのか、そこもちょっとお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"時期につきましても、これまで繰り返しご説明をさせていただいてまいりましたけれども、今の暫定の駐車場の契約が２年ということでございまして、おおむね２年間延びるというふうに、今、話は進めているところですけれども、ただ。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"そういうふうにちょっと聞こえたので、どうなのかということでお伺いしたいのと、あと結局いつまで待つつもりなのかというのはわからないんですけれども、２年間で建て替えが実効しない場合は、じゃあ、いつまで待つのかというのがわからないんですけれども、結局品川区は計画が具体化するまで待つつもりだという受け止めでよろしいんでしょうか。お伺いします。","respondent":"久保田行財政改革担当課長","answer":"先ほどの私の答弁ですけれども、住宅の場合は協力しないといったふうには説明していないと私のほうは考えてございまして、今のように卸売業のオフィス、貸しビルであるということが基本でありますので、それに協力をしていきたいということでご説明をさせていただいたところです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、これが有効活用と言えるのか。ですから、私は２年間の暫定契約、もう即刻解除してもいいと思いますし、少なくともその暫定契約が終わったら本契約なるものは結ばないで、区民のための活用というのが必要だと思うんですけれども、そちらの契約の内容、暫定契約の内容、そしてこれから結ぼうとしている契約の内容について、改めてもう少し説明いただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"契約の内容ですけれども、暫定の契約につきましては、これも繰り返しご説明してまいりましたけれども、平成２２年９月６日から２年間という内容で、貸付面積も校庭部分の２,０００m2ということで、あとは駐車場として使用をするといった内容が書かれているところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"暫定契約の週末混雑解消の駐車場の話ですが、ＴＯＣから報告を受けているということでしたけれども、順調に伸びているんだということでしか説明がなかったので、もう少し具体的に、どれぐらい、今、この駐車場が埋まっているのかという状況を、報告を受けているということですのでおわかりだと思いますので、何％ぐらいとか、そういった稼働率みたいなものがあればぜひ聞かせていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"利用状況ですけれども、ＴＯＣのほうから報告を受けているものにつきましては、月間利用台数ということでご承知おきください。１０月につきましてはおおよそ６００台月間利用されているです。１１月が１,０００台、１２月が１,２００台ほど利用されていると伺っております。","id":"exchange-021"},{"speaker":"須藤委員","kind":"意見","question":"請願の中で、貸付計画を見直してというような表現になっているんですけれども、区としては、資料にあるように平成２２年９月６日よりということで貸し付けを開始されて、それなりの契約をされてきたと思うんですが、こういった契約をもし破棄してしまうということになると、それに対してはどういう形をとっていかなくてはいけないのか。","respondent":"久保田行財政改革担当課長","answer":"そういった中ではいろいろな事業の投資等もありますので、そういった賠償金というんでしょうか、そういったものの協議もしていかなければならないと認識はしています。","id":"exchange-022"},{"speaker":"須藤委員","kind":"質問","question":"この計画が議会のほうにも報告されてきて、大分時間がたってきているので、その間いろいろなお話をさせていただいて、契約についても９月にやりますけれども８月、それから１０月に報告をいただいてきているので、それが終わって、またそれを全部ちゃらにしてしまえということは非常に難しいことだろうと思って、暫定契約も本契約に準じてというか。","respondent":"久保田行財政改革担当課長","answer":"ただ、今回平成２２年４月からの計画の着手時期が若干おくれているというところもございまして、その間、混雑解消として２年間お借りをしたいという話がございまして貸していますので、この暫定の貸し付けにつきましても。","id":"exchange-023"},{"speaker":"須藤委員","kind":"意見","question":"いずれにしても、もう議会に報告があったときよりも、ＴＯＣ側が着工を出すこと自体がおくれているというのは、議会に対してもそうだけれども、やはり区民に対して疑問を呈する形になってくると思うので、そこはしっかり行政としてもいろいろな問題、疑念を起こされないように、議会からもやはりそれを承認して、本来４月から、それが延びて９月から、まだいまだにこうだよというふうになってくると。","respondent":"日下部企画部長","answer":"そういう点から申しますと、確かに２年間暫定という形をとりましたけれども、建て替えの計画についてやはりできるだけ速やかに、早目にその内容をしっかりと固めて、これを議会。","id":"exchange-024"},{"speaker":"須藤委員","kind":"意見","question":"そういう話までしてくれないと、待って何もわからないよという話で終わってしまうと思うので、ＴＯＣはＴＯＣで、今、区にも来ている、あるいは東京都にも折衝をしているというような、今、図面が少しずつ形ができるというようなお話をしていただければ、それなりに進めているなということは理解ができます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"石田委員","kind":"質問・要望","question":"そんな中で、今回請願が出ているこの地元住民をはじめ、区民の要望を聞く機会をつくってくださいというのが書いてあるんですが、これまでも町会合同で区のほうに説明をしていただきたいということで、区もわかりましたということで説明をされていますし、またその後の計画の際に、例えばＴＯＣと計画がまとまりましたと、そういったときには。","respondent":"久保田行財政改革担当課長","answer":"１０年後の活用等につきましても、きちんと私どものほうで、今の時点で未定ではありますけれども、活用の計画が決まりましたら、まず議会にはご報告を当然いたしますし、その後、住民の方等にもきちんと説明はしていきたいと考えているところです。","id":"exchange-026"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、特別養護老人ホーム、認可保育園等、五反田は確かに足りていない部分があるというのも、私も地元で活動している１人としても承知をしているんですが、これはあくまで今回暫定で２年間貸し出しをして、その後建て替えが実際行われる際には１０年間という中で、ちょっと先になってしまいますが、そういった際にはぜひ住民の声をしっかりと聞いていただいて。","respondent":"久保田行財政改革担当課長","answer":"私ども、こういった学校跡地の活用につきましては区民の貴重な財産ということで、都市部ではこういった大規模な土地をなかなか手に入れることはできないので、活用につきましては慎重かつ計画的に進めているところです。","id":"exchange-027"},{"speaker":"金野委員","kind":"質問・要望","question":"確かに暫定を含めて本格的になれば１０年というので、「１２年以上の長期にわたって」というこの表現が、現時点ではまだ本当に１０年なのか、暫定の２年というところまでしかまだわからないということで、いろいろな声を区の行政としてはできるだけ早く、仮に本契約に入ったとしてもこの１０年を１０年としないで、できるだけ短くしていくというお考えがあるのではないかと、またそこも要望したいですし。","respondent":"久保田行財政改革担当課長","answer":"暫定の期間が２年ということと、平成１７年のときにお聞きした計画ではおおむね１０年間ほどかかるということを聞いてありますけれども、私どもとしましては、やはり区民の貴重な財産ですので、それの有効活用を図っていくと。","id":"exchange-028"},{"speaker":"金野委員","kind":"質問・要望","question":"それをどういうふうにしていくかというところ、区民の皆さんのご要望の声は当然持たれていると思いますけれども、何せ明確になっていないというところで非常に皆さんの声が多いと思いますので、そこら辺のところを再度要望いたしますけれども、明確にして、できるだけ短い期間で建て替え工事なり、またその中の施設の一部の中にでも、区の要望が１つでも２つでも施設が使える。","respondent":"久保田行財政改革担当課長","answer":"今、いただいたご意見につきましては、きちんとＴＯＣのほうに伝えまして、今後の協議の中で工事期間はできるだけ短くといったこと、またそういった区民の要望を取り入れるようなことができるのかどうかといったことも踏まえながら、協議は続けていきたいと考えているところです。","id":"exchange-029"},{"speaker":"菊地委員","kind":"確認","question":"ちょっと確認させてもらいたいんです。先ほどの須藤委員の質問のときに、企画部長が相手に計画の明確化について働きかけていくという話をされていました。そういう中で、先ほどの答弁の中の相手に働きかけるといっても、じゃあ、働きかけって一体どういう中身を持つものなのかというところが、先ほどの答弁の中身だけではよくわからないです。そこをちょっとご説明を願えればと思います。","respondent":"日下部企画部長","answer":"やはり計画の内容、今、精査中ということではありますけれども、やはりできる限り早く具体的な、例えば施設計画でありますとか、また時期の問題も含めて、区民、それから議会のほうにご報告をできるだけ早くしていくに越したことはないわけですから、そういったことも含めて。","id":"exchange-030"},{"speaker":"菊地委員","kind":"意見","question":"今の中身でも、相手に働きかけることは幾らでも語りかけることはできるんでしょうけれども、実際に経済情勢となれば全然また次元の違う話になっていくんだろうと思います。今の部長の答弁の中でも、経済情勢の問題等々を考えていけば、いくら相手に働きかけたところで実質的な計画は生まれてこないんだと思いますので、そのことだけ申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"山路委員","kind":"質問・要望","question":"金野委員のほうからも質問をさせていただきましたが、総合的な判断で暫定契約でも実際にはスタートしているわけですけれども、早急に計画を明確にしていただきたい。区民要望を取り入れていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"１２歳の子どもからは思い出の地が駐車場になって悲しいとの声もあります。ＴＯＣの建て替えは、ほかの多くの企業がそうであるように自分の努力でできる範囲でマイペースでやってもらって、貸付計画は白紙撤回して、貴重な大規模公有地であるこの跡地は区民要望を第一にした活用に切り替えるよう求めまして、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"稲川委員","kind":"質問・要望","question":"私たち民主といたしましても、第一日野小学校跡のＴＯＣの駐車場に貸し出す見直しということが１点あると思うんですが、これは品川区としても計画性を持って進めていることだと私たちは思っております。これからもこの件に関してはバランスを持って、そして今後の保育園に関しては少子高齢化をしっかりと見すえた中で計画性を持って進めていただきたい。それは思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問・要望","question":"少し意見を述べさせていただきたいと思います。平成１７年に区は大きな政策判断をされたんだなと思います。例えばその昼間人口で４,０００人と先ほどおっしゃっていました。地域要望として、今回、請願が上がったような要望があります。もし、この先１年でＴＯＣがなくなるんだよというのがわかっていたとしたら、そのまちの生活が成り行かなくなるのかな。ですから、この請願に対しては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"結論は、現在の計画を見直してほしいということでしたので、請願には不採択という態度です。そのときには財政的な根拠を示して区民に理解を求めていただきたいと思いますので、そこのところを要望したのに、そのことに対して説明責任を果たさなかったということのないように、ぜひそこだけは気をつけていただきたいという意見で、不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-02","title":"２の報告事項を聴取します。 はじめに(1)、平成２２年度事務事業評価報告書","agenda":"２の報告事項を聴取します。 はじめに(1)、平成２２年度事務事業評価報告書","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"何点かお伺いしたいんですが、例えばまず評価方法のところで、ここに記載しているとおり、事業部みずからが評価を行った後に区首脳部が最終的な判断を下すということなんですが、事業部みずからの前に、例えば本当にここの事業部がこの庁内だけなのか、それとも例えば地域活動課とかは、事業部にしたら多分各出張所単位があると思うんですが。","respondent":"久保田行財政改革担当課長","answer":"ただその一方で、これまでの経過ですぐに平成２３年度に見直しが図れないといったものもございまして、そういったものにつきましてはやはり半年なり１年の猶予の期間の中で、廃止というわけではなくても、事業の改善等見直しを図っていかなければならないということで。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"今度の事業の見直しあるいは廃止などで、削減した経費というのは幾らぐらいになるのか、お伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"削減の費用の効果ですけれども、おおむね約２億５,０００万円から２億６,０００万円ほどの削減の効果があったというふうに見込んでいるところです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"いわゆる国でテレビなどでも大々的に報道された事業仕分けで、その財源捻出というのが非常に強調されていたわけですけれども、今回の区がやったこの事務事業評価というのは、その約２億５,０００万円という経費の削減というのを目的にしているのか、「選択と集中」というのがありますけれども、こういった削減できた経費をほかの鋭意推進すべき事業に振り分けるという形を目的にしているのか。","respondent":"久保田行財政改革担当課長","answer":"今回の評価の目的ですけれども、先ほどもご説明させていただきましたように全事業を見直すということでございまして、それによりまして行政と民間の役割分担の明確化を図っていきたいということ、またはそれぞれの事業の費用対効果を確認することで。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"資料に目的が３つ挙げられていましたけれども、その説明だったと思うんですが、ちょっと質問としては削減が約２億５,０００万円できたということなんですけれども、これを鋭意というか、これから拡充していくべき事業に充てるような目的、考えがあるのか、区としてはどういう考えを持っているのかというのをお伺いしましたのでお伺いしたいのと、あと今回、新年度予算がいわゆるマイナス予算というんですか。","respondent":"久保田行財政改革担当課長","answer":"削減効果の約２億５,０００万円のことですけれども、これをイコールで、Ａの拡充する事業に充当するといったところではなくて、ある意味全体の中でそういったところの見直しを図りながら、やはり選択と集中といったところを基本としておりまして。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、単純に人にかかる経費というのを算出できるのだろうかという疑問があるんですけれども、そこら辺に関してはどのように算出しているのかお伺いします。","respondent":"久保田行財政改革担当課長","answer":"これもできるだけ簡便にですので、一定の算出式、６月、７月の委員会の中でもご説明させていただきましたけれども、そういった一定の人件費等の算出式を設けまして、そこの中で算出をした結果を充てているです。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"算出式をご説明いただいたんですけれども、ちょっとどういったものだったのか改めて確認をしたいのでちょっとご説明いただきたいのと、あとまず今回のみずからの評価を踏まえて、来年度からは第三者を交えた評価ということで施政方針説明にもありましたが、どのようなものを今の時点で区としてはイメージしているのか、その中身というのがわかればお考えを伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"それと区民参加についてですけれども、こちらにつきましても現在、その仕組みについていろいろと検討しています。いろいろな参加の仕組みというものもあろうかと思いますけれども、具体的な内容については現在、検討しています。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"今、説明をされた中で先にお伺いをしたいんですけれども、先ほど区民意見の反映があるかと言われたときに、各所でシートを作っているということだったんですが、これはどういう項目のあるシートなのかということと、あと部ごとにそのシートは別なものなのか、同一のものなのかということを１つ伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"これにつきましては、７月２１日の本委員会のほうで資料としておつけしておりますけれども、それぞれの事務事業ごとに評価シートを作成するというものですので、枚数としては８７５事業あれば８７５枚あるといったところです。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問・要望","question":"今、コストのところで説明があったのは、常勤か再任用かということだったんですが、非常勤の職員がこのコストのところに入れられているのかということを教えていただきたいのと、あとちょっと全体のところで、まず４ページの評価方法４点目の丸のところで、「第二次評価で出た指示内容については、事業部経営会議で具体的な指示を行うとともに、企画財政課において」というこの評価の流れのところで。","respondent":"久保田行財政改革担当課長","answer":"そうしたものに基づきまして、特にＣ評価、Ｄ評価につきましては進行管理といったものが必要ですので、これらにつきましては企画財政課のほうにおいてきちんと抽出をいたしまして進行管理を行っていくというものです。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問・要望","question":"大きなところでこの冊子の６ページに「新たな評価の仕組みを検証」ということが大きな目的にあったんだろうなというふうに平成２２年度のところであるんですけれども、この冊子を見る限り、以前のものと体系があまり変わらないというところで見受けられるんですけれども、この新たな評価の仕組みの検証という、その検証のところで、どういう検証なのかということで、内容と成果。","respondent":"久保田行財政改革担当課長","answer":"そうした中で私どもが考えたのが必要性、代替性、効率性といった３段階の評価といったところで、できるだけその評価の仕組みをシンプルにしてきたところです。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問・要望","question":"それともう１点、このスケジュールの中で、９ページのスケジュールなんですけれども、８月下旬に事業部経営会議による第二次評価ということで、これが今年度の平成２３年度予算編成に反映されているということの目的の中に１つあったので、この時点でそういう行政としてこういう評価をしているのだということであれば、決算特別委員会にこれが活かされて、ともに区民の意見も議員が聞き取った上で。","respondent":"久保田行財政改革担当課長","answer":"公表の中間報告的なもののご質問ですけれども、私どもとしましても今後は区民参加といったものを取り入れていく中で、やはりある一定の段階でそういったものも必要ではないかなと考えているところではありますので。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど２つほど意見を申しまして、Ｃ方向での見直しの、その説明をぜひ載せていただきたいということと、成果について表記をしていただきたいという意見に対して、何かお考えがあれば、ちょっとお願いします。","respondent":"久保田行財政改革担当課長","answer":"今、ある事業をさらに推進するといった場合にはＡ評価というものをつけているです。そういったところを基本に評価をつけているというものです。成果のほうのことにつきましても今後の検討課題であると考えているところです。","id":"exchange-047"},{"speaker":"井上委員","kind":"確認","question":"今の答弁のちょっと確認なんですけれども、見直しのところで、見直しはＣというところで、これは特に廃止を視野に見直すというような表記がたまにあるので、そこのところはわかるんですけれども、どういうふうに検討を進めていくのかということまで踏み込んで表記をしてほしいということを、今、お伝えしたので、そのことについて、そういうことが難しいというのか。","respondent":"久保田行財政改革担当課長","answer":"Ｃの見直しの説明の表記の問題ですけれども、見直しといいましてもいろいろと見直しの幅が広いものがありますので、一律的に表記するというものは大変難しゅうございまして、我々もそういった課題というものは認識をしています。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問","question":"もし聞き漏らしていたら恐縮な質問なんですけれども、７月２１日に先ほどお話がありましたように説明いただいたときに、平成２２年度事務事業評価の実施についてというペーパーをいただいています。その中で、評価基準の中に必要性、代替性、効率性、今度の冊子だと５ページに出てくる部分と、それがもう少し前回のペーパーのほうが丁寧に書いてあった感じがするんです。","respondent":"久保田行財政改革担当課長","answer":"私どもは冊子をつくる際に、区民の方にできるだけわかりやすくということで冊子を作成してきたところですけれども、やはり委員ご指摘の点もありますので、冊子の中で改善するのもなかなかちょっと難しいところがありますけれども、例えばホームページで公表する際には。","id":"exchange-049"},{"speaker":"菊地委員","kind":"意見","question":"ちょっと１つだけ、今の鈴木委員の話とちょっと似通った話になってしまうんですけれども、それぞれにこの評価の基準があって、必要性ですとか代替性というのはある程度計っていけると思うんですけれども、一番わからないのが、効率性という問題で言うと、なかなか行政の仕事は効率性だけでは判断できない部分があると思うんですけれども、すべての事業について。","respondent":"久保田行財政改革担当課長","answer":"やはり全事務事業に対してこの３段階での評価をしていますので、効率性といったものもすべての事務事業の中で評価基準として判断をしてまいりました。","id":"exchange-050"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、例えば子どもたちの施策だとか高齢者の施策というのは、効率性の問題として、ここに書かれているものを見ると幾つかの判断の仕方が載っているんですけれども、そういう子ども、あるいは高齢者の分野については、この効率性の中でどの部分を重要視して評価を出したのかというのをお聞かせ願えますか。","respondent":"久保田行財政改革担当課長","answer":"効率性の考え方の基本は、５ページにありますように、投入された資源量に見合った結果・成果が得られたかといったもの、または最少の経費で最大の効果を上げているかといったものがやはり基本になってあります。","id":"exchange-051"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、今のお話だと、それぞれにこの効率性のところでも一体何を見てランクをつけてきたかというのは、１つ１つの事業について言えばすぐにわかるというふうに判断させてもらっていいんですか。これから、先ほどもあったように予算特別委員会で、そういう問題なんかも出てくるのだと思うんですけれども、ちょっとそこだけ最後にお願いします。","respondent":"久保田行財政改革担当課長","answer":"すべての事業について、この３段階での評価を経て評価をしていますので、その意味では高齢であるから、子育てのほうであるから特段何かそこで特別な配慮があったということはございません。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"繰り返し、今回の評価を踏まえて来年度活かしていくという答弁があるんですけれども、今回のこの区が行った事務事業評価と、来年度以降行おうとしているこの第三者を交えた評価との関係というのがどういうふうに活かしていこうというお考えがあるのか、もう少し突っ込んで聞きたかったので、１点だけ答弁をお願いいたします。","respondent":"久保田行財政改革担当課長","answer":"今後、今度は区民目線による区民参加の評価の仕組みというものを取り入れていきたいと考えているところですけれども、そうした中でどういった仕組みで取り入れていけばいいのか、また前回政策評価等でも外部評価の仕組みも取り入れたところもありますので。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"区民の参加によるという、今の安藤委員のところなんですが、どのぐらいからスタートするものなにか、内容もまだこれから詰めていくというものなんですけれども、時期はどのぐらいをめどに考えているのか、ちょっとそこだけ方針として出していただきたいです。","respondent":"久保田行財政改革担当課長","answer":"できるだけ速やかに進めていきたいと考えているところです。いろいろと作業の準備の手順等ありますけれども、新年度できるだけ早く進めていきたいと考えています。","id":"exchange-054"}]},{"id":"topic-03","title":"杜松小学校の跡地利用計画案にかかるパブリックコメントの実施","agenda":"杜松小学校の跡地利用計画案にかかるパブリックコメントの実施","exchanges":[{"speaker":"井上委員","kind":"意見","question":"少し戻ってしまうかもしれないんですが、申しわけないんですが、杜松小学校と荏原第四中学校のところで、杜松小学校は高齢者施設の整備ということであるんですが、すごく長期的に考えて、隣接する学校ということを考えたときに、荏原第四中学校はこれからですけれども、杜松小学校を高齢者施設にするという議論の中で、政策決定をするところの中で、敷地の広さとか近隣の関係とかを考えたときに。","respondent":"久保田行財政改革担当課長","answer":"は周辺状況の立地環境を考えますと、杜松小学校のほうが、特別養護老人ホーム等の整備をするに当たりましても、校舎を活用して整備するに適した場所だと判断いたしまして、杜松小学校のほうを活用することとなった次第です。","id":"exchange-055"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと確認ですけれども、２枚目以降のこれそのものがパブリックコメントにかかる資料になるのかどうか、お伺いします。","respondent":"久保田行財政改革担当課長","answer":"２枚目以降が、基本的にはパブリックコメントにかける利用計画案です。ただ、正確に言いますと、ここに応募の方法とかいろいろ載せしますので、これがそっくりというわけではございませんけれども、基本的な内容はこちらがパブリックコメントの対象になるものです。","id":"exchange-056"}]},{"id":"topic-04","title":"３の特定事件調査を行います。 はじめに(1)、公有地活用に関すること","agenda":"３の特定事件調査を行います。 はじめに(1)、公有地活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"在宅介護支援センターが一緒に入っていますけれども、これが移ってからの全体の活用になるのか、その前からこの分室のところだけは暫定活用するお考えがあるのか、お伺いします。","respondent":"久保田行財政改革担当課長","answer":"その後、地域活動課のほうが国勢調査を終わりますれば移転しますので、どういった活用をするかというところは、ちょっと今、三者で協議を進めているところですが、いずれにしましても有効活用は進めていきたいなと考えているところです。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"三者で協議ということですが、その三者はどこなのかということと、あとちょっと限られたところですので、いろいろ活用方法もまた限られてくるかと思うんですが、地域の住民の方のご要望というのは、そういった活用に当たってどのように反映されていくのか、そこら辺についてお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"それとあと、地域の要望というお話がございましたが、こちらの暫定活用をする際にもいろいろとご説明をさせていただきましたが、こちらの施設につきましては建築物の構造上、なかなか耐震の補強等が難しい施設であるということもございまして、そういったことを考えますと。","id":"exchange-058"},{"speaker":"安藤委員","kind":"意見","question":"わかりました。全体の介護支援センターが平成２５年の夏または秋までということですが、この建物自体がかなり古くなっているということですけれども、全体の活用計画というのは、区はいつぐらいからどのように検討していくお考えなのかお聞かせください。","respondent":"久保田行財政改革担当課長","answer":"ただ、引き続きこの平成２５年に今の暫定活用が終わりますので、それに向けまして、その後の本格的な活用に向けての方針というものは考えていかなければならないということで、現在検討を進めているところです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"現在もさまざまな条件を踏まえて検討をするということですけれども、なかなか近隣の方にとってはどういう条件があって、どういう制限があるのかというのはちょっとわからない中で、いろいろな要望とかそういうのはあると思うんですけれども、ぜひ検討する際に、そういった調査の結果なども十分に情報提供しながら、地域の皆さんの要望ですとかお声ですとかを踏まえて検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"須藤委員","kind":"質問","question":"それから八潮南のこみゅにてぃぷらざ八潮が２月からオープンしたけれども、利用者が少ないというような話も聞いているので、地域の声を聞けよ、聞けよと言って、そういうものがいいんだというけれども、結果的にそんなに利用がないよということでは、やはり区全体としての視野で見ていかないと、１つの建物をつくる、直すというものは非常に問題があろうかと思うので、今後ともそういうもので。","respondent":"日下部企画部長","answer":"地域の中でいろいろ自治会が中心になって、まちづくり検討委員会というのができまして、八潮南小学校、八潮南中学校、それぞれの活用ということでいろいろご提案をいただきまして、現在のような形で進めてきているという経過があります。","id":"exchange-061"}]},{"id":"topic-05","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"前回委員会で委員長からお示しいただいて、議論をしたわけですけれども、ちょっと４点目についてなんですが、前回お示しいただいたところで、「高齢者福祉施設の建設等」というところで幾つかの意見がありまして、私のほうはこのままこの「建設等」を残してほしいということでお話をさせていただいて、何人かの方からも同じような意見があったかと思いますけれども、この部分を「地域バランス」について。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"菊地委員","kind":"意見","question":"ただ、前回の行財政改革特別委員会は杜松小学校、荏原第四中学校まとめての話でしたけれども、前回委員長からお示しいただいた中身での議論があって、高齢者福祉施設というのが極めて大事な部分だということは皆さんの同じ意見があるところだと思うんですけれども、この施設配置の地域バランスというだけだと具体性のない中身になるのではないかと思いまして、できうれば高齢者福祉施設の建設等。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"須藤委員","kind":"意見","question":"もっと具体的にこれがいい、あれがいいと言い出すと、我々だっていろいろなことを言い出してしまうので、そういうことはなかなか難しいからということでこういう表現にさせていただいている。ぜひご理解のほどをお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"全会一致でという点では、自民党のほうからも荏原第四中学校のほうに老人保健施設などの要望が出ておりますところですし、「高齢者福祉施設等」というふうに入れても、そこが著しく限定とはならないと思います。皆さん一致できるところではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"須藤委員","kind":"質問・要望","question":"私はこれで結構だと思いますので、まとめていただきたいと思います。前回がどうのと言うけれども、前回はまだ杜松小学校、荏原第四中学校と２つという形があったので、ある程度「等」というか、高齢者福祉施設としてどちらかを、そういう区民ニーズが多いからそういう表現でもいいだろうと。よろしくどうぞお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"山内副委員長","kind":"質問・要望","question":"この品川区の将来の行く末といったところで、事務事業評価に関すること、そして公有地活用に関すること、そして施設のあり方に関すること、この３つを主に調査をさせていただいてまいりましたけれども、本当に皆様からたくさんの意見をいただき、そしてそれを理事者の方々にしっかりと受けとめていただいて、この品川区の将来といったものをしっかりと運営をしていただきたい。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/860991?Template=document&Id=5900#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":54101,"voices":162}},{"id":"h23-20110303-15","meetingId":"h23-cm03","date":"2011年3月3日","dateIso":"2011-03-03","committee":"環境対策特別委員会","time":"午前１０時０１分～午後０時０１分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"の水辺とみどりの整備に関することとしまして、河川浄化の現状","agenda":"の水辺とみどりの整備に関することとしまして、河川浄化の現状","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれのご説明、ありがとうございました。１点、そもそも論の話にはなるんですけれども、浄化対策を進めていく目的やねらいをどこに置いているのか、そこをちょっと伺いたいなと思うんですね。２点目ですけれども、結構な予算も使われているのかなと思いますし、品川区の地理的な事情といいますか、隣が海といいますか、そういうところから、でも、川はつながっているわけですからね。","respondent":"藤田水とみどりの課長","answer":"今回、私どもがやっている高濃度酸素溶解水、これについては大もとはダムの湖、ダム湖でやられていたような手法で、こういったものが使えないかということで、職員と、それから当時、検討の委託をしているところと検討しながら、何がいいんだろうかという研究をする中で。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"すみません、溶存酸素量のことでお伺いしたいんですけれども、立会川と目黒川の溶存酸素量、２つあるんですけれども、平成２０年は３で、平成１９年、平成２１年ということと、平成２０年が突出して上がっているんですけれども、それの前後関係というのがおわかりでしたら教えてください。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"調査はやはりその日のバックボーンといいますか、その日の天気ですとか、その日だけでなくて、河川の場合はその直前の雨だとか、そんなような状況とかもいろいろ関係があるのかなと考えています。ちょっと言い回しが変なんですが、要は、立会川の場合は３mmから４mm、１時間ですね、雨が降りますと、月見橋からいわゆる高濃度の汚濁物質を含んだ、有機物を含んだ汚水、下水道局は「雨水」と言っているんですけれども。","id":"exchange-002"},{"speaker":"大沢委員","kind":"意見","question":"その後、立会川、目黒川、各々、浜川橋、市場橋ということで、そこを定点で観測というか、調べているわけですけれども、この場所というのはどのような意図があって、この橋の周辺を選ばれたのか。環境がいいのか、わからないので。","respondent":"岩田都市環境事業部長","answer":"先ほどの説明の中でちょっとありましたけれども、シミュレーション上では１２台ぐらいは最低必要だろうということになっているんですね。そうしたら、最初から、実験ですから、１２台ぼんとやるわけにいきませんので、とりあえず品川区だけで単独で２台でやり始めました。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"１つは、合流式から分流式下水道へと整備の方針が変わってきたというふうに。改善についての進捗というか、進みぐあいというのは今後どのように行くのか。かなり遠い道のりというふうな印象を持っています。そういうので、３区連合で、落合浄水場から水を川に足すと、きれいな水を足すということで、３区連合の動きというのは、東京都も入っていますよね。国というのは期待できるんでしょうかね。","respondent":"藤橋都市整備下水道課長、藤田水とみどりの課長","answer":"しかしながら、今、東京都のほうで進めているのは、例えば面的な、いわゆるまちづくりの中で分流化ができるような場所があれば、分流化ができるかどうかを検討するといったことはやってあります。ただ、一方では、下で悪い分解が起こったときに、においが上がってくるようなケースがあるんですけれども、そこにふたをするような効果はあるんだろうということで考えまして、一定の効果はあるものの。","id":"exchange-004"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、今のご説明もありましたけれども、これは、微生物の戦いの説明があったんですが、量的な問題は影響しているのか、それをちょっと伺っておきたい。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"私もいっぱい流せばうまくいくんじゃないかなと思ったんですが、表面しか流れませんので、下の層へ酸素が供給されるわけではないんですね。ということで、やはり違う対策が必要なんだと考えています。しかし、それには約１００億円かかるということなので、それに立会川で成功した高濃度酸素溶解水を付加することによって、もう少し量的にも、費用的にも落とすことがどこまできるかということをこれから検討しようと、こういう段階です。","id":"exchange-005"},{"speaker":"阿部委員","kind":"確認","question":"頭の中でまだ理解しきれていない部分があるので、確認なりも含めて少し教えてください。それで、立会川の今後については、これはあれですか、第二立会川幹線ができれば、５０mmを超える雨というのは、事実上は年間そんなに何日も降らないでしょうから、そうすると、立会川については第二立会川幹線ができれば、高濃度酸素溶解水を流すことでほぼ問題は解決するだろうという見通しなんでしょうか。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"１点目のほうですが、委員の考えのとおりです。ただし、勝島運河のほうの水質の今、実験をこれから、港湾局がやっていますけれども、これも進めないとまだきれいになりませんので、それは次のステップの課題ということになろうかと思います。","id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"目黒川についてなんですけれども、目黒川のほうは、じゃ、合流改善ですとか、そういった設備的な意味で改善を今後、高濃度酸素溶解水の話がちょっと出ましたけれども、多分それだけでは追いつかないのかなと思いますが、目黒川については構造的に、要は汚水の出口のところというか、入り口と言ったらいいんですかね、川に入ってくるところを減らすという、そういう施策は今後あるのか。","respondent":"岩田都市環境事業部長","answer":"立会川の、第二立会川幹線の最終年度はまだ下水道局が公表しておりませんので、先ほど言った立会川直下の管が昨年やっと日の目を見たといいますか、公の場に計画として乗りましたので、これからいつできるかということが検討されることになると思いますけれども。","id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"最後のところなんですけれども、平成３５年までに合流式下水道の改善を行うという。これはどこかに限ったはで話なくて、品川区全体べったりと、面的に完成させるのが平成３５年ということでよろしいですか。","respondent":"岩田都市環境事業部長","answer":"日本全国です。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"要はどこかピンポイントではなくて、平成３５年までに。そうすると、河川に入ってくる汚れというのはかなり少なくなる。その上で、例えば、さらに汚い部分はどうしようかという、そういう段取りでいいですか。","respondent":"岩田都市環境事業部長","answer":"何も人工的にしなくても、そこの中の微生物が頑張ってくれて、自然の食物連鎖の中で浄化が図られている。ところが、合流式下水道が１００％完成したとしても、目黒川はだめなんですね。自然水がないですから、システムはできないんです。自然では。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問","question":"ごめんなさい、ちょっとしつこいようですけれども、釈然としないところがあって。平成３５年までに都のほうで合流改善をすることによって相当、根本のところは絶つことができる。そうすると、平成３５年以降も例えば高濃度酸素溶解水だけではなくて、海水とか大がかりなものを流していかないと、やはり浄化というのは図り得ないものになるんでしょうか。","respondent":"岩田都市環境事業部長","answer":"したがって、そこでさらなる、何を加えるか、あるいは立会川のようにもうやめちゃうか、あるいはさらに何かやるかというのは、平成３５年以降の水質の状況にあわせて対策を考えざるを得ないと考えています。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問","question":"１つだけなんですけれども、勝島運河水質改善実証実験の説明がありました。これ、今年度というふうにたしか書いていたと思うんですけれども、実験をいつまでやるかということと、それから、この目的は、実験ですから何か目的があると思うので、その実験と、それからこれをやったことでどういうふうにこの標準化につなげていくかという展開を、どう考えていくかということを今もしわかればお聞かせください。","respondent":"藤田水とみどりの課長","answer":"港湾局のほうで行っております勝島運河での実験ですが、実験の開始が昨年１１月、完了がこの３月ということで聞いてあります。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、東京都がそういうふうな計画があって、その中の一つとしてこの勝島運河を決めたということですね。あわせて品川勝島運河についてどういう計画をもってこれから対処していくのか、今の、現状でわかるようでありましたら教えてください。お願いします。","respondent":"藤田水とみどりの課長","answer":"私どもがこの間、確認ができているのは、まず、東京港全体で考えている。その実験のフィールドとして勝島運河をまずは選んだ。","id":"exchange-012"},{"speaker":"阿部委員","kind":"確認","question":"すみません、１点だけ確認させてください。海水を流したときに、海水というのは塩水だと思うんですが、それによって川の中の生態系への影響みたいなものはないんでしょうか。量的に少ないので、いいのかしら。","respondent":"岩田都市環境事業部長","answer":"ただし、淡水魚に戻るかどうかというのは、上流から真水を入れない限り、昔の目黒川のような生態系には戻らないでしょうから、それをどうするかは次の世代の方々に考えていただくしかないと。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"それでまた１００億円がどれだけ少なくなっていくのかというのは、また経過をとらえると思うんですけれども、いずれにしても相当な、２けた、３けたの、億円のお金がかかってくるということで、これの事業の実現可能性というのがどういうふうに。可能性がなければ、幾ら品川区独自で計画を立てても絵空事になってしまうと思ったので、そこら辺、どのように踏んでおられるんでしょうか。","respondent":"岩田都市環境事業部長","answer":"しかし、東京都は、目黒川だけではありませんので、東京都内いろいろな河川を抱えていますので、重い腰がなかなか上がらないということで、２年前から我々が実験開始以降、勉強会を東京都と一緒に何回か事務レベルでやっております。","id":"exchange-014"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"内容的なことではないんですけれども、この「記」としている１番の最初の１文だけが、ですます調になっているのがちょっとこう、リズムが悪いなという気がします。ほかのところが「めざすこと」みたいな形になっているので、「求められています」じゃなくて「求められている」で切ったほうがいいかなと。言葉の問題ですけれども。同じ１番のところ、「掲げた」の後の「、」はないほうがいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"これ、「ＣＯ２」の「２」は大きいのでいいんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"意味を逆に教えて。５番の「区民一人ひとりの省エネ行動の効果が、楽しみとなるような評価のしくみ」というのは、何、どういう。日本語としてちょっと理解できないので、どういう趣旨の文章。これ、どなたがつくったのかよくわからないけれども、「省エネ行動の効果が、楽しみとなるような評価」、ちょっとこれ、整理が必要。これ、理事者が見て、どう感じるのかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"若林委員","kind":"提案","question":"そうね。見えるということなんですか。いや、この文章を提案された方がどういう思いか、それを逆に聞きたい。だれですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"そういうことと、評価の仕組みというのを立て分けて文章にしないと。句読点をつけるとか。何かずらっと、ここまで評価となると、どこが大切なのかちょっと。楽しくなるようなことと、そのための評価というのはまた、運動とも違うんでしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"阿部委員","kind":"意見","question":"今のご意見なんですけれども、一般用語としては、ここにある「生」を使うのが一般的だと思います。ただ、状況によっては「活」などを使うこともありますが。例えば新聞なんかでは「生」のほうです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"最終的には任せますけれども、この「水とみどりの整備に関すること」の１のところで、「区民・事業者・品川区が力を合わせ」、「力を合わせ」という表現になっていますから、これであれば例えば「協力体制を構築し」とか、表現はお任せしますけれども、「力を合わせ」という表現はしっくりこないんじゃないでしょうかということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"２番は、これはだれに対して言っているのか。例えば品川区はというのをつければ意味は通じるんですけれども、これだけだとだれが何を言っているのかわからなくなりますので、それは表現の調整をお願いします。それから、４番のところの２行目、「公園などまとまったみどり」という表現になっていますよね。「公園等のみどりだけじゃなく」とか、そういうふうにしたらいかがでしょうか。意見ですから。","respondent":"飯沼委員長","answer":"１点目の「力を合わせ」のところ、文章表現を正副で、もう一回考えてみます。４のところは「公園などのみどりだけでなく」という感じですね。","id":"exchange-022"},{"speaker":"阿部委員","kind":"意見","question":"この部分なんですけれども、「まとまった」がなくて、「公園などのみどり」でも文章としては通じると思いますけれども、ここで言っている「まとまった」というのは要は規模の話ですよね。一定規模以上のみどりだけではなくという意図が多分、含まれていると思うので、そういう言葉が入ったほうがもしかしたらいいのかもしれない。実際に入れるかどうかはお任せしますが。一応そういうような意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]},{"id":"topic-03","title":"を行います。 マイガーデン南大井の区画数の変更","agenda":"を行います。 マイガーデン南大井の区画数の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"お伺いしたいのは、東京都が今まで無償で貸していたわけですよね。その東京都が無償で貸していた理由と、何で今回、有償に、要するに金を取るということに理屈が変わったのか。東京都はそこをどう説明しているのかご説明いただきたいと思います。東京都の言い分を説明というのも何か変な感じですけれども、要するに東京都が何と言ってきたのかということを説明いただきたいと思うんです。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"実は、今はもうなくなってしまっておりますけれども、豊町の道路予定地の中にも一時期、東京都のほうからお借りして、その遊休地をマイガーデンとして活用したという経緯もありましたので、それと同じような形で整備をし。その一環だろうと思うんですけれども、我々は、先ほど担当課長が言いましたけれども、抵抗に抵抗を重ねたわけですけれども、残念ながら時間切れで、これ以上引き延ばしますといわゆる行政財産の使用貸付でいきますと。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"後半の部長の説明ですと、単に、要するに特定の人になったからというよりも、そもそも前提条件が変わったのがわかっちゃったという、そういうことなんでしょうか。それならそれで、そういう事情があったというのを説明すべきだったかなというふうに思うんです。","respondent":"岩田都市環境事業部長","answer":"それに対して品川区は、少しのお金でもお金を取って、特定の人だけに使わせる利用の仕方は、東京都としてはそれは有償になりますよと、これが財務局の考え方で、頑として譲りませんということなんです。","id":"exchange-025"},{"speaker":"川西委員","kind":"質問・要望","question":"希望的な意見ですけれども、豊町が廃止になって、ここへ来ました。区画が減るということになると、やはり区民の要望からすると、さびしいことだと思いますので、今後どこか探してあげていただきたい。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"とりあえず時間切れということだったんですけれども、今後また何か、ネゴシエーションの可能性があるのかないのか。財務局が一番強いというのはわかるんですけれども、逆に品川のようなところで農業に親しむような活動をするというのも、東京の農産物を広めようとか、いろいろな活動も逆に東京都では予算がついているわけですから、そちらのほうから攻めていけないかなと思います。","respondent":"岩田都市環境事業部長","answer":"東京都の事業で緑化事業とかいろいろやっているわけですけれども、財務局の考えでいきますと、これは品川区から取り返して、おそらく駐車場として経営させることを考えているんだろうと思うんですが、そこはさせないで。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、区としては公園にするような予定でいらっしゃるんですか。","respondent":"藤田水とみどりの課長","answer":"東京都の求めはそういうことでございまして、今回、貸し出しをやめ、今後、広場等にしていくわけですが、しばらく、お金もありませんので、そこの場所は植え込み、あるいはほかの公園で木を一時、仮植えしなければいけないというようなときになったときの苗圃といいますか。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/316742?Template=document&Id=6204#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":35527,"voices":107}},{"id":"h23-20110307-3","meetingId":"h23-c-budget","date":"2011年3月7日","dateIso":"2011-03-07","committee":"予算特別委員会","time":"午前１０時０３分～午後６時４３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井桁副委員長","kind":"質問・要望","question":"第１項、理事および理事会の設置についてです。１人当たりの質問時間は、答弁時間も含めて１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。無所属の委員の質問時間は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"確認","question":"私は、８７ページ、任意予防接種の点、１０１ページ、教育センター運営費の点で、伺いたいと思います。はじめに、任意予防接種のところ、過日の品川区のホームページ、あるいは、新聞等で全国的な報道、発表資料もあわせて、伺いたいと思います。この補正に計上されている中で、肺炎球菌、新型インフルエンザワクチンのところで、補正というくくりの中で、全体の流れの中での実施時期の確認。","respondent":"吉田保健予防課長","answer":"補正の肺炎球菌ならびに新型インフルエンザワクチンについてのお問い合わせですが、肺炎球菌につきましては、大変希望者が多いということでございまして、今回、約１万人分を補正する予定です。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"厚生労働省からの通知が、今、報道資料等ということでありました。そういう中で、過剰な反応をすべきではなくて、正確な情報をもとに冷静に対応すべきという思いを持っています。この補正の中で、それぞれの接種費用の助成も含めて、開始時が昨年９月、１０月とありました。これまでの品川区内の接種者の状況を伺いたいと思います。それぞれ、どのような人数がいらっしゃるのか、教えてください。","respondent":"吉田保健予防課長","answer":"おおむね予定どおりといった内容です。それにあわせて、ほぼ同時期に実施しております肺炎球菌につきましては、当初、伸びが大変あったわけですが、現在、少し落ちておりまして、予定の約４割程度、１万５,５００人程度といった内容になっております。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やはり、導入時から、とても地域要望が多かったと思います。そういう当事者への、その後の情報提供、あるいは、それぞれご家庭で考えたら、確認をしたいという思いが強いと思うんです。この見出しだけが走ってしまって、不用意に、ワクチン自体のあり方に不安だけが広がることは、決して好ましくないと思いますので、そういった点の対応策を伺えればと思います。","respondent":"吉田保健予防課長","answer":"私どもといたしましては、明日、国が開催を予定しております有識者会議等の意見を踏まえまして、例えばホームページにＱ＆Ａを掲載する、あるいは、医師会等に、情報提供を適切に行って、接種の際、あるいはお問い合わせの際にご対応いただくということを考えています。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問","question":"次に行かせていただきます。教育センターの運営費のところから、伺いたいと思います。教育センター自体が、教育相談の事業、あるいは学校関係者による利用と、自分は承知をしています。やはり立派な複合施設の中の一つということで、まだまだいろいろな活用の余地があるのか、どうかという方向性も聞きたいので、現在状況と、今後の展開と、教育センター自体のあり方を伺えればと思います。","respondent":"冠木指導課長","answer":"今回、カウンセリングの部屋であるとか、相談の部屋であるとか、充実をした施設としていますので、今後も、この五反田の教育センター内の教育相談を十分に利用していただけるようにＰＲしてまいりたいと考えています。","id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"そこで、こうした予防ワクチンを推進する立場から、区民の皆さんのワクチンへの不安、こうしたものがありますので、今後の対応について、要望も含めて、幾つか確認をさせていただきたいと思います。厚生労働省より、接種の一時見合せという通達が出されていますけれども、先ほどもご説明が少しありましたけれども、その内容、そして、その内容から、品川区の対応はどのようにされていますでしょうか。","respondent":"吉田保健予防課長","answer":"その通知がございましたのが、実は、３月５日の午前０時でございまして、それを受けまして、品川区の対応といたしましては、当日の６時半には、もう医師会等に連絡を取り、調整を行っております。","id":"exchange-006"},{"speaker":"金野委員","kind":"質問・要望","question":"そこで、今も、医師会の方と連携を取ってということでありましたけれども、解明されるまでの間、どのような態勢をとっていくのか、ありましたら、教えていただきたいと思います。","respondent":"吉田保健予防課長","answer":"速やかな対応ということが求められますので、ホームページ、あるいは医師会等へ情報をまず流すことを考えております。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問・要望","question":"ですので、この厚生労働省からの見解が公表されましたら、速やかに、正確な情報を皆さんにお知らせをしていただくとともに、きめ細やかな対応をお願いしたいと思います。これまで以上に、ワクチン接種の安全性の確保に取り組むように、国への要望も、ぜひお願いしたいと思います。ご見解をお願いいたします。","respondent":"吉田保健予防課長","answer":"ただ、国への要望ですが、既に東京都が国に要望をするという内容もありますので、現在のところは、有識者会議もこれからといったところですから、その内容等を見極め、対応していきたいと考えております。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"東京都からの要望はあるかもしれないですけれども、やはり区民の皆さんの、というところでは、区からも声を挙げていくということは必要ではないかいと思いますので、よろしくお願いしたいと思います。先日の本会議等でも、他の議員より質問がありましたけれども、今の工事の進捗状況、改めてその確認をさせていただきたいと思います。この２線について、工事の今の進捗状況を教えてください。","respondent":"藤橋都市整備下水道課長","answer":"補助１６３号線につきましても、現在、区役所から２６号線の南側につきましては、来年１２月末の完成に向けて、電線類の地中化を進めているところでございまして、計画どおり進めているところです。","id":"exchange-009"},{"speaker":"金野委員","kind":"質問","question":"補助２０５号線のほうですけれども、今、仮の横断歩道もつけながら整備が進められていると思うんですけれども、工事の最中、ちょっと事故などが起きているということも耳にしております。特に補助２０５号線のほうのカーブの部分、その点、ご存じでしたら、交通安全対策をぜひお願いしたいと思うんですが、いかがでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"これまでも補助１６３号線、補助２０５号線については、地域の皆様方からの声もありますので、私どもといたしましては、工事の安全確保に十分に気を配りまして、今後も対応します。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"私から、１３０ページの国民健康保険事業会計と、１６８ページの後期高齢者医療特別会計について、保険料徴収について、お伺いしたいと思います。私は、高すぎる国民健康保険料、ますますひどくなる区民生活の実態がそこにあると思いますけれども、品川区は、この点をどう分析されていらっしゃるのか、お伺いいたします。","respondent":"本城国保医療年金課長","answer":"今回、補正予算でお出ししていますのは、国民健康保険の保険料につきましては、例年、当初としては９０％超の保険料を見込んでいるところですが、この最終補正の段階で、実態に見合った保険料の収納ということで、このような形で計上しているものです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"私は、生活実態にしっかりと目を向けるべきだと思います。病院での窓口負担が１０割となる資格証の発行について伺いますが、平成２１年度は１２４世帯だと伺っておりますが、平成２２年度は、現在、何世帯なのかお伺いしたいと思います。あわせて、現にアパートなどで生活しているにもかかわらず、郵送で資格証を送っているという状況があると伺っておりますけれども、どういう場合に郵送で届けるのか。","respondent":"本城国保医療年金課長","answer":"資格証明書の発行件数ですが、現段階では１５０世帯となっているところです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"資格証の発行は、一度、訪問するというご説明がありましたけれども、その中で、会えていないのに、資格証を郵送しているという件数があるのか、お伺いしたいと思います。なぜならば、２００８年１０月３０日の厚生労働省の通達で、資格証の発行について、「機械的な運用を行うことなく、特別の事情の有無の把握を適切に行った上で行うこと」とあります。","respondent":"本城国保医療年金課長","answer":"現に、通院されているという関係ですが、国民健康保険の資格証の発行にあたっては、特別な事情によって納付できない場合は、基本的に対象外とするということで、例えば災害等であるとか、病気によって働けないことによって滞納されている状況なども、特別な事情の中で勘案して。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"自宅に出向いているとのご説明はあるんですけれども、そこで本人に会っているのか。本人に会っていなくても、資格証を郵送しているという事例があるのか、そこをご説明いただきたいと思います。","respondent":"本城国保医療年金課長","answer":"ただ、資格証の発行自体、最終的な段階での手続ということで、長期の滞納が発生してから、その間、電話、文章等々、再三やった結果、私どもとしてできる範囲のことをやったうえでの手続ということで、ご理解いただければと思います。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"厚生労働省の通達でも、相手の生活事情といいますか、特別な事情の有無の把握とうたっているにもかかわらず、なぜ会えてもいないのに、生活状況がわからないのに、結果的に資格証を送るということをするのか、これは改善すべきだと思いますけれども、いかがでしょうか。それから、あわせて、私のところに寄せられる相談の中に、何人も、保険証を持っていない無保険の方がいらっしゃいました。","respondent":"本城国保医療年金課長","answer":"特別な事情がわからないのに、という関係のご質問だったと思いますが、国のほうも、可能な限り状況把握に努めるということで、その中で、区としては、郵送等の手続だけにしないで、必ず訪問して、会えない場合は、その中に手紙を入れるとか。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういう場合は、どういう対応をしていらっしゃるのか。つまり、今は、区民が持っている保険証の期限が切れる前に、相手の手元に保険証が届くのか、そういう仕組みがあるのか、ご説明いただきたいと思います。実際に私のところにきた、保険証を持っていない方の状況をいろいろ伺うと、こういうところに無保険の状態が生れてしまうのではないかと、疑問に思うんですけれども、その点はいかがでしょうか。","respondent":"本城国保医療年金課長","answer":"基本的には、今、ご説明させていただきましたように、すべての方に、短期証を含めて、何らかの種類の保険証が届くような形にしています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"短期証のほうですけれども、先ほど、伺ったのは、相手の方が持っている保険証の期限内に届けられるのか。結局、期限が切れてしまったら無保険になるわけですから、その状況がわからないので、ご説明いただきたいと思います。なぜこういう状態が生れてしまうのか、私は疑問に思うのです。結局、品川区にため置き状態があるのではないかと思うんですけれども、いかがでしょうか。","respondent":"本城国保医療年金課長","answer":"これも再三の繰り返しのご説明になってしまいますが、すべての方を対象にして保険証は郵送をさせていただいているところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局、保険証の期限というのは、品川区自身は把握をしているわけですから、相手の方に、期限が切れる前に届けているという状況は、先ほどからの説明でも、よくわかりませんでした。現在、何件の発行が行われているのか、伺いたいと思います。保険証の期限が切れてしまっているという事態は起きていないのか、あわせてご説明いただきたいと思います。","respondent":"本城国保医療年金課長","answer":"後期高齢者医療についての短期証の発行ですが、現在、全部で１３名に発行しています。短期証発行にあたっては、すべての方と納付相談等を通じて、状況把握のうえ発行しています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"よくわからないんですけれども、後期高齢者医療制度のほうは、相手に会えないという事例はないということなのでしょうか。国民健康保険の短期証のほうですけれども、期限が切れるタイミングで送ってしまったら、切れてしまうと思いますので、そこはどうなっているのか伺いたいと思います。暮らしの実態をよく見ていただきたいと思いますけれども、いかがでしょうか。","respondent":"本城国保医療年金課長","answer":"短期証の発行自体、趣旨といたしましては、なるべく可能な限り、交渉の機会を設けるという趣旨で発行していますので、先ほど、ご質問がありました、１３名の後期高齢者医療の方は、今回の機会にすべて納付相談をやらせていただいたうえでの短期証の発行となっているところです。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"５０ページ、国庫補助金、社会資本整備総合交付金、先ほどもご説明いただいたんですが、もう１回、ちょっとお伺いしたい。それから、６２ページ、都補助金ですか、土木費補助金、そして、９７ページの都市防災まちづくり事業費、更正減額について、この辺、お伺いしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"社会資本整備総合交付金に移行したのが、平成２２年度でございまして、当初予算でほかの個別の費目で計上していたものが、国の制度が変わって、社会資本整備総合交付金と変わりましたので、当初予算の分をまず削除いたしまして、新たに計上し直すのですが、今年度。","id":"exchange-020"},{"speaker":"稲川委員","kind":"質問","question":"ということは、間違っていたらすみません、今度、平成２２年度から、社会資本整備総合交付金というのができたということは、平成２３年度から、例えば都市防災不燃化促進事業とか、そういったものは、節としてはなくなってくるという判断でよろしいのでしょうか。","respondent":"金子企画財政課長","answer":"これは、予定によりますと、平成２３年度につきましては、都道府県段階で実施を行うということになっております。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問・要望","question":"ちょっとわからないところを聞いてしまうのですけれども、５３ページに、充当事業と書いてありまして、密集市街地整備促進事業、都市防災不燃化促進事業とか、防災生活圏促進事業と書いてあるんですけれども、ここで減らされた額は別にイコールでもない、どういう状況がここに書かれているか、教えていただきたいんです。","respondent":"品川防災整備担当課長","answer":"ご説明いたします。５１ページのほうですが、こちらのほうは、今まである予算を、社会資本整備総合交付金のほうに移すというマイナスです。実際に、５３ページのほうですが、この中で、一部金額が、移した金額と違うものがあります。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"次にいきます。わからないことがありますので、また聞きます。６２ページの、都補助金の中に、土木費補助金というのがあります。そこに、５節都市防災不燃化促進事業助成費と、密集住宅市街地整備促進費、この２点がマイナスで、実績見合いで減額をしたということなんですけれども、この中で１点、防災生活圏促進事業というのがないんですけれども、これはどうしてないのか、教えてください。","respondent":"品川防災整備担当課長","answer":"説明が少し不十分だったようですが、防災生活圏促進事業につきましては、今回、補正の減額はしておりません。避難道路機能強化事業のほうかと思われるんですが、こちらについては、国費のほうを減額しておりまして、都費のほうは減額しておりません。","id":"exchange-023"},{"speaker":"稲川委員","kind":"質問","question":"はい、ありがとうあります。最後に、９７ページの都市防災まちづくり事業の更正減額についてなんですけれども、国の補助金、都の補助金のことについて、いろいろお伺いしました。その中で、減になってしまったというのは、私も非常に残念という思いでいるんですけれども、実際に、何で実績が下がってしまったのか、教えてください。","respondent":"品川防災整備担当課長","answer":"用地の購入に時間がかかった理由としまして、地権者が亡くなった関係とかで、相続の関係がありまして、例えば相続人が、大体５人から６人いますと、その方々一人ひとりにこの話を持っていって、交渉をしたりとかいうことがありまして、この辺の関係で時間がかかったです。","id":"exchange-024"},{"speaker":"稲川委員","kind":"質問","question":"さっき、公園の整備と言われたのですが、厳密には、防災広場ということでよろしいのですよね、防災関係で。それから、土地の購入ができなかったということなんですけれども、基本的には、もう道筋ができていて、あとは事務的な処理が終われば、すべて順調に進むという解釈でよろしいですか。","respondent":"品川防災整備担当課長","answer":"地権者の合意が取れて、それ以降、事務的な手続に関しては、予定どおり進むということで間違いがございません。ただし、やはり用地交渉の段階では、いろいろ手間がかかるところがあります。","id":"exchange-025"},{"speaker":"沢田委員","kind":"質問","question":"私は、４６、４７ページ、８６、８７ページの生活保護費について、それから、８８、８９ページの保健指導費の不妊治療費助成について、それから、９６、９７ページの都市開発費について、お伺いいたします。そのうちの高齢者世帯の割合はどれぐらいでしょうか。ここ何年か、生活保護受給世帯が増加している中で、高齢者世帯の割合がどう変わっているのか、お伺いいたします。","respondent":"平澤生活福祉課長","answer":"平成２１年になりますと、４,１４５人で、６５歳以上の方が全部で２,２９３人となっております。こういったところで、受給者につきましては、この間だけなんですけれども、７４９人の高齢者世帯が増えているです。","id":"exchange-026"},{"speaker":"沢田委員","kind":"意見","question":"今回の補正で、国庫支出金の増額に伴って更正減額を行っておりますが、これは国の問題になってしまうかもしれないのですけれども、今後の区としての見通し、新年度以降、国庫支出金はどうなるかということがわかれば、お聞かせください。","respondent":"平澤生活福祉課長","answer":"その後者のほうにつきましては、これから高齢化がますます進展していくということもありますし、お年を召した方で生活保護になられた方につきましては、自立というのは非常に難しいということになりますので、引き続き少しずつは増えていくということが考えられます。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"そういう厳しい中で、少しでも不正受給者をなくしていくことは、窓口業務を行っている区としては大変重要なことだと考えています。品川区としての、窓口での対策は、今現在、いかがでしょうか。受給者に対する就労支援や、先ほどお話がありましたけれども、生活実態の現状、それから、生活保護費の使われ方の調査は、どのような形でやられているでしょうか。","respondent":"平澤生活福祉課長","answer":"委員、ご指摘のとおり、こういった制度につきましては、区民の信頼がなければ制度そのものが立ち行かなくなってしまうということもありますので、開始日の調査、それから、支給中の調査ならびに支援、それから、使い道というのは、生活保護費につきましては。","id":"exchange-028"},{"speaker":"沢田委員","kind":"質問","question":"不妊治療費の助成について、お伺いいたします。品川区におきましても、平成１８年度から、国が助成を出す特定不妊治療に加えて、一般不妊治療に対しても助成を行ってきました。今年度は、予算では２８０件ということでしたけれども、補正で６７５万円の追加になったということは、結局、何組ぐらい不妊治療を受けられたのでしょうか。","respondent":"山岡健康課長","answer":"区としましては、少子化対策の一つとして実施してまいりまして、毎年増えておりますので、今後も引き続き、この事業については力を入れていきたいと、そういうふうに考えているところです。","id":"exchange-029"},{"speaker":"沢田委員","kind":"意見","question":"今後、さらに少子高齢化が進む中で、私もこれから頑張っていきたいと思っているんですけれども、これは、国家的な問題ではありますけれども、子どもを産みたいのに、医学的に産むことができない夫婦に対して、行政が少しでもサポートをしていくということは、とても大切だと考えています。今後、予算的な部分でどうなっていくのか気になるので、今後の区としての見通しについて、お聞かせください。","respondent":"山岡健康課長","answer":"これは、制度をやって、予算がなくなりましたから、今年度はおしまいというわけにはいきませんので、必要な額を予算化してまいりたい。今回のように、補正でお願いすることも、今後もあろうかと思います。","id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"ぜひとも、これからもよろしくお願いいたします。次に、都市開発費について、お伺いいたします。市街地整備事業費の大井町西地区再開発事業補助金以外、すべて減額になっていますが、こういうものだと言われたら、そうなのかもしれないですけれども、これはどういうことなのでしょうか。","respondent":"三宅都市開発課長","answer":"今こちらの事業、権利変換計画の合意形成をやっている最中ですけれども、そちらの作業に時間がかかったため、移転補償費などの支払いが年度内に執行できないということになりまして、すべて減額しまして、平成２３年度に再計上するというものです。","id":"exchange-031"},{"speaker":"沢田委員","kind":"質問","question":"北品川五丁目の整備以外にも、ほかの事業についての減額は、どういうことなのでしょうか。","respondent":"三宅都市開発課長","answer":"次に大きいところでは、都市再生総合整備事業ですけれども、大崎駅西口駅前交通広場整備工事（Ｃ地区デッキ）ですが、こちらに関しましては、予定工事費よりも落札が３割低い価格であったとか、整備内容についても、暫定整備可能な予算としておりましたけれども。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"９２ページ、中小企業対策費のところと、もう１件は、人件費に関して、１０２ページか１０３ページか、学校給食費のところを例にとって伺っていきたいと思います。予算というのが１０月の段階で決まって、来年度、例えば給食を委託するという考えがあった場合でも、当然、区の職員がもともといらっしゃるわけですから、その部分、給与費で乗せなければならないのはわかります。","respondent":"田村庶務課長","answer":"教育費だけなく、すべての事業について、そういうような考え方であります。委員、ご指摘のとおり、調理代行が予定どおり進んですので、それは平成２２年度の予算の中に、調理代行の委託分というのが含まれております。","id":"exchange-033"},{"speaker":"渡部委員","kind":"確認","question":"そうしましたら、もう１回、確認だけで結構です。平成２２年度の当初予算の段階では、当然、新たに平成２２年度から始める外部委託の経費ものせてあるし、実際には給食職員としてはいないであろう人の分も、とりあえず区の職員であるから、どこに割り振っていいかわからないという言い方は変ですけれども、確定していないから、そこにのせてあるということで、よろしいでしょうか。","respondent":"田村庶務課長","answer":"今の委員のご指摘のとおりです。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。というのは、実はこれは足し算、引き算していくと、給与費、いろいろな問題があって、その予算との差異は出てくるんですけれども、これは全般的な話ですが、今回の補正で、区の職員全体の人事や何かすべて反映して、給与費は、退職された方は別ですけれども、そうでない方は、ほかの部署なりにすべて反映されているんでしょうか。","respondent":"榎本人事課長","answer":"今回の最終補正の人件費の関係ですけれども、全体を説明しますと、職員の給料で、９,４３８万円の減額補正をしております。退職手当を除く職員手当で、約１億円の減額補正をしています。","id":"exchange-035"},{"speaker":"渡部委員","kind":"質問","question":"今さらだったのですが、ちょっと見方がわからなくなるものがあったので、伺いました。９３ページです。午前中の説明の中でも伺っていたんですが、中小企業対策費で、商店街活性化事業更正減額が、約２,１００万円挙がっています。事務事業概要等を比較してみますと、空き店舗活用支援事業はほぼ皆減に等しいのかなと思うんですが、これは、何か予定が狂ったのか。その辺、ちょっと教えていただけますか。","respondent":"諸岡商業・観光課長","answer":"１件につきましては、実施されておりますけれども、１件につきましては、その後の家賃交渉等がうまく進まなかった等々の理由で、今年度については見送りたいということで、２件予定しておりましたところ、１件のみということになったものです。","id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"小規模商店街は、私の近所の商店街でも行っておりますが、やはり支援をいただいたからというのではなく、昔からの継続というのですか、この支援をいただいたから、やっぱり頑張ろうということで、その商店街の方々は力を合わせて頑張っております。いわゆる区内に小規模商店街と思われるところがどのぐらいあるのか。こういう支援を受けさせてほしいと手を挙げているところがあるのか、教えてください。","respondent":"諸岡商業・観光課長","answer":"今後ですけれども、平成２２年度、今、１商店街におきまして、コンサルタントに入っていただきまして、再生モデルのモデルづくり、今後、どんな事業を行っていくかということで、アドバイスをしながら、来年度に向けて事業を計画されています。","id":"exchange-037"},{"speaker":"浅野委員","kind":"質問","question":"たしか平成２２年度の予算には記載がなくて、平成２３年度の予算が５５６万円になっていたと思いますけれども、これは、平成２２年度に費用が発生をしたのか、どうかというところを、まずお伺いしたいと思います。そして、都補助金の地域活性化・住民生活に光をそそぐ交付金、先ほどの説明の中で、定住外国人向けのホームページの改正と伺ったんですけれども、もう少し細かい内容を教えてください。","respondent":"間部高齢者いきがい課長、中川原広報広聴課長、本城国保医療年金課長","answer":"この空調機につきましては、広間についている水冷式の冷房機でございまして、昭和４９年の開設時から設置していたということで。これは、在住外国人に必要な情報として、既にＣＡＴＶの番組で制作済みの生活情報番組を、英語、中国語、韓国語、タガログ語の４カ国版に編集し直しまして。いずれも、特定健康診査については、平成２１年度はかなり落ち込んだところでございましたが、平成２２年度については。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"小山シルバーセンターの暖房機のところなんですけれども、もう一つ質問が中に含まれていたんですけれども、平成２３年度にこの暖房機と空調機の取替工事ということで予算計上されている。それから、先ほどのこちらのホームページ等経費と書かれている部分ですが、今のケーブルテレビ関係の、外国人に対します対応ということで、伺いました。","respondent":"金子企画財政課長、山岡健康課長、中川原広報広聴課長、本城国保医療年金課長","answer":"今回、債務負担行為は、補正で２９件、お願いしておりまして、そのうちの２１件を、平成２３年度に早期に発注できるようにということで。契約上、いろいろと苦労している部分もあるということは聞いておりますけれども、受診状況については、特に情報は入ってきておりません。現在の品川区の公式ホームページの写真ニュースにおける外国語翻訳の不具合のことですが、これにつきましては。","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問・要望","question":"小山シルバーセンターの計上の件、理解しました。ホームページの件は、これで終わります。それから、この前、特定健診を受けていない方への通知を、２回から３回に増やしたと伺った記憶がありますけれども、それ以外のいい方法というのでしょうか、さらに受診を勧奨するような方策を、ぜひとも考えていただきたいと思うんですが、何らかの方策が、追加であれば、教えていただきたいと思います。","respondent":"間部高齢者いきがい課長、本城国保医療年金課長","answer":"小山シルバーセンターの空調機の取替時期のお話ですけれども、現在のところ、施設整備課と調整をとりまして、５月２７日が工期ということですので、多分、５月第３週には終了しまして、衣替えの時期には間に合うということで。特定保健指導のほうの実施率の関係ですが、約１８％程度を見込んでいるところです。それから、特定健康診査につきましての未受診者への勧奨ですが、平成２２年度から１回増やして３回にしたところです。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"４０ページ、特別区民税、６６ページ、基金繰入金、７５ページ、基金積立金の追加、７７ページ、地域振興基金積立金追加分。特別区民税について、お伺いしますが、これは補正していますが、その理由を説明してください。","respondent":"武内税務課長","answer":"その後、平成２２年度においても、経済の状況が不透明ということで見積もっている中で、今回、調定額に対して、１１億５,０００万円という金額が、確実に区税として入るという見込みができましたので、補正をさせていただきました。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問","question":"わかりました。税金が増えて、財政調整も増えて、基金の繰入れをとめていると思うんですけれども、三者がこういう間になって、今回の補正のポイントというのは何でしょうか。","respondent":"金子企画財政課長","answer":"事業を執行させているうえで、当初見込みを上回る必要が生じた、あるいは逆に、当初見込みを下回ったために減額する必要が生じた等々、幾つかのものがありますが、いずれにしましても、当初の時点では予測できなかったことについて。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"６６ページから始まる各基金の繰入金が大幅に減になっているんですけれども、改めて、そこの説明。それから、７５ページから始まる基金の積立の追加なんですけれども、財政調整が４億２,６００万円、その下の下の公共施設が２２億８,４００万円と、かなりの額を積み立てしておりますが、今回の積立ての理由といいますか、原因についてお伺いしたい。","respondent":"金子企画財政課長、秋山協働・国際担当課長","answer":"違うものというのは、例えば普通財産貸付で、旧総合体育館のところが、半年の予定が１年貸すことになったということから、貸付料等について、ここに上乗せしているのと、これの大部分を占める４億円というものは、年度末に至りまして。地域振興基金の積立金ですけれども、今年度、１３０万円補正をさせていただきました。これについては、法人等からの寄附が、当初予定したよりも増ということで、補正をさせていただきました。","id":"exchange-043"},{"speaker":"藤原委員","kind":"質問","question":"地域振興基金のほうからいきますが、スタートに対しての助走だと、自分は思っているので、この事業をいかに一人立ちさせるかというところがポイントだと思うんですが、その辺について、いかがですか。それから、基金の積立なんですけれども、今後の考え方を教えてください。","respondent":"秋山協働・国際担当課長、金子企画財政課長","answer":"区民からの寄附のお金が、また区民の活動の団体に戻って行くと、そういう流れをつくっていきたいと考えております。基金の積立、ないし使い方ということでのお尋ねかと思いますが、冒頭、区長がご説明申し上げましたとおり、予算につきましては、平成２２年度、２３年度とも、緊急対策と長期基本計画の着実な実行ということであります。","id":"exchange-044"},{"speaker":"山内委員","kind":"確認","question":"改選前といったことではなくて、私は何度も、不妊治療については質問していますけれども、また改めましての確認と可能性について、お伺いしたいと思います。そういったところから、今回、補正で６７５万円という大変大きな補正をつけましたけれども、これは当初予算で見込めなかったのか、まずその辺を伺いたいと思います。","respondent":"山岡健康課長","answer":"平成２１年度は増えておりますので、平成２１年度の実績を見る形で予算を組むことができるのであれば、もう少し増額して組んだところですけれども、平成２２年度の当初予算は、そういう形で組んだところでございまして、不足が生じる可能性が出てきたです。","id":"exchange-045"},{"speaker":"山内委員","kind":"質問","question":"そういった中で、可能性をちょっと伺いたいんですが、今度は子づくりをするなら品川区といった可能性。夫婦で７３０万円と所得制限を設けて、やっています。１５万円のところを、例えば５万円補助をするとか、そういったことが、子づくりをするなら品川区といったところにつながっていくのかなと思うんですけれども、その辺の可能性を、ちょっと伺いたいんです。","respondent":"山岡健康課長","answer":"我々としましては、できれば所得制限をなくしたらどうかという提案を、国に対して、あるいは東京都に対してしていく。区のほうは、それ以外の特定以外の一般不妊治療の助成に力を注いでいきたいと、現時点では、考えているところです。","id":"exchange-046"},{"speaker":"山内委員","kind":"質問","question":"そういうところを、区のほうで独自の助成をしていけば、できるのであれば、うまくマスコミを使って、こういうことをやっていますとか、そういうところで、品川区に転入してきていただいて、それこそ、ひいては人口が増えて区民税のアップにもつながっていくのかなといったことも、いろいろ考慮しながら、私は質問をさせていただいているんですけれども、いかがでしょうか。","respondent":"山岡健康課長","answer":"そうすると、それ以上の方、ある程度収入が多くある方だけに区の制度を考えるのかということになり、これはいかがなものかということも言えますので、ちょっと直ちにこれを導入するというのは難しいかと思います。ただ、今後、一応、研究してまいりたいとは考えております。","id":"exchange-047"},{"speaker":"山内委員","kind":"質問","question":"ですから、そういった質問をさせていただいているので、少子高齢化を解消するには、やっぱり子どもをつくっていただくといったことがほんとうに大前提なので、そのあたりちょっと、今後について考えていただけたらありがたいかなと思います。何せ金額が大きいですよね。そういったところで、区の将来像というか、今後の高額療養費についての考え方というか、それをちゃんと伺っておきたいと思います。","respondent":"本城国保医療年金課長","answer":"高額療養費の制度については、今回、このような補正になっているわけですけれども、基本的には、区といたしましては、保険制度内で対応するですので、そのあたり、ちょうど高額療養費制度については、現在、入院のみ現物で給付できるという制度がありますが、通院についても。","id":"exchange-048"},{"speaker":"山内委員","kind":"質問","question":"高額療養費は、今、通院のほうでも検討いただくといったことなのでしょうが、そうは言っても、やはりいろいろとかさんでくるというのは現実なのでしょうから、高額療養費が抑制できるような事前の対応というのを何かしていくような区の方針というのはないのでしょうか。","respondent":"本城国保医療年金課長","answer":"あくまでもこの制度は自己負担の限度額が、超えた部分が返戻されるという仕組みですので、医療費がかかった結果、戻ること自体は、医療を受診した結果だということで、区としてそれを抑制するとか、そういう形のところは考えていないところです。","id":"exchange-049"},{"speaker":"石田委員","kind":"質問","question":"私からは、７７ページ、広報経費追加分、９７ページ、百反歩道橋架替関連整備事業について、大井町駅周辺地区再開発事業補助金、９５ページ、商店街電線類地中化事業、時間があれば、雑入について、お伺いします。それから、百反歩道橋ですが、この内容と理由というか、どうしてこうなったのかということと、あわせて、同じページの大井町駅周辺地区の再開発事業も、理由と内容を教えてください。","respondent":"中川原広報広聴課長、三宅都市開発課長","answer":"国際友好協会との関連といいますか、連携ですが、内容によりましては、ご相談いたしますが、今回、制作しているものにつきましては、所管と相談して制作をさせていただいたものです。もう一つは、広町一丁目のほうで、内陸部にある工業地域になっているところは、そちらなんですが、そちらのまちづくりを、現在、検討しているところでして、その中で、第一三共のご協力によりまして。","id":"exchange-050"},{"speaker":"石田委員","kind":"確認","question":"これは以前もやっていたということで、平成２１年度、１６本で１９２万円のコストがかかったと出ていて、今回、５本２セットで１０本で２７５万円と、１６本より大分かかっているんですが、その辺の整合性、どうしてこのような金額が多くなっているのか、教えてください。ただ、整備の実施設計の委託の部分で５００万円減っているんですが、これは設計はされているということでよろしいのですか。","respondent":"中川原広報広聴課長、三宅都市開発課長","answer":"映像館は、平成２１年度にオープンしまして、随時、 ＣＡＴＶで放映している番組を、映像館向けにデータ編集しまして、放映しておりますので、そういった経費は、日本語版でつくるより、外国語版は。百反歩道橋の設計ですけれども、現在、設計を進めております。今回の９７ページの減額ですけれども、こちらにつきましては、契約落差です。今後、改善等が可能になることも含めまして、設計のほうは、並行して行っております。","id":"exchange-051"},{"speaker":"石田委員","kind":"確認","question":"広報経費の部分なんですが、平成２１年度も、多言語化によるケーブルテレビの番組制作だと、私は理解をしていたんですが、これはあくまでも、日本語で外国人の暮らしの支援をする事業なんですか。ちょっとその辺の確認をお願いします。それから、９５ページ、商店街電線類地中化事業で、大幅に減になっているんですが、その理由を教えてください。","respondent":"藤橋都市整備下水道課長、中川原広報広聴課長、藤木交通安全担当課長","answer":"それとあわせて、戸越銀座地区におきましても、戸越銀座の駅の両側で、今、工事をやっているんですが、西側のほうの工事が、交通管理者との協議の結果。今回は、映像の文字もすべて４カ国語でやっておりますので、その分高くなっているです。差額が出ましたのは、当初、私どものほうで予算を組んだときに、１台当たりの売却単価を、自転車については１００円程度。","id":"exchange-052"},{"speaker":"石田委員","kind":"質問","question":"今までと違う手法でつくられていくのかということを、ちょっと教えてください。１００円と考えていたのが、１,０００円ということで、１０倍ぐらいになっているんですが、高く売れたというのは非常にいいことだと思うんですが、それは例えば、よほどいいものがいっぱいあったからとかいう理由なのか。それとも、何か材料費の高騰で高く売れたのか、その辺ちょっと教えてください。","respondent":"中川原広報広聴課長、藤木交通安全担当課長","answer":"外国人に向けての情報提供は、国際友好協会とよく相談して、アンケートなども取らせていただいて進めてきている事業です。たまたま昨年度は、そういう金額で入札がなされたです。","id":"exchange-053"},{"speaker":"石田委員","kind":"質問","question":"ちょっとその自転車の部分で、１点だけ。それは、今までは、いいものも、悪いものも全部一緒に売却だったのですが、今回は、１台１台で売却をされたということなんですか。ちょっとそこだけお願いします。","respondent":"藤木交通安全担当課長","answer":"説明がちょっと不十分でございました。いいものも、悪いものもすべてかわりありません、一律に同じ値段で売却しております。","id":"exchange-054"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、９３ページ、産業経済費の中の、小規模商店街活力づくり支援事業、また、その下の空き店舗活用支援事業について、お伺いしたいと思います。はじめに、小規模商店街活力づくり支援事業、また空き店舗活用支援事業というのは、どういう事業なのか、改めてお聞かせいただきたいと思います。","respondent":"諸岡商業・観光課長","answer":"こちらのほうは、１年目、小規模商店街をモデル指定いたしまして、そこにコンサルタント等を含めて調査にあたり、再生モデルを提案する、それに基づき、商店街のほうで、いろいろご検討いただきまして、翌年度以降、商店街として事業を進めていく。","id":"exchange-055"},{"speaker":"山元委員","kind":"質問","question":"今回、みんな減額になっているわけですけれども、例えば、空き店舗活用支援事業は、たしか去年も減額、今回も減額という形になっているんです。ある程度やっぱり目標を持ってやられると思うんですけれども、その辺、連続して減額になる原因といいますか、何かあるのでしょうか。","respondent":"諸岡商業・観光課長","answer":"したがいまして、区はそういったことが整えば支援できるように予算計上して対応しているわけですが、実際に先送りになった場合、その分が残となっているというものです。","id":"exchange-056"},{"speaker":"山元委員","kind":"質問・要望","question":"すみません、その１件というのは、実際にスタートしていると思うんですが、どういうお店なのか、また、どの辺の地域でそういうのを実際にやっているのか、教えていただきたい。それから、商店街のほうから推薦をされて、区のほうでいろいろ考えていただけると思うんですが、対象になる、手を挙げる商店街というか、候補というのは、どういう方たちが手を挙げているのですか。","respondent":"諸岡商業・観光課長","answer":"全商店街を対象といたしまして、その旨をお伝えいたしまして、商店街として、その中にある空き店舗を活用されて事業を行いたい場合については、区として支援をする、ぜひ、ご相談くださいということで申し上げているところです。","id":"exchange-057"},{"speaker":"山元委員","kind":"質問","question":"実は、地方なんですが、空き店舗対策支援の助成金とちょっとずれるかもしれないんですが、その中には、１８歳以上の人とか、ＮＰＯ法人とか、いろいろ手を挙げて、それを受けるというところがあるんですが、区としては、あくまでも５０店舗以下の商店街が推薦したところだけを対象にしているのでしょうか。","respondent":"諸岡商業・観光課長","answer":"商店街に入っていただきまして、地域で、その空き店舗を商店街が活用されること、やっぱり商店街全体でそこを盛り上げていただくということが必要であると思いますので、区としては商店街を介して、助成金も商店街に交付をしているというものです。","id":"exchange-058"},{"speaker":"山元委員","kind":"質問","question":"すみません、何かしつこくて申しわけありません。やっぱりまちを活性化するためには、いろいろな人たちが使えるような、行き来できるような、例えば、さっき言ったように１８歳以上という、高校を卒業した子どもたちがそこで若い子のお店を開きたいということで手を挙げ、それをまた商店街のほうで推薦をしてもらえたら、区は応援をしてくださるのでしょうか。","respondent":"諸岡商業・観光課長","answer":"新しく店をやりたいというそういった希望を持っている方が、商店街に来られて、何かやらせてほしいということで、商店街はそれを受けて、商店街が区の助成金の受け皿になるから、ぜひやってみろと、最終的には。","id":"exchange-059"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと時間があるので、その下の土木費のところでお伺いしたいのですけれども、土木総務費の中に、財源更正ということで、駅周辺放置自転車対策事業に対する使用料増額および諸収入減額により、同額一般財源を更正減額云々と書いてあります。これはどういうことなのか、教えていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"しかしながら、自転車の雑入の売却費が８２５万円ほど、当初予定より上回りましたので、その三つの差し引きを一般財源のほうに振り分けるというものです。","id":"exchange-060"},{"speaker":"山元委員","kind":"質問","question":"実際に、ほんとうに駅周辺はたくさん放置自転車がありますが、現実的に、伸び率というのでしょうか、増えているのですか、それとも減っているのか。それから、自転車の駐輪場というのは、これから増える予定はあるのでしょうか。","respondent":"藤木交通安全担当課長","answer":"自転車の駐輪場につきましては、今後、利用率の高いところなど、道路上に設置できないかとか、そういうことにつきまして、いろいろ道路管理者などと協議していきたいと考えております。","id":"exchange-061"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは、８８、８９ページ、衛生費、環境費の中の緑化推進費の関連と、９６、９７ページの土木費、都市計画、都市開発費に関連をしてお伺いしてまいります。それから、補正ですから３４５万円マイナスになっていますけれども、緑化率について、基本的に品川区自体が、将来、５年とか、１０年、２０年、３０年のスパンで、どんなふうにお考えになっているか、その３点、お願いいたします。","respondent":"藤田水とみどりの課長","answer":"その率で言いますと、平成２１年度で２１.２％ということになっております。これからも、品川区としては、まずは４分の１緑化といったときの目標を目指して、今、頑張っているところです。","id":"exchange-062"},{"speaker":"原委員","kind":"確認","question":"品川区は、景観を重視していくという方針のところでしょうけれども、もう１回確認をしたいんですけれども、全体の公園とか、みどりの件ではなくて、緑比率について、今後、どういうふうにお考えになっていくのかということ。","respondent":"藤田水とみどりの課長","answer":"これは私どもの緑化指導も、おそらくいい方向に進んでいると考えていますので、今後も、それに向けて頑張ってやっていきたいと考えています。","id":"exchange-063"},{"speaker":"原委員","kind":"質問・要望","question":"私も、そう思います。品川区自体、すごくみどりに力を注いでおられると思うんです。比較する必要もないのかなとも思うのですけれども、品川区の個性的なものは、これはちょっと質問が嫌みっぽくなってしまうのかもわからないですけれども、旧東海道以外で、もし何かそういった形で景観とか、都市計画の関連でのことがあれば、お教えいただきたいんですけれども、よろしくお願いいたします。","respondent":"藤田水とみどりの課長","answer":"そういった中には、昔からのものを守っていくものだけではなく、新しいものも、やはり景観上は重要ですので、例えば大崎駅前の再開発のエリアといったところも、景観上、重要な地点だということ、それから、武蔵小山等の商店街のにぎわい等も景観上、重要だと考えていますので。","id":"exchange-064"},{"speaker":"原委員","kind":"質問・要望","question":"当然に、都市計画の再開発ということだけではなくて、環境のビジネスだったり、先ほども答弁で出たように、大崎の関連だけではなくてということになって、観光も一部入ってくるのかもわかりませんけれども、よく答弁でお聞きするのは、観光だったり、環境関連ビジネス、エコの問題だったりということですけれども、それでもいいんですけれども、できましたら、それ以外に、品川区のお考えがあるようであれば。","respondent":"岩田都市環境事業部長","answer":"法定再開発に対して、品川区自体が補助金という形で支援しているわけですけれども、まだしばらくは幾つかの事業が回りますので、これは続くと思います。その次は、大崎が一定落ち着きますと、この額は、当然落ちてまいります。","id":"exchange-065"},{"speaker":"原委員","kind":"質問・要望","question":"今のご答弁を聞きまして、安心をいたしました。そうしましたら、他区はなかなか厳しい中で、品川区はしっかりとした健全な運営をしていただくとありがたいということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"南委員","kind":"質問","question":"１９２ページの介護保険の保険給付費について、質問したいと思います。居宅介護サービス費が、ずっと増の補正予算の内容になっておりますので、その内容について何かということを伺います。","respondent":"冨岡高齢者福祉課長","answer":"居宅介護サービス給付費の補正の内容ですが、この部分につきましては、特定施設の入居者が、当初予想した見込みより５００件ほど、優良老人ホームとか、特定施設が増える予定、見込みだということで、増額の補正をしています。","id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。介護保険が導入されて、今年で１１年目になると思うんですけれども、当初のサービスを受けていた方から、今日は、どのぐらい増えているのか、それが何倍になっているのか、そこのところを、ちょっと数字で教えていただきたいと思います。必要な人が必要なサービスを受けられているのかというところでは、区としての認識はどういうふうに見ておられるのかも含めて、教えてください。","respondent":"冨岡高齢者福祉課長","answer":"サービスの受給者数ですが、数字的にはつかんでおりませんが、２.２倍です。平成１２年度が４,６５１人、平成２２年度が１万１８５人ですので、２.２倍です。","id":"exchange-068"},{"speaker":"南委員","kind":"質問・要望","question":"必要な人が必要なサービスを受けられていると認識しているかどうかについても、伺いましたので、その辺についても、ぜひ、教えていただきたいと思います。私は、要介護認定が、品川区の高齢者の方々の受けている方たちで、分布状況というのでしょうか、要介護認定が、どこで、どのぐらいいらっしゃるのか、何％ぐらいの割合になっているのかをつかみたいと思うので、それを教えていただきたい。","respondent":"冨岡高齢者福祉課長","answer":"サービスの問題ですけれども、ご案内のとおり、ケアマネジメントによりまして、個々のケース、それぞれ適正なサービスの提供がされていると考えております。それから、介護度別、先ほどの平成２１年度末ですけれども、要支援が約３３％、要介護が６７％です。","id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけ、今年４月以降は、来年度の介護保険料の改定に向けて、具体的な検討がされますよね。その点について、見解を伺いたいと思います。同時に、福祉用具の利用について、リフト付ベッド、特殊寝台について、利用状況が適切に行われているのかどうかというところも、数字上で、どういうふうに見たらいいか知りたいので、ぜひ、０５年、０８年、１０年度で教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"平成２４年度の介護保険事業計画に向けて、ですけれども、ご案内のように、区内２０カ所に在宅介護支援センターがありますし、８割は区の関係のケアマネジメント計画をつくっているところですので、まず、一般的なケアマネジメントの計画の中で、状況について把握している。","id":"exchange-070"},{"speaker":"南委員","kind":"質問・要望","question":"高齢者の基礎調査は、何項目で、どんな内容ですか。たしか、数年前に、私も質問で取り上げたことがあるんですけれども、ほんとうに高齢者の実態を把握するという内容の調査ではないはずです。ぜひ、そこのところをちょっと教えていただきたいと思うんです。品川区の場合、適切に受けているということなんですが、所得の低い方々の利用状況は、どういうふうな実態になっているか、教えてください。","respondent":"冨岡高齢者福祉課長","answer":"必要なサービスが提供できるように、というお話ですが、先ほどの特殊寝台につきましては、ご案内のように、平成１８年に制度が変わりまして、真に必要な方ということで、要介護１までの方、要支援１、２という方までは提供できないことになったところです。","id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"重度化しないように、ほんとうに大事だと。介護保険の会計上からも、それは好ましいと思いますので、やっぱりしっかりと必要なサービスを提供させる、そういう立場に立って、これからの保険料改定だとか、診療報酬等々の必要な意見を、区として、自治体として国に言う、そのことをしっかりと持っていただきたいということを、時間がないので答弁はいいですから、そのことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"高橋委員","kind":"質問","question":"１３０ページの国民健康保険料と、１６８ページの後期高齢者医療保険料の二つについて、お尋ねしたいと思います。こちらの金額が４億５,０００万円減ということなんですが、ここ数年の傾向と、そこからわかることというのでしょうか、現状の状況をご説明いただければと思います。","respondent":"本城国保医療年金課長","answer":"その結果、補正額の規模といたしましては、収納率の見込みということで、それが補正額を見立てることになるわけですが、今回については、現年分について、８３.４％ほどの収納率で見込んでおりまして、これはほぼ、平成２１年度の実績と同じ程度です。","id":"exchange-073"},{"speaker":"高橋委員","kind":"質問","question":"そのぐらいの数字というのは、ここ数年同じような形できているのでしょうかということ。それから、現時点での収納率というのでしょうか、それはどれぐらいになっているのでしょうか。","respondent":"本城国保医療年金課長","answer":"滞納繰越分の収納率ですが、この五、六年の間、年によって、若干前後はありますが、２５％を挟んでプラスマイナス数％ということで、大体、そのような傾向で推移しています。","id":"exchange-074"},{"speaker":"高橋委員","kind":"意見","question":"平成２１年度の決算書によると、収納率が３１.２％ということで、もともと２５億円が平成２２年度の滞納の中で３８％と見ているので、９億７,０００万円収納する予定だったのですが、現時点で４億５,０００万円と。さまざまな事情があって納められない方がいらっしゃると思います。区のほうも、徴収の態勢をとられているのですが、その現状と、今後の対応についてお願いします。","respondent":"本城国保医療年金課長","answer":"ただ、そのような状況の中でも、いろいろな状況で滞納される方は、当然いらっしゃいますので、そういった方に対しては、文章をお出しするだけではなくて、電話等、可能な限り手段を尽くしまして、ご本人と接触することを通じて、ご本人の状況を踏まえながら、状況を見て。","id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"どれぐらい納めないと、電話がかかってきたりするのでしょうか。皆さん、さまざまなご事情があると思うんですが、公平性の点から徴収の努力はお願いしたいと思います。どれぐらい未納だと、電話がかかってくるのでしょうか。","respondent":"本城国保医療年金課長","answer":"文書自体は、定期に一斉に発送していますが、電話につきましては、すべての方がわかるわけではないので、一定程度の期間になった段階で、ということで一律にいつから電話をするとか、そういうわけではございません。","id":"exchange-076"},{"speaker":"高橋委員","kind":"意見","question":"この問題は、これで最後にします。ということは、いつ電話をするかわからない。それから、どなたか特定の担当する方がいらっしゃって、そういう滞納の方に対する徴収の体制が、特別にとられているのか、そうでないのかというところを、お願いします。","respondent":"本城国保医療年金課長","answer":"現年分にお支払いいただけなくて、滞納繰越分ということにされている方につきましては、国保医療年金課に専門の係が設けられていまして、そこで、地区をそれぞれ受け持つ形で、未納になっている方にいろいろ対応させていただいているところです。","id":"exchange-077"},{"speaker":"高橋委員","kind":"意見","question":"引き続き、徴収努力の継続をお願いいたします。次に、後期高齢者医療保険料ですが、こちらを見ると、特別徴収と普通徴収と保険料の違いがあるのですが、ちょっと簡単に、そこを説明いただけるとありがたいのですが。１６８ページです。","respondent":"本城国保医療年金課長","answer":"ただ、その方の納付の状況等によって、口座振替という形で選択することもできますので、そういった選択をした場合は、特別徴収ではなくて普通徴収という種別に分類されているところです。","id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、年金から自動的といいましょうか、控除されるわけですね。そういう状況の中で、６億４,０００万円のマイナスなのでしょうか、そういったところは、どういうふうに考えたらよろしいのでしょうか。普通徴収でお支払いされるのは、いろいろな事情で、というのはあると思いますが、年金受給されている方のお支払いを、今、お聞きしたのですが。","respondent":"本城国保医療年金課長","answer":"特別徴収につきましては、その性格上、収納率自体は１００％ということになりますが、減額しているものは、収入額自体が減額されたということで、具体的には、当初見込んでいた所得よりも、実際には少ない所得だったので、結果として保険料の収納額が減っているということと。","id":"exchange-079"},{"speaker":"武内委員","kind":"質問・要望","question":"８６ページの生活保護費全般で、お伺いしたいと思います。はじめに、生活保護総務費で、今回、２,４６７万６,０００円の追加補正になっておりますが、このうちの職員給与費追加分２,１７８万７,０００円につきまして、内訳を教えていただきたい。それから、現在、職員は何名ぐらいいらっしゃるのか、あわせて教えてください。","respondent":"平澤生活福祉課長","answer":"もう一つ、今お尋ねの２,１７８万７,０００円の内訳ですが、こちらは、残業代というのですか、少し超過勤務代が増えてまいりまして、その分を補正させていただいたです。","id":"exchange-080"},{"speaker":"武内委員","kind":"質問・要望","question":"正規職員が６２名で、非常勤が２０名、それから、午前中にも質疑がありまして、年々増えているですね。先ほどの午前中の質疑の中では、保護の対象者、受給者の方は平成２１年度で４,１４５名、それから、平成２２年は、今、お手元にお配りいただいている、事務事業評価の４７ページを見ますと、４,３４７名プラス２０２名ということでいいのでしょうか。","respondent":"平澤生活福祉課長","answer":"先ほどの被保護者世帯の増加につきましては、委員、ご指摘のとおりです。それから、一般にケースワーカーと呼ばれている職員は、現在、４０名ということで処理しています。","id":"exchange-081"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、例えば平成２２年度でいきますと、約４,３４７名を４０人のケースワーカーで担当されているという認識でいいのでしょうか。１人約１００名強という形になります。例えば、このケースワーカーは、保護を受けている方のお宅に定期的に訪問とかをされるのでしょうか。されるとすれば、何か法律とかで決まっていて、何カ月に１回とかあるのかどうか、その辺のお仕事の内容を教えてください。","respondent":"平澤生活福祉課長","answer":"受け持ち人数につきましては、委員ご指摘のとおりです。訪問につきましては、訪問類型ということでございまして、東京都のほうの指導等がございまして、いわゆる居宅、一般的に住居にお住まいの方は、半年に１回程度の訪問が基準となっているところです。","id":"exchange-082"},{"speaker":"武内委員","kind":"質問・要望","question":"基準が半年に１回ということで、わかりました。実は、今回なぜこれを取り上げたかといいますと、昨年から今年にかけまして、区民の大勢の方と区政に対するお話を伺う機会が増えてきましたので、いろいろなところでお話を伺う中で、２会場のうち１会場ぐらいで、２分の１ぐらいの確率で、必ず生活保護の話が出ます。現実に、そういう方に対しても、半年に１回しか行かないのかどうか。","respondent":"平澤生活福祉課長","answer":"先ほど、私のほうでご答弁申し上げましたのは、いわゆる生活上安定している方については、半年に１回ぐらいということでございまして、訪問類型のＡ、それから、Ｂというのがございまして、毎月行く、それから３カ月に一遍行くというのがあります。","id":"exchange-083"},{"speaker":"武内委員","kind":"質問","question":"そうすると、実態として、やっぱりそういう方がかなりいるということなのでしょうか。そうすると、そういう方は、保護を受けても、なかなかアルコール中毒が治らなければ、いくら注意しても、同じようなことを繰り返して、周りの区民からおかしいではないかという声が出てくるということになってしまうんですけれども、そういうのを、毎日でも行かれて、指導して、改善するというケースもあるのでしょうかね。","respondent":"平澤生活福祉課長","answer":"生活保護を受給されている方につきましては、指導上の目標と申しますか、指導方針というのを定めております。例えば、委員お話のようなことにつきましては、療養専念という形になるわけです。アルコール中毒ということは病気です。","id":"exchange-084"},{"speaker":"武内委員","kind":"質問・要望","question":"そういった面では、人数がほんとうに少ない中で、１００名以上を担当されてやっていらっしゃって大変だと思うんですけれども、これからどんどん保護費が増えていく中で、その辺のところをしっかり、区の担当のほうでやっていただいているということを、私たちも堂々と、区民の方には説明しなければいけないですし、またそういう対応を、これからもお願いしたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問","question":"今度の二つの基金、お一人は匿名なんですが、この基金が取崩しになったときにお名前が残らないかもしれないんですが、もう１人の方に関しては、お名前をつけた基金を積んでいったとき、残高がゼロになったときに、どういうふうに考えているのか、そこをまず１点、お聞きしたいと思います。何でそんなに落とせるのかということが、ちょっと疑問にあったので、この２点、まずお聞きしたいと思います。","respondent":"冨岡高齢者福祉課長、永尾障害者福祉課長","answer":"今回の１５億円の二つ内容がありますが、いずれにしても、委員のご指摘のように、処分をするということが前提になっておりますので、ゼロになった場合は、例えば、施設になったとすればの話ですけれども。こちらにつきましては、区立の施設ですけれども、品川総合福祉センターが指定管理者となっております。品川総合福祉センターと区と協議いたしまして、事業の委託内容の見直しを行った結果、４００万円の減額となったものです。","id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１点目の寄附金の件ですけれども、確かに、そういうふうに何か名前を残していただきたい。これは知的障害者の生活の場だと思うんですけれども、運営を変えたことによって、何か影響が出ないのかどうか、余分な心配かもしれないんですけれども、単純に金額だけ考えると、そう思ってしまうんですが、その辺は問題ないということでよろしいでしょうか。","respondent":"永尾障害者福祉課長","answer":"つばさの家の件ですけれども、世話人の方につきまして、ＮＰＯ法人のほうに再委託をしたということですけれども、そのＮＰＯ法人自体も、ほかの個別にグループホームを運営されておりまして、そういうノウハウも持っているということで、区のほうとしても了解したところです。","id":"exchange-087"},{"speaker":"鈴木委員","kind":"確認","question":"要するに通常どおりやっていただければ、今まで以上やっていただけるということが大前提なので、そこら辺は問題ないというお答えを、もう一度確認をして、この件は終わらせたいと思いますが、この点について、お答えをお願いします。","respondent":"永尾障害者福祉課長","answer":"内容につきましては、特に変更をしているわけではなく、今までどおりきちんとした運営をしているということで、ご心配ないと思います。","id":"exchange-088"},{"speaker":"鈴木委員","kind":"質問・要望","question":"わかりました。その辺、よく連携を取ってやっていっていただきたいと思います。もとが９億２,０００万円が１０億４,３００万円になった。３年前と比べて、この２年間の最終補正がちょっと多いような感じがしたんですが、この辺は、どういう原因で増えているのか。使うものはちゃんと使って、お支払いしていただきたいんですけれども、その増えていく理由を教えていただければと思います。","respondent":"榎本人事課長","answer":"その以前と比べますと、その前の年は勤務時間の変更がありまして、その休憩時間の置き方に若干変更があったということで増した部分があるんですが、今回は主に労働基準法改正の部分だと認識しております。","id":"exchange-089"},{"speaker":"鈴木委員","kind":"質問","question":"理由がわかりました。それから、職員が、当然、行財政改革で減るようにしている中で、その影響で残業が増えているということはないのかという点が１点。例えば病欠の方が、今、区の中でどのぐらいいらっしゃるのかわかりませんけれども、そういう病欠の方の影響によって、通常に業務している方の残業に影響が出ているのではないかと、そこら辺は心配はないのかどうか、お聞きしたいと思います。","respondent":"榎本人事課長","answer":"２点目の病欠のほうの影響ですけれども、病気休暇も、長期にわたる場合については、代替職員を入れるという形をとっているのですけれども、１カ月未満の休暇につきましては、所属の努力で、という形にしておりますので、それはやはり若干影響が出てくるのかなと考えています。","id":"exchange-090"},{"speaker":"鈴木委員","kind":"質問・要望","question":"わかりました。なるべくなら、残業しないで終わっていただきたいと、これはすべての方の希望でしょう。ただ、どうしても仕事が重なる部分はやむを得ないと思うんですが、逆に言うと、体に気をつけて残業していただきたいと思います。以上、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"井上委員","kind":"質問","question":"５８ページの都補助金の障害者施策推進包括補助金と、６０ページの安心こども基金交付金の減額の理由と、それから、歳出、民生費のほう、８４ページなんですが、認証保育所運営費等助成についての変更を教えてください。","respondent":"永尾障害者福祉課長、吉岡保育課長","answer":"その金額自体は、２,５９８万円余ですけれども、それと一緒に小規模作業所の新体系移行支援事業というのが別にございまして、その部分が逆に、１,４００万円余いただくということで、差し引きとしてこの金額になったものです。それからもう１点、８４ページ、認証保育所の運営費の増額補正ですけれども、こちらは、予算上は６,２００人ほどの子どもに対する運営費の補助を計画しておりましたけれども、実績として６,６００人弱の需要が見込まれるということで。","id":"exchange-092"},{"speaker":"井上委員","kind":"確認","question":"この事業で、要綱を確認しますと、利用期間が２年間で、区長が認めれば１年間という延長があるということになっているんですが、利用者から、旗の台の身障会館では、２年間以上なかなか延長ができない、ほかのところではわりと延長ができるのに、不公平であるではないかという声もあるんですけれども、実態は、どういうふうになっているのか。","respondent":"永尾障害者福祉課長、吉岡保育課長","answer":"就労支援の件ですけれども、自立支援法の中では、最大で２年間というような規定が政令の中でありますけれども、現実、その２年間経った後、障害者が通えるような施設がすべてあるわけではございません。すみません、ちょっと安心こども基金のほうのご説明を補足しますと、今、申し上げた認証保育所の当初の３園を予定したのが１園に減になったというのは、これが減額の部分ですけれども、そのほかに。","id":"exchange-093"},{"speaker":"井上委員","kind":"質問・要望","question":"それは、改善をされているということなので、ぜひ、前向きにお願いしたいと思います。安心こども基金のほうですけれども、今、説明をされた中で、８５ページで、開設準備経費というところがマイナスになっているけれども、ここのところでは、どういった状況なのでしょうか。","respondent":"吉岡保育課長","answer":"こちらが、先ほど、増減の説明をしたうちの一番はじめの、認証保育所の部分です。当初予算では３園分の安心こども基金を活用した助成を計画しておりましたけれども、結果として、決算見込みでは１園になっているということ。","id":"exchange-094"},{"speaker":"井上委員","kind":"質問","question":"安心こども基金のほうで、３園予定をしていて、２園が使われなかったということなのですが、何か基金を使わなかった理由があるのでしょうか。","respondent":"吉岡保育課長","answer":"この３園と申しますのは、既に去年８月にオープンをしました小学館アカデミー武蔵小山保育園と、ポピンズナーサリー東五反田という認証保育所がありますが、こちらは、当初、安心こども基金を使うという想定のもとで予算計上したのですけれども、実は。","id":"exchange-095"},{"speaker":"井上委員","kind":"質問","question":"今、おっしゃられたように、認証保育所でも、いろいろな水準があるということなんですけれども、この中で、品川区も待機児対策の一つの手段として、認証保育所を活用するということを打ち出しているので、質の保証というのは大変重要なものかと思うんです。こういった認証保育所の質の調査を東京都ではやっていると思うんですけれども、それが品川区ですぐに見られるようなシステムになっているのでしょうか。","respondent":"吉岡保育課長","answer":"その際には、品川区も同行いたしまして、どのような問題があるか、あれば改善について一緒に対応していくということになってあります。検査結果については、特にその水準に問題があるというようなことで、ホームページ等で掲示とかはされていないと認識しております。","id":"exchange-096"},{"speaker":"井上委員","kind":"提案","question":"以前にも提案をさせていただいているんですけれども、東京都での調査結果がすぐにリンクをされて、品川区でも見られるようにということに、ぜひ改善をしていただきたいと思います。","respondent":"金子企画財政課長","answer":"現在の経済状態がこのように続いていく見込みがあるわけですけれども、もし続くのであるならば、財源が不足して、その分については、財政調整基金を活用していく必要があるということから、委員もご指摘になりました新聞等でも表示されておりますが、品川区は。","id":"exchange-097"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺について、いろいろな区民要望がある中で、たまたま貯金ができますよということなのか、今までは、生活ネットワークは指摘してきたのは、いろいろな給付を押さえてそっちに回しているのではないかというようなことも、介護保険制度の中でも、いろいろなところで、区民からも声があるんですが、その辺の考え方について、少しお願いします。","respondent":"金子企画財政課長","answer":"先ほど、ちょっと説明が漏れました。ほかのサービスとの関係ですけれども、これも私ども、区長を先頭に再三述べさせていただいているとおり、このような経済状況の中で、地域経済の活性化と区民生活の安定化という意味で、区民を支えるという意味でさまざまな事業を実施していく。","id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"次にいきます。先ほど、百反歩道橋の架替えのところで、スケジュール変更という答弁がありましたけれども、１５億円ほどの債務負担行為を廃止するということで、国との関係で、２０１２年に完了しなくてもよくなったということなので、そこのところをちょっと説明いただきたい。その辺の執行の関係を教えてください。","respondent":"三宅都市開発課長","answer":"実施設計のほうですけれども、これから改善点などを含めて考えるというところがありますが、今まで考えていたのは、暫定利用と暫定整備と、それから、最終的な完成形という二段構えの設計をやっておりました。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問","question":"そうすると、今、２年ほど猶予ということだったので、これから２０１４年ぐらいまで、あそこは工事は延びていくという判断でよろしいのでしょうか。","respondent":"三宅都市開発課長","answer":"詳細なスケジュールはこれから詰めてまいりますけれども、そのくらいの時間的な余裕は得られたです。","id":"exchange-100"},{"speaker":"井上委員","kind":"質問","question":"最後に、衛生費の保健衛生費のところで、予防費の委託料なんですけれども、１億４,１００万円余のこの委託料を、どういう形で医療機関に支払われていくのか、ちょっと仕組みを教えてください。","respondent":"吉田保健予防課長","answer":"本委託料につきましては、予防接種費ですので、契約している医療機関に月別にご請求いただいて、お支払いしているといった状況です。","id":"exchange-101"},{"speaker":"井上委員","kind":"質問","question":"予防接種のところ、定期予防接種で、ポリオとＢＣＧが集団接種だと思うんですけれども、兄弟を抱えている方たちは、天気が悪かったりとか、大変に困難なんですが、これをそういった形で医療機関でできないのでしょうか。","respondent":"吉田保健予防課長","answer":"ＢＣＧにつきましては、管針法という日本独自の接種をしておりますので、技術的な問題がまず一つ。それから、接種率が、４カ月健診と同時にやっているということで、非常に高い接種率が得られているということから、ＢＣＧは行っておりません。","id":"exchange-102"},{"speaker":"安藤委員","kind":"質問","question":"今の財政調整基金のところで質疑がありましたが、ちょっとわからないところがありましたので、詳しくお伺いしたいと思います。その関係で言うと、サービスを担う職員が、不安定な非常勤や派遣などに置き換えられてサービスが行われた場合、それはサービスの低下にあたると思いますので、そことの整合性がどうなのかというのが１点、聞きたい。","respondent":"金子企画財政課長","answer":"財政調整基金の繰入金のところに荏原第六中学校と書いてありますけれども、これは、誤解をされているのかと思いますが、荏原第六中学校は、下に線が引いてありまして、ここの部分は、その前のページの義務教育施設整備基金繰入金の説明でありますので。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問","question":"後段のほうは、誤解だということがわかりました。欄がずれていますね。失礼いたしました。後から国から戻ってくると思うんですけれども、義務教育施設整備基金を積み立てているという、区独自の理由は、ちょっとわからないんです。後から戻ってくるのに、義務教育施設整備基金を積み立てているというのは、それはどういう意味なのか、ちょっと教えてください。","respondent":"金子企画財政課長","answer":"そういう意味では、ちょっとご質問の趣旨がわからないところがあるんですけれども、国庫補助は戻らないということ、後から戻るというようなことはないということは、ご認識いただきたいと思います。","id":"exchange-104"},{"speaker":"阿部委員","kind":"質問・要望","question":"宝保育園の工事の遅れで、年度はじめの受け入れ児童数に影響があったかどうかということを教えてください。空き店舗活用支援事業については、すみません、確認してないんですけれども、廃業例なんかもあると聞いておりますけれども、新しいお店をつくるときに、経営が成り立つのかどうかというようなことを、ある程度精査されて、やっているのか、その仕組みについてを教えてください。","respondent":"藤橋都市整備下水道課長、吉岡保育課長、諸岡商業・観光課長、三宅都市開発課長、金子企画財政課長","answer":"交付金になったことで、交付金の中で、いわゆる計画にのっとってやる事業については。現園舎についても、面積の余裕がありますので、１２人増については、４月１日から実施するということで、影響はございません。区のほうで助成するにあたりましては、区の中小企業診断士の診断を受けてもらったり、あるいは経営相談を受けてもらったり、また。北品川五丁目第１地区の再開発事業の状況ですけれども、現在、権利変換計画の案を固めまして、地権者とそれぞれ交渉といいますか。","id":"exchange-105"},{"speaker":"阿部委員","kind":"質問・要望","question":"権利変換に関する話し合いが非常に長引いている、これは確認させていただきたいんですけれども、その理由の一つとしては、権利の配分の考え方が、これまでの再開発とちょっと違ってきているのではないか、さらに言えば、住民の方々に、従来ほど有利ではないような条件が提示されているのではないか、そのことも、話し合いに時間がかかっている背景にあるのではないかというご指摘も。","respondent":"三宅都市開発課長、金子企画財政課長","answer":"北品川五丁目第１地区の再開発事業の権利変換の時期ですけれども、まだ、都知事に認可申請を行っておりませんので、３月中に認可をもらうというところまでは至らない見込みです。基金についてのお尋ねです。平成２２年度の当初予算は、最前からご説明申し上げていますとおり、一定の事業を実施するために、財源不足ということで財政調整基金において約２０億円近く取り崩す予定でした。","id":"exchange-106"},{"speaker":"阿部委員","kind":"確認","question":"そのうえで、実際に交渉の何が引っかかっているかというのは、正確なところは知る由もないことではありますけれども、ここの場合は、地権者の中に、要は組合員の中に区も入っているわけですから、ある程度、合意の取りやすいような環境について、区もイニシアチブといいますか、一定程度発言をしていくべきではないかと思っているのですが、いかがでしょうか。","respondent":"三宅都市開発課長","answer":"区のイニシアチブですけれども、区としましても、理事会ですとか、総会に参加しまして、疑問点は、皆さんにわかりやすいように質問したり、もろもろ働きかけておりまして、そのようなことは合意形成のほうに寄与しているものと考えております。","id":"exchange-107"},{"speaker":"伊藤委員","kind":"質問","question":"私は、１１２ページ、繰越明許費の庁舎等維持管理費について、それから、８５ページの保育園運営費について、８７ページ、生活保護費に関連して質問します。委員会等で報告があったと聞くんですが、約５億６,０００万円前後の繰越明許をしたということは、よほど大きな工事の遅れがあったということが推測されるわけでありますので、改めて、これが遅れた理由を明確に教えてください。お願いいたします。","respondent":"阿部経理課長","answer":"音が出たということがございまして、そのことよりまして、業務に支障が生じないように、工事時間に若干影響を受けましたので、その結果、当初は３月末の竣工予定でしたけれども、それが３カ月延びまして、６月末になったです。","id":"exchange-108"},{"speaker":"伊藤委員","kind":"意見","question":"５億５,０００万円近くのお金が予定されているんですけれども、騒音とか振動というのは、当然予想されたはずしょう、はじめから。騒音は予想されたはずですよね、当然。そのことについて、区の当局としては、この大切な庁舎を改築していくにあたって、どうしてしっかりと検討しなかったのかということが、非常に不思議でなりませんので、そのことについて、改めて答弁をお願いいたします。","respondent":"宍戸施設整備課長","answer":"なぜ、当初からこういう見込みが立てられなかったのかですが、はつり工事は大分多く発生しておりまして、当初から、ある程度のご迷惑をかけるということは想定しておりましたけれども、やはり現実的に仕事との兼ね合いという部分で。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問","question":"予算特別委員会だから、そういうことを、私は指摘をしなければいけないわけではないですか。例えばそういう表現の方法とか。今さらなぜ、その時期を考えないで契約したかということを指摘しても仕方ないからやらないけれども、だったら、そういう理由でこうなったということについては、ぜひ、いろいろな工夫をしながら、区民の皆さんにＰＲするべきだと思うんですが、いかがでしょうか。","respondent":"宍戸施設整備課長","answer":"その辺の説明する責任はあると重々感じておりますので、経理課長その他と相談しながら、その辺については対応してまいりたいと思います。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"確認","question":"私たちは、いつまでも増え続けると思っていません。確認したいのは、品川区のこれからの乳幼児人口の推移と、公立の保育園を１園つくるのに、文教委員会の資料では、大体９０％近くが税金で賄われているわけであります。ですから、ざっとですけれども、仮に公立保育園を一つつくった場合には、年間でどれぐらいの品川区の財政負担になるかということを、お聞かせください。お願いいたします。","respondent":"吉岡保育課長","answer":"乳幼児人口の推移の見込みですけれども、これについては、いろいろな変動要因がありますので、なかなか予測は難しい部分があります。ただ、今のところ、中期的には、あと数年間については、乳幼児人口については増を見込まざるを得ないだろうと考えています。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"確認","question":"確認しますけれども、現時点での乳幼児人口の推移、大切なところですよ。だから、その前提をしっかり確認しないと、次の質問に移っていけないのですけれども、要は、いろいろな見方があるから一概には言えないけれども、日本全国としては少子化が進んでいることは事実でありますし、東京都内に流入する人口は、これからも増え続けていく保証も、逆にないわけであります。","respondent":"吉岡保育課長","answer":"今、お話しましたように、１園当たり平均的な１００人規模の園で２億円弱の運営費がかかるということになれば、区立保育園を無制限に設置をしていって、待機児問題等々に対応していくのかということになりますと、それはそういうふうにはならないわけで、平成２３年度予算でも。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"確認","question":"昔の一時期のように、経済が右肩上がりで、税収がどんどん入ってくるときであるならば、それはいろいろな選択肢はあるかもしれないけれども、これからの品川区を考えていくと、低経済成長が続いていく、それから、保育も充実しなければいけないということを考えていくと、やっぱり選択肢が狭められてくると思いますので、この質問の最後の確認で、改めて、品川区のこれからの保育の方針をお聞かせください。","respondent":"古川子ども未来事業部長","answer":"そういう中では、既存の保育資源を有効に活用しながら、当然に民間の力にも支援していく中で、少なくとも、品川区の中での子育て環境については、十分に配慮していきたいと、このように考えております。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"確認","question":"ぜひ、よろしくお願いいたします。生活保護費に関連して質問いたします。パチンコに行ったり、お酒を飲んだり、それから確認していませんけれども、車に乗っている生活保護受給者の方がいらっしゃるとか、いろいろ聞こえてくることも事実ですよ。こういう人に対して、確かに、制度上はできないことはわかる。だけれども、税金を支出する以上は、しっかりとした対処をしていくべきではないでしょうか。","respondent":"平澤生活福祉課長","answer":"ご指摘のとおり、私どものできる範囲というのは、法令上、決まっているところではありますが、先ほど、ご答弁させていただきましたとおり、必要な方につきましては、私どものほうで呼んで話を聞くということもあわせて行っておりますので、その点はご了解いただきたいと思います。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"この間、自民党の勉強会で出たんですけれども、今、ただお金を渡していくだけではないですか、いろいろな方々に対して。例えば、電子マネーで、その方の使い道を管理していくとか、いろいろな電子マネーが、今出回っています。これを言うと、できないことはわかっていますよ。答弁いただけますか。","respondent":"平澤生活福祉課長","answer":"委員のご指摘とはちょっと違うかもしれませんけれども、国のほうでも、この３月、４月にかけて、生活保護制度そのものの抜本的な見直しについての検討に入るということを聞いております。その辺につきましても、事業について、しっかりと見守っていきたいと思っています。","id":"exchange-115"},{"speaker":"堺委員","kind":"提案","question":"私のほうからは、８７ページの保健衛生費、２目予防費に関連いたしまして、お伺いしたいと思います。しかし、今回、提案されております補正予算書の中では、まず、設計委託については５６２万円の減額ですから、おそらく、４,０００万円近くが執行されたのかなと理解するんですが、もう一つの工事委託について１,０００万円、これは全く使わなかったということでしょう、減額の計上がされておりますね。","respondent":"三宅都市開発課長","answer":"その理由ですけれども、国の補助の制度が変わりまして、平成２４年度までに工事を完了するということでやっておりましたけれども、社会資本整備総合交付金に移行したことによって、国との調整の中で、時間的な余裕ができてきたということと。","id":"exchange-116"},{"speaker":"堺委員","kind":"質問・要望","question":"したがって、どこか場所を移設してもらえるとありがたいと、こういうことですから、東側も、西側も、今ある百反歩道橋の階段の部分が、単に移設されるということによって、補助１６３号線もスムーズにいくし、利用者にとっても安全なところから上り下りができるとなれば一番いいので、それを期待して、少し時間を稼ぐということで延期をしたという理解をしたいんですが、それでいいのか。","respondent":"三宅都市開発課長","answer":"１点目のＪＲとの協議ですが、その後、順調に進んできておりまして、来年度、平成２３年度に協定締結の予定です。","id":"exchange-117"},{"speaker":"堺委員","kind":"質問・要望","question":"保健衛生費のほうです。そういう中で、特に任意予防接種としては、１億円近いお金が補正予算で組まれております。これは確認をしておきたいんですけれども、間違っていたら訂正をしていただきたいんですが、単価３,６００円につき、０歳から１２歳までの人は本人負担が１,５００円で、区が２,１００円助成しますと。","respondent":"吉田保健予防課長","answer":"６５歳以上につきましては、ご指摘のように、１回限りですが、２,２００円です。","id":"exchange-118"},{"speaker":"堺委員","kind":"質問","question":"そうすると、この実績についてはどうでしょうか。先ほども、お答えをいただいたような気がするんですが、ちょっと書きとめられなかったので、実績を教えていただけますか。","respondent":"吉田保健予防課長","answer":"約７０％近い接種率という形になります。肺炎球菌につきましては、１万５,５００人弱というところでございまして、こちらもかなり伸びている。今、Ｂ型インフルエンザの流行もありますので、今後また、伸びるものと考えております。","id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問","question":"８５ページの私立保育園の開設準備経費について、お伺いいたします。","respondent":"吉岡保育課長","answer":"私立の認可保育園の補助金の内容のご質問ですけれども、まず、開設準備経費というところに出ているのは、４月にオープン予定をしておりますみずなら保育園という私立保育園です。","id":"exchange-120"},{"speaker":"飯沼委員","kind":"質問","question":"区の負担はないのかどうかと、それから、事業者の開設のときの負担の割合はどうなっているのか、わかったら教えてください。","respondent":"吉岡保育課長","answer":"今、申し上げた国庫補助が入る分、それから東京都の上乗せの補助金にプラス、品川区の助成金といたしまして、７７０万円余が区の一般財源で入っております。事業者のほうの負担については、６００万円余です。","id":"exchange-121"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国と東京都の緊急整備の活用をぜひしていただいて、事業者の負担をなるべく減らして、やっぱり認可保育園を必要数つくっていただきたいという立場で質問をしたいと思います。共産党は、この間、待機児解消は、認可保育園の増設を求め続けてきましたけれども、やっと平成２３年度に３園、認可保育園ができるということで、まず歓迎をしているわけです。","respondent":"吉岡保育課長","answer":"平成２３年度については、先ほどもちょっと申しましたけれども、軸足を民間の活用というところに置きまして、私立の認可保育園、今のところ、４月には３園オープンの予定になってありますけれども、私立認可保育園の活用、あるいは。","id":"exchange-122"},{"speaker":"飯沼委員","kind":"意見","question":"私たち、認可保育園をつくらないとは言ってはいないのですよ。幼保一体化でつくっているけれども、とっても消極的で間に合わないという言い方を、この間、しているんです。これは区立ですよね。その辺で、方針が変わって、民間活力とは言っていますけれども、認可保育園をつくりながら解消していくというおつもりになっているのかどうか、そこを聞かせてください。","respondent":"吉岡保育課長","answer":"いろいろな施策の中で、組み合わせによって、多様な展開を図っていくという説明をしてまいりました。そういう中で、認可保育園についても開設をしてきましたし、これからも民間も活用しながら開設をしていくと、そのようにご説明申し上げているところです。","id":"exchange-123"},{"speaker":"飯沼委員","kind":"質問","question":"今年も、速報値で、４４１名が入れないという実態がきっちりあると思うんです。この間の区の施策を見ていますと、幼保一体化の中で、この１２年間で５カ所しかできていないんです。この間の１２年間を見ると、認証保育所が１５カ所できています。やはり、認可保育園の増設による待機児解消を基本に据えていく方針に切りかえていかなければ、今の状況は変わらないと思いますが、いかがでしょうか。","respondent":"吉岡保育課長","answer":"区としては、いろいろなニーズにこたえるために、認可保育園はもちろんですけれども、認証保育所、保育ママ、あるいは、短時間保育室等々、預かり保育も含めてさまざまな施策で対応をとっているというのが、今までのご説明です。","id":"exchange-124"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、これって異常だと思うんですけれども、いかがですかね。その間に、認証保育所が１５カ所、また、続々と増えていくことと思いますが、いつまでもこんな民間頼みでいいのでしょうか。それから、いずれ少子化がくるという認識でいいのでしょうか。ぜひ、経済効果も高いので、保育園をつくるという方針に転換をしていただきたいんですけれども、いかがでしょうか。","respondent":"吉岡保育課長","answer":"その中でも、女性が働きたいというニーズは高まっていることも承知していますし、それに対応するために、働くといっても、フルタイムで働かれる方から、短時間で働かれる方までいろいろな就労形態がありますので、それにこたえるためにも。","id":"exchange-125"},{"speaker":"飯沼委員","kind":"意見","question":"多様ということなんですけれども、今年、一次で４４１人が入れなかったということは、これは自治体がこたえていないということだと思うんです。それから、ぜひ、少子化を防いでいくという積極的な、経済的な効果がどんどん上がっていくという意味では、今、お金がかかっても、将来的な予測においては、効果が絶大だと思うんですが、もう１回、そこのところ経済的なことをお答えてください。","respondent":"吉岡保育課長","answer":"何回も繰り返しになりますけれども、さまざまな施策で保育をご提供する中で、就労ですとか、社会進出ですとか、そういう女性のお手伝いもしています。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"確認です。ほかの委員からもご質問がありましたけれども、ワクチン、今、４名、死亡されたということで痛ましい状況になっていますけれども、これは確認です。それから、厚生労働省の考えはどうであったのかということを確認しておきたいと思います。そして、今回、補正がかかっていますけれども、補正をするという意味が、平成２２年度においてはどういう意味合いを持っていたのかというところです。","respondent":"吉田保健予防課長、安井子育て支援課長、金子企画財政課長","answer":"当初、予算を作成した段階では、子ども手当として計上させていただいたところは、子ども手当の中学生分、児童手当の所得制限を超えた部分、それから。ですので、例えば、再三出ております庁舎の耐震改修工事につきましては、本来、予定では今年度内に終わるつもりでしたけれども、予算の当初のところでは。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"明日から平成２３年度予算のほうに入っていきますけれども、多分、その予算の中でいろいろ議論していきたいと思いますけれども、ただ１点だけ、区の負担はあったのか、なかったのかというところだけ、お聞きしておきたいと思います。それから、繰越明許費、そうすると、議会のほうではオーケーだと言われる項目については、こういう手法が取ることができるという認識でよろしいでしょうか。","respondent":"安井子育て支援課長、金子企画財政課長","answer":"ただ、従来、児童手当で所得制限をなくしていた時代は、１２億円ぐらい区の負担がございましたので、逆に７億円ほど減ったというような形になったものです。繰越明許費につきましては、必ず議会の議決を経るということになっておりますので、それが必要です。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"繰越明許費は、事業の内容、こういうものについてはできるけれども、これはできないというくくりはあるのでしょうか。今のご答弁ですと、すべての全部の事業に対して、こういう繰越はできるのだと認識してしまうのですが、そこでの、国の補助金等との関係もありますので、その縛りはないのでしょうか。","respondent":"金子企画財政課長","answer":"事業のものによっての制限というものはございませんけれども、あくまでも単年度独立主義の例外措置であるです。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"４８ページの国庫補助金、１０３ページの小中一貫校に関連して、質問します。これが、民生費だ、教育費だといろいろ入ってきているんだけれども、その辺の取り扱い方はどういう基準で、この一括交付金として変更しているのか、そのあたりを教えてください。","respondent":"藤橋都市整備下水道課長","answer":"そのほかに、いわゆる都市公園の整備ですとか、防災関係の事業につきましての市街地整備というくくり、それから、四つ目が住宅関連の地域住宅支援という事業がございまして、この四つの分野にかかわるものが、大体社会資本整備総合交付金としていただいている事業です。","id":"exchange-130"},{"speaker":"須藤委員","kind":"質問","question":"もう一つ、質問は、１９億円幾らという数字が下がったのか、上がったのか、それとも同じなのか。そうすると、一括交付金といっても、今、国で言っているのは、自治体で何に使ってもいいという話ではなくて、そういう縛りがありますよということで理解をしておいていいのか。そのあたりの見通しを教えてください。","respondent":"金子企画財政課長、藤橋都市整備下水道課長","answer":"１回前の質問で恐縮なんですけれども、土木費だけではなくて、民生費、衛生費、教育費でこれを充てております。今の国の動きですけれども、平成２３年度の国土交通省の予算の状況で見ますと、いわゆる一括交付金化に伴いまして、社会資本整備総合交付金ができましたけれども、来年度以降、先ほど申しました現行の四つの分野を統合して。","id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"わかりました。そのあたり、今、やめている自治体が幾つかあるというのが、新聞にも載っているんですけれども、やめている自治体があるというと、また何かのときに、これはだめなのでこんなにやめているという話になってしまうといけないので、そういうところと比較して、しっかり品川区は成功した事例ですと、そこには載せてあるんですけれども、そのあたりについては、いかがお考えか、教えてください。","respondent":"和氣学務課長","answer":"一方で学校を支援し、それぞれが特色ある教育活動をやっていく、その中で、学校自身が自己革新をしていけるような、そういう一つの契機にもしてまいりました。","id":"exchange-132"},{"speaker":"須藤委員","kind":"質問","question":"今のお話を伺って、逆に、品川区はしっかりしている、範を垂れている一つの自治体であるという模範になってこようかと思うので、そのあたり、今、言ったように、いろいろ出てくると思うので、そのあたりの、緻密にやっているとか、地域性とか言われたけれども、もう一度、お答えいただければと思います。","respondent":"和氣学務課長","answer":"そういう意味では、私どもはしっかり考えて進めておりますので、引き続き進めてまいりたいと思っています。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"私は、７５ページ、総務管理費の基金積立金追加分、１０１ページ義務教育施設整備基金について、お聞きしたいと思います。トータルだと、１１７億円の見込み額を出しておりますが、ほんとうに今回の補正の中で際立った金額を出しているんですが、こういうふうなことでいいのでしょうか。ちょっと何かやりようがあったのではないかと思うので、その辺についてご見解をお聞かせください。","respondent":"金子企画財政課長","answer":"ですが、こういうものについては、きちっと翌年度で手当をして実現するというふうに、そういう意味では、私どもの予定した事業を、地域経済、また区民生活について支えるために、きちっと実行してきております。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"年間予算１,４００億円で、１０％以上が要は固定という形で、次年度は使うというのはわかります、わかりますが、毎月ちゃんと、品川区は収支を出している以上、ではここで品川区の単独予算で、今、品川区の経済状況も大変だというのはよくわかっていると思うんですが、そういうところに補正を持っていって、そちらで区民生活を下支えする、区内経済、地域経済を盛り上げる、そういうふうな使い方を。","respondent":"金子企画財政課長","answer":"平成２３年度におきましても、先ほどご説明したとおり、比較的小規模な工事については、ゼロ債を活用して、新年度当初から中小企業者が受注できるようにということで、そういった経済対策にも取り組んでおります。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"別に、区で皆さんがしっかりやられているんですから、私は、それはそれでもちろん評価をしております。まして、単独予算で、単年度で、単発でもいいですから、臨時予算という形でもいいから、これは残りそうだなと思ったら、そこは経営会議でも開いていただいて、区民のために使おうかということも必要なことではないかと思うんですが、再度、お願いいたします。","respondent":"金子企画財政課長","answer":"そういう意味では、もちろんさらに区民のニーズにこたえること、区民に対して必要な事業を実施していくということが必要なことかもしれませんけれども、私どもとしましては、さまざま努力した中で、そういったものについてはすべて考えてやってきているという自負はありますが。","id":"exchange-136"},{"speaker":"若林委員","kind":"提案","question":"１１２ページの繰越明許費の中から、商店街電線類地中化。それから、１１６ページからの債務負担行為の中から、百反歩道橋のお話、堺委員のほうからもありましたけれども、改めて、バリアフリーについて、しっかりと取り組んでいただきたいということを提案させていただきたいんです。いわゆる百反隧道、ご存じのように、なかなか自転車、歩行者が通りづらいというところがあります。","respondent":"藤橋都市整備下水道課長、三宅都市開発課長、宍戸施設整備課長","answer":"今、繰越明許費につきまして、１０ページ、それから１１２ページで電線類地中化につきまして。百反歩道橋ですけれども、東西両側にエレベーターをとりつける予定にしております。この中で、おおよそですが、今後、かかるであろう主要部位の改修工事等にかかる経費についての集計をしておりまして、現在。","id":"exchange-137"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、５０年から６５年という耐用年数にもっていくことで、施設のコスト削減をしていくということになってきますので、そうすると、先々見えてくるわけですから、先ほどの答弁ではありましたけれども、公共施設整備基金とか、義務教育施設整備基金とか、こういうところでの対応というふうになっていくのかなと、そのための積立も含めてというふうに理解をしているんですが、いかがでしょうか。","respondent":"藤橋都市整備下水道課長、久保田行財政改革担当課長","answer":"これにつきましては、今後、全体事業のスケジュールについて、改めてチェックをいたしまして、今、平成２４年度の完了予定という形で、地域にはお話ししていますけれども、事業にはかなり時間を要することが考えられますので。その中では、やはり利用実績、または利用者の利用形態等も詳細に分析をして、そうしたデータのうえで施設の有効活用を図っていくということで、例えば施設の多目的化とか、複合化といったものも視野に入れながら。","id":"exchange-138"},{"speaker":"若林委員","kind":"意見","question":"ちょっと基金のお話が出なかったんですが、施設の有効活用プランは、今後の行財政改革に向けて、大変重要な基礎データとなると思いますので、ぜひとも、早急なプランの策定を、と思うんですが、予定はありますか……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"林委員","kind":"提案","question":"そこで、この補正予算の、先ほど来、ずっといろいろ出てきました、繰越明許費がこれだけ数多く並べられる、それから、ゼロ債のために債務負担行為がたくさんあるというのは、それはそれで、我々も何年か前に、ゼロ債務を使って行政のサービスがスムーズに進むようにという提案もしてきましたから、債務負担行為についてはわかるんですけれども、この補正予算を認めるうえでは、我々議会としては。","respondent":"金子企画財政課長","answer":"これにつきましては、ご説明でも申し上げましたとおり、かなり多くのものを中小企業者のために早期発注できるように設定したものでありますが、今、ご議決をしていただきましたら、早速事務も進めている部分もありますが、今年度中に契約を整えて。","id":"exchange-140"},{"speaker":"林委員","kind":"質問","question":"比較的そんなに大きい金額の債務負担行為ではないから、あまりゼロ債と大手を振って言うよりも、これから審議をする平成２３年度の予算が成立すれば、すぐに政策執行に動けるはずなんですよね。ゼロ債がなくても、４月に入ったら、一気に政策がスタートできるということも考えに入れておいてほしいと思います。まとめて最後にというスタイルではなくなるんですか。","respondent":"金子企画財政課長","answer":"ですが、これについては、先ほどもちょっと申し上げましたとおり、当初から別の節で入ってくる予定になっておりましたので、その事業については執行については、支障なく進めていくべきものと、私ども考えておりますので、そういう点につきましては、できる限り。","id":"exchange-141"},{"speaker":"林委員","kind":"質問・要望","question":"少し細かく聞いていきます。有名なプロ野球選手が、宮崎へ１,０００万円の納税をしたという話が、この間、ニュースで流れていましたけれども、品川区として、本来なら品川区に払ってくれるものが、よその自治体に行った、逆に行くものが品川区に入ってきた、そういうものを、資料としてわかるなら出していただきたいと思います。","respondent":"榎本人事課長、武内税務課長、太田品川区清掃事務所長、三宅都市開発課長","answer":"１１１ページの明細のほうは、補正後と補正前というのが、段がちょっと逆になっているんですけれども、補正前が下の段の２４億円。控除額として、住民税関係、都民税との合計ですけれども、９１０万円ほどの減税をしております。そういう意味で、当初予想した経費が、実際にかかった金額を下回った場合の２分の１を。ですから、再開発事業そのものに影響があるというものではないと認識しております。","id":"exchange-142"},{"speaker":"林委員","kind":"質問・要望","question":"最後の再開発の建物が、もう分譲が始まっているというか、モデルルームもできてやっているわけで、いわゆるあそこに住んでいた方々が土地を提供して、開発を進めているわけですから、区も知らないということにはならないようにしておいていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"土井委員","kind":"提案","question":"それと、国民健康保険料の収納率とのかかわりについて、お伺いをしたいと考えています。そこら辺について、お伺いをしたいと思います。生活保護受給者は、逆に、そんなこと関係ないのではないかと思うんですけれども、そこでこの料金なんかも含めて面倒見ているのではないでしょうかとなるので、そこら辺の関係を、どのように把握されているのか、そしてどう対応されているのか、ちょっとお伺いします。","respondent":"金子企画財政課長、平澤生活福祉課長","answer":"委員ご指摘のとおり、幾つか補正予算という形でご議決をいただかなければならないものもありますが、それ以外の中では、やはり平成２２年度の結末といいますか、確認をいただいて、そういう意味では。はじめに、４７ページ生活保護費、財源更正の７,７８４万２,０００円につきましては、平成２１年度におきまして、国庫負担基本額が決算額より少なかったということで、生活保護の場合には、法に基づきまして、４分の３が国。","id":"exchange-144"},{"speaker":"土井委員","kind":"質問","question":"そういうことでよろしいのですよね。中には、みずからの思いで、こんなものは払わないと思っていらっしゃる人もいるかもしれないけれども、そういうことなのかどうかということで、もう１回、お伺いします。書かれていないのは、どういう意味と解釈したらいいのかということも含めて、ちょっとお伺いさせていただいたんです。固まりで出てきて、こちらで分けるのでしょうか。","respondent":"本城国保医療年金課長、金子企画財政課長、藤橋都市整備下水道課長","answer":"そのうえで、保険料を滞納されている方というのは、そういう意味では、生活保護ではない国民健康保険の加入者ということで。４９ページ等の財源更正が載っているものと、載っていないものの違いですけれども、財源更正と載っていないものは、基本的には。来年度以降については、まだどのような形になるかわかりません。","id":"exchange-145"},{"speaker":"土井委員","kind":"質問","question":"その辺のことも含めて、どのように考えていらっしゃるのか、現状では、どのように受けとめているのかということを、ちょっとお伺いしたい。それによって、先ほどの話を聞くと、何も変わらないみたいにも聞こえるので、ほんとうに変わらないのかということで、なぜこういう名前のものが意図されているのかということをも感じてはいけないのか、どうなのかということで、お伺いしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"いわゆる手続上の話でいきますと、来年度予算については、あくまで国からの内示が、４月１日にならないと全くおりてこないので、現段階でここで、どういった状況になるかというのを正確にお答えすることはいたしかねますが、いわゆる来年度予算のポイントの中で。","id":"exchange-146"},{"speaker":"土井委員","kind":"質問・要望","question":"それは、不足しているものは、ぜひ注文を出していただきたいと思います。それから、先ほどの国民健康保険の関係ですけれども、となると、ここに徴収率、９割方と思っていたんですけれども、それがないというこの状況の原因、対策について、ちょっとお聞かせいただきたいと思います。","respondent":"本城国保医療年金課長","answer":"現在、収納率につきましては、先ほど、申し上げましたように、約８３％程度の収納を見込んでいるところです。","id":"exchange-147"},{"speaker":"土井委員","kind":"質問・要望","question":"ぜひ、フォローしていただきたいんですけれども、いろいろな形で収められない、納めないという、そのいろいろな形のところが何なのだろうか。そうしないと、何をやっていいのかわかりませんから、そこら辺を、いろいろなヒアリング等も含めた中で、どのように把握されているのかということを、ちょっと聞かせてください。","respondent":"本城国保医療年金課長","answer":"国民健康保険の加入者、全部で６万数千世帯ということでございまして、一度でも滞納がある世帯の方ということになりますと、そのうちの２２％程度で、１万８,０００世帯ぐらいになってきますので、逐一すべて把握しているわけではございません。","id":"exchange-148"},{"speaker":"土井委員","kind":"質問","question":"だから、確信犯で、こんなものは払わないという、お金はあるけれども払わない人も中にはあるのかもしれませんし、そこら辺の状況を把握することと、何万世帯あると言っても、そのうち、何カ月か知りませんけれども、どう見るか知りませんが、継続的にやっている人なんかは、そうそうたくさんいらっしゃるわけではないだろうと思うので、そこについては、少なくとも類別的にこういうのが多いとか。","respondent":"本城国保医療年金課長","answer":"私どものやりとりだけではなくて、いわゆる多重債務ということで、法的問題も解決しなければいけないような方については、例えば法テラス等、専門の機関等も紹介しながら、そういった多重債務とかを解決しながら国民健康保険料の納付にかかわるご相談もあわせてしたり。","id":"exchange-149"},{"speaker":"宮崎委員","kind":"質問","question":"私は、９７ページの北品川五丁目第１地区、補助金の更正減額について、何点か伺いたいと思います。もう既に何人かから質問がありましたけれども、改めてちょっと伺いたいんですが、進捗状況を改めて聞きたいと思います。ネックが、ほかに何あるのか、どうなのか、改めて伺いたいと思います。","respondent":"三宅都市開発課長","answer":"北品川五丁目第１地区ですけれども、リーマンショック後の景況の変化に対応するために、設計見直しなどを、これまでやってきまして、工事費の低減を図る、あるいは設計の見直しによって共用部分を少なくするといったような工夫を重ねて、事業費を変えてきてあります。","id":"exchange-150"},{"speaker":"宮崎委員","kind":"質問","question":"今、設計の見直し、工事費の軽減というお話でした。当初、この事業費、２６４億円ぐらいだったかと思うんですけれども、その変化がどういうふうになったのかを、一つお伺いしたいと思います。この開発は、もともとは３００％の容積率を、いろいろな名目でどんどん増やしてきていますよね。これはもう、権利変換ができれば、あとはすんなりいくという状況なのでしょうか。","respondent":"三宅都市開発課長","answer":"容積率を割り増しているけれども、事業に余裕がないのではないかというお話ですけれども、事業費の見直しもいたしまして、着々と手続を進めているところで、今それが権利変換の段階にあるですので、特に何かこれ以上の問題は、今のところはございません。","id":"exchange-151"},{"speaker":"宮崎委員","kind":"質問・要望","question":"どういうふうに帳尻を合わせてきているのか、そのやり方と考え方をお伺いしたいと思います。それから、権利変換のところは、南地区の場合は、取り壊す建物の補償金を増やすんだということで、８億円増額しました。今、権利変換、ここでも９５％まできたんだけれども、あと５％分がうまくいかないという話なんですけれども、南地区でやったような手法、そういうのはここでも考えているのでしょうか。","respondent":"三宅都市開発課長","answer":"補助金の額の変更についてですけれども、平成２１年当初、２６０億円でございましたが、現在、見直して２２０億円になってきているわけです。","id":"exchange-152"},{"speaker":"宮崎委員","kind":"意見","question":"今回も、今、権利変換がうまくいかない場合には、そういうことをやるのか、どうなのかということを聞きたいということです。そうすると、実際に今参加組合員が何者あって、保留床が何床あって、参加組合員は全部確保するという見通しになっているのか、どうなのかということを聞きたいと思います。","respondent":"三宅都市開発課長","answer":"北品川五丁目第１地区の参加組合員の数ですが、ちょっとすみません手元に正確な数字がございませんけれども、北品川五丁目第１地区は参加組合員が６者になってあります。それから、北品川の保留床ですけれども、面積にしまして約１０万m2が予定されております。","id":"exchange-153"},{"speaker":"宮崎委員","kind":"質問","question":"今の１０万m2保留床のうち、参加組合員は、全部１０万m2を全部割り振るということになったのか、どうなのかを聞きたいと思います。エンドユーザーにどのぐらい販売されているかというのは、企業秘密なんだということなんですけれども、そうすると、再開発というのは、結局参加組合員に渡せば、それで終りということなんでしょうか。","respondent":"三宅都市開発課長","answer":"１点目ですが、１０万m2の保留床ですけれども、これは基本的に参加組合員のほうで、負担金に応じて取得をするという予定です。","id":"exchange-154"},{"speaker":"三上委員","kind":"質問","question":"どういう性格のものだったのでしょうか。だから、そこらあたりが、ちょっとどういう形で計画を進められてきたのかということです。品川区として、こういった商店街に対して、常日ごろから密接に連携を取り合って、こういう事業がありますとかという呼びかけとか、今日までずっとされてきて、それでなおかつ、９６６万３,０００円を更正減額せざるを得なかったのか、ここらあたりちょっとお伺いしたい。","respondent":"金子企画財政課長、吉岡保育課長、諸岡商業・観光課長","answer":"地域活性化・住民生活に光をそそぐ交付金についてのお尋ねでありますけれども、これは国の１０月補正で成立したものでありまして、それ以降、細かい日程は。お寺の人が場所がわからなかったというお話なんですけれども、一応、保育園自体は社会福祉法人の大宝会という団体が設置をしている形になってありますので。小規模商店街の再生モデル事業等についてですけれども、制度につきましては、毎年の商店街に対する説明会等を含めて。","id":"exchange-155"},{"speaker":"三上委員","kind":"質問・要望","question":"人件費にも使えますというような話がずっとあったりして、そうなったときに、この交付金を使い方によっては、申請をもうちょっと多額にできたのではないかと思うんですけれども、そこらあたりはどうだったのでしょうか。それから、宝保育園については、ここは予定より遅れたということは、どういうことが理由だったのか、ちょっとお伺いしたい。","respondent":"金子企画財政課長、吉岡保育課長","answer":"地域活性化・住民生活に光をそそぐ交付金のお尋ねでありますが、これは、ご指摘のとおり、国全体で１,０００億円という金額でありましたけれども、その中で、特別区につきましては割り当てが少なくて。宝保育園の移転が遅れた理由ですけれども、施設の移転にあたっての設計等を担当しておりました設計事務所が、いろいろな計画等を全部やっていたんですけれども、移転先の土地の中に東京電力の電柱が３本立っておりまして。","id":"exchange-156"},{"speaker":"三上委員","kind":"意見","question":"それぞれよくわかりました。商店街については、ご答弁をいただかなかったんですけれども、そういった点で、小さいところ、それこそ２０人とか、それ以下のような商店街もあるんですよ。そういったところは、やはりそういった情報については、なかなか入らない。そういったところについて、ぜひ、緻密に品川区はしっかりと商売発展のためにご尽力いただけるようにお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-157"},{"speaker":"松澤委員","kind":"確認","question":"大分おそくなりましたけれども、しっかりと４点、お伺いしたいと思います。４０ページの特別区民税についてと、１２ページでしょうか、債務負担行為補正、たくさん出ましたけれども、百反歩道橋架替整備工事委託、それから、４６ページ、土木手数料、建築確認手数料について、それから、９９ページ、避難道路機能強化事業、１,８１０万円の減額について。","respondent":"武内税務課長","answer":"この補正の内容を見込み違いという部分ですけれども、当初、納税義務者を、普通徴収については９万人、特別徴収については１２万人ということで、それぞれ決算というか、先ほどお話ししたとおり、６月の調定、当初賦課をしたときとの人数の差があります。","id":"exchange-158"},{"speaker":"松澤委員","kind":"質問・要望","question":"結局、数字ですから、当然、動くのは当たり前なんですけれども、２年連続収入減で、うわあ、景気がまだまだこんなに悪いんだという中で、実際には、当初予算の２３億３,７１０万円の減額が半分で済んでいたということになると、あれっ、何だこれはと思いますよね。","respondent":"武内税務課長","answer":"この辺のところがぶれますと、全体的な政策がぶれてくるということになりますので、税務課職員、心を改めまして、このような算出方法について、いま一度、しっかりやっていきたいと考えておりますので、よろしくお願いします。","id":"exchange-159"},{"speaker":"松澤委員","kind":"質問","question":"２点目に移ります。百反歩道橋、今日は一番質問しましたよね、やはりそれだけ関心が高いんだと思います。ところが、ここは何ｍかずれても、当然、関係ないと思うので、この路線が１cmたりとも動いていないのか、動いていないとしたら、何でもっといい形に動かせないのかということが１点。それから、わかりましたら、ランニングコストがどれぐらいかかるのか、聞きたいと思います。","respondent":"三宅都市開発課長","answer":"ランニングコストですが、電気関係の費用も含めまして、年間二、三十万円を見込んでおります。","id":"exchange-160"},{"speaker":"松澤委員","kind":"質問・要望","question":"私の近所の方も、あそこはどうなっているかという中で、２年後にはできる、エレベーターで自転車が上がれるんだというようなお話をしてきました。３点目で、土木手数料、建築確認手数料、１１１万７,０００円の減額、７４件とあります。これは、民間が参入してから、毎年減っているんですよね。その数の推移、それから、今期、最後の結果、数字的なものをお知らせいただきたいと思います。","respondent":"中村建築課長","answer":"建築確認申請の推移です。平成１９年から平成２１年度にかけまして、品川区の確認の総件数ですけれども、平成１９年度が２１９件、そして、平成２０年度が２３４件、平成２１年度が１４０件、平成２２年度が、今、おおよそ１１０件ほど見込んでおります。","id":"exchange-161"},{"speaker":"松澤委員","kind":"確認","question":"民間のほうが便利なんでしょうか、どんどん数が減っている。私たちが心配するのは、やっぱり品川区の確認申請ですから、品川区でやったほうが安心できるということと、つい先日も建設委員会で、マンション紛争の陳情があったんですけれども、確認申請出ているんでしょうかって聞いても、わからないんですよね。思うのは、確認申請そのものが、品川区は委託をしているのでしょうか。","respondent":"中村建築課長","answer":"ただ、法の規制によりまして、一定規模以上の構造計算におきましては、第三者に委託をしてピアチェック、ダブルでチェックするということがありますので、そういったものは、第三者機関に委託しなければいけないものもありますが、これも品川区の職員が。","id":"exchange-162"},{"speaker":"松澤委員","kind":"質問・要望","question":"時間がないからあまり言いませんけれども、やはり職員で一級建築士を持ってしっかり頑張っている方もいると思うので、その人の腕の奮える場所がなくてはいけないので、これはしっかり品川区、頑張って民間から取り返せるように、どうすれば取り返せるかというのは、なかなか難しいと思いますけれども、ひとつ考え方があったら、１点、お聞かせいただきたいと思います。","respondent":"中村建築課長","answer":"品川区と民間の差はどこにあるのかというのを考えましたときに、一つは、建築確認の申請から、確認の処分がなされるまでの時間、この差がどのぐらいあるのかというところで、参考までに、平成２１年度の、確認申請からおりるまでの平均の日にちを計算してみましたところ。","id":"exchange-163"},{"speaker":"松澤委員","kind":"質問・要望","question":"ＰＲをしっかりとしていただきたいとだけ述べておきます。これは１,８１０万円減額。１,５９０万円というと、道路に面した角地あたりだと、坪１５０万円とすれば１０坪ぐらいしかありませんから、当然、予算を計上するには、話し合って買えるという見込みのもとでやっているんだと思うんですけれども、なぜこれが買えなくなってしまったのか、この点について、時間がないですけれども、お願いします。","respondent":"品川防災整備担当課長","answer":"前年度、見込みがある土地について２件挙げていたのですが、家族間の意見の食い違いとか、いろいろございまして、なかなか用地を売るということの決定までに至らないというような関係がございまして、今回、打切りとしています。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/779540?Template=document&Id=946#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":132103,"voices":408}},{"id":"h23-20110308-3","meetingId":"h23-c-budget","date":"2011年3月8日","dateIso":"2011-03-08","committee":"予算特別委員会","time":"午前１０時０２分～午後６時０７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を154件抜き出しています。","topics":[{"id":"topic-01","title":"平成２３年度品川区一般会計予算","agenda":"平成２３年度品川区一般会計予算","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"１３４ページの競馬組合配分金、それから、６６ページのシルバーセンター使用料、それから６３ページのこみゅにてぃぷらざ八潮の使用料について伺いたいと思います。最初に競馬組合の配分金なんですが、改めてこの配分金というものはどういうものなのかといったことをご説明いただきたいと思います。","respondent":"伊勢総務課長","answer":"それで本場の所在区に充てる３億円については変わりがないんですが、他場の売り上げ、これは本場も同じですけれども、年々売上高が下がってくるということで、そこの部分で少なくなっている、こういう状況です。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"つまり、売り上げが上がれば、この配分金ももちろん上がるといったことで、前回の委員会、決算特別委員会だったかと思うんですけれども、新羽田空港が開港して、外国人を取り込むといったことをしたらどうかといったことを私ども自民党からも発言させていただいたと思うんですけれども、そういった、競馬場を盛り上げるといった意味で、それはもちろん品川の収入になるわけですから。","respondent":"伊勢総務課長","answer":"特別区競馬組合でも振興策、いろいろ考えてございまして、その１つに、外国人観光客の誘致ということで、東京の夜の楽しみと、それからトゥインクルレースの認知を図って、外国人の観光客を誘致する。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"もう今がチャンスだと思うので、そのあたり、設置区である品川区といたしましても、これは大いに声を上げていくといったことをお願いしたいなと改めて思います。つまり、新規の方がなかなかそこを利用していただけないといったことも聞いておりますけれども、そういった意味で、こういった新規の方を取り込むような区の考え方というのは何かあるのか、教えてください。","respondent":"間部高齢者いきがい課長","answer":"考え方といたしましては、現在、老朽化した建物の改修工事を随時進めているわけですが、それに伴いまして、魅力あるシルバーセンターづくりということで、介護予防拠点を整備したりですとか、例えば南品川のシルバーセンターであれば、ほっとサロンを併設するなど。","id":"exchange-003"},{"speaker":"山内委員","kind":"確認","question":"かたや、１けたのところもある。こういったところにどうやって手を入れていくのかといったことが、これからひとり暮らしの高齢者等も多くなってくるといったことで、安否確認、それから先ほど申し上げたように、介護予防施設、介護予防といった形での施設といった形で、利用していただくといったことも非常に大事なのかなと思うんですけれども、そのあたりはどうお考えでしょうか。","respondent":"間部高齢者いきがい課長","answer":"目的外使用につきましても、従来は７日前までの予約ということを実施しておりましたが、今年度ですけれども、１日前までにご予約いただければ使えるようにしたりですとか、また、品川区の高齢者クラブ連合会の会合などでも、空き状況をお知らせするなど。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問・要望","question":"ただ、やっぱり利用者が断定されちゃっているところもあるといったところもありますし、そういった意味で、区のほうでもひとり高齢者の安否の確認とか、そういった、これからの高齢者対策といった形で、このシルバーセンターというのが大きな役目を果たしていくのかなという思いもいたしておりますので、そのあたり、目的外使用というところもありますけれども、その辺は、目的外でも。","respondent":"堀越文化スポーツ振興課長","answer":"そのほか、利用される種類によっては、なかなか文化センター等では空き室がなくてご利用できないという団体の方にも、ご紹介するほか、それから、部屋の特徴といたしまして、こみゅにてぃぷらざ八潮の地域交流室は、鏡を張ったダンスバーも設置して。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"新年度から本格的にということなんですが、もうオープンして１カ月ぐらいたちますよね。それに対して、これはちょっと款が違っちゃうので、総務費を見ますと、運営費が８,９９３万円という大変多額な運営費をかけて、この施設を１年間運営をしていくといったことなんですけれども、このあたりのお金の入りと出、そういったことも含めてどうお考えなのかといったところを伺いたいです。","respondent":"堀越文化スポーツ振興課長","answer":"３月の利用については上向きの状況にあります。運営費ですが、他の文化センター等と比べましても、同等程度の経費、コストの率だと把握しております。そのほか、効率的な運営に努めて、ＰＲには今後も努めていきたいと考えているところです。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問・要望","question":"最後の運営費なんですけれども、これだけの運営費をかけて、他と同等のとおっしゃいました。確かに八潮、行きづらいです。じゃないと、区民からどんな声がこれから来るかといったこともわかりかねない。そういったところで、しっかりと運営といったもの、これからの運営といったものをしっかりと行っていただきたいなという思いがいたします。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"金野委員","kind":"確認","question":"まとめて３点質問いたしますが、１点目の児童手当、子ども手当、確認ですけれども、この予算書に記載されております手当の給付金、事務経費、これはどのような予算かというのを確認、１点。その点、本区としてはどのような対応なのか、確認をさせてください。２点目に、区民住宅の共益費、あるいは管理費ですけれども、この経費の内容をまず確認させてください。お願いします。","respondent":"安井子育て支援課長、柏原住宅担当課長、冠木指導課長","answer":"子ども手当につきましては、現在国のほうで法案として出されている、２月１０日現在で出されているような法案の内容に基づきまして、予算計上しています。私からは区民住宅共益費等に係る部分です。共益費の部分ですが、区営住宅につきましては、５団地について共益費をいただいております。理科の指導力向上事業実施委託金ですけれども、この事業は国の事業が都を通過して区に委託という形で来ているものです。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"１点目の手当の件ですけれども、例えばほかの自治体では混乱が起きそうだというところの点のご答弁がなかったので、もう１点お聞きしたい。品川区としてはどのように６月以降執行していくのかというのをもう１点確認をしたいと思います。できるだけ混乱がない。品川区といたしましては、所得制限がついていないので、どちらにしても想像はつくんですが、確認のためそれを教えていただきたいと思います。","respondent":"安井子育て支援課長、柏原住宅担当課長、冠木指導課長","answer":"子ども手当の関係につきましては、現在政府提案の法案が実施されるということを前提としてうちも進めるというような形で考えております。区民住宅の管理等につきましてです。８団地ある中、３団地、下神明と西五反田につきましては常駐しておりますので、そちらで対応しています。あるいは、ことし１月に入りまして、東海中学校と城南第二小学校で小中一貫した理科の研究の発表会をさせていただいたわけですけれども、そういった中で。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"私から９３ページと１１５ページにおける住宅・建築物耐震化支援事業の国と東京都の補助金について、冒頭大幅な増額とご説明がありましたが、そのねらいを中心に伺いたいと思います。昨年比で増額となった理由が何か、あわせてご説明いただきたいと思います。","respondent":"品川防災整備担当課長","answer":"耐震の補助金の内訳ですが、国が大体４５％、それから都が１５％、区の負担分が、大体ですが、４０％となっております。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"耐震設計のほうにも２０万円今回つきましたけれども、その内訳についても伺いたいと思います。今もご説明ありましたけれども、耐震診断から改修に結びつかない理由が、補助額を引き上げようということになったというご説明がありましたけれども、改めてどういう実態が区民の中にあるのか、そこにどのようなねらいを持って引き上げたのか、改めて伺いたいと思います。","respondent":"品川防災整備担当課長","answer":"大体半分ぐらいという意見が多かったので、今回大体３４５万円の半分とまではいかないんですけれども、大方１５０万円まで補助しようということで改正を考えております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"アンケートから見られてくる半分ぐらい、今回半分はいかないですけれども、そういう実態を見てということだと思います。そのためには、区民の実態や実情にしっかりかみ合った事業にしていかないと進まないと思うんですけれども、この点をどうお考えなのか、伺いたいと思います。さまざまな事情があると思いますけれども、こうした実態については、どう解決しようとお考えなのか、伺いたいと思います。","respondent":"品川防災整備担当課長","answer":"その中でも、まちづくり協議会とか民生委員協議会等、耐震化の制度を説明するだとか、広報に載せていくだとか、そういった啓発活動を進めていきたいと考えております。それから、２点目の経済的なお話ですが、品川シェルターについて、今回制度の要件の緩和を行いました。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"ただ、しかし、それがなぜ品川シェルターだけなのかということを伺いたいと思います。簡易補強について、工法の拡大については、どのようにお考えなのか、伺いたいと思います。それともう１点、耐震改修についても、高齢者、障害者などはいろいろ事情があるわけですから、耐震改修についても上乗せ補助や手続の支援など、そういった支援策も強めることも必要だと思いますが、いかがでしょうか。","respondent":"品川防災整備担当課長","answer":"初めに啓発についてですが、先ほどと繰り返しになってしまいますけれども、まちづくり協議会、それから民生委員協議会等、今区で行っている会合に参加をして、耐震制度の説明をしていくことを実際考えております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"ちょうど去年の第１回定例会でこのことを伺ったときに、アンケート調査の中であわせて検討するとご説明がありましたが、改めて推進体制の構築について早く行うべきだと思いますけれども、いかがでしょうか。区内業者への誘導策についてはどうお考えがあるのか、まず伺いたい。私は、区内業者は補助額を引き上げるなどの誘導策が必要だと思いますけれども、いかがでしょうか。","respondent":"品川防災整備担当課長","answer":"結局のところ、耐震化についても、防災まちづくりの中の一環ですので、この中で説明をしていきたいと考えております。それから２点目ですが、品川シェルター、それからほかに耐震シェルター、これは実に工期を短くできます。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"どこかにもちろん何でもありにはいきませんから、構造計算をどこまでやるのかいろんな議論はありますけれども、一定の図面があれば区内の業者でもできるという話も工務店から伺ったことがありますので、簡易補強の拡大というのはしっかり進めるべきだと思いますけれども、いかがでしょうかということです。","respondent":"品川防災整備担当課長","answer":"簡易改修については、先ほども申しましたとおり、Ｉｗ値、こちらが１以上のものでない限りは、いくら改修をしても、お金をかけて倒壊してしまうという危険性があるのであれば、やはりまだ区としては進めるわけにはいかないと考えております。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"住宅耐震化はやはり時間との勝負だと思います。Ｉｗ値１.０以上でなければならない、もしそうおっしゃるのであれば、高齢者や所得の少ない方、そういった方が世帯にいらっしゃる方、そうした方への上乗せの補助を行うべきではないかと思います。やはり実態にかみ合っていかないと進まないと思いますので、上乗せ補助についてはいかがでしょうか。","respondent":"品川防災整備担当課長","answer":"やはり簡易な改修につきましては、品川シェルター等を区としては考えております。","id":"exchange-016"},{"speaker":"稲川委員","kind":"確認","question":"７８ページ、土木手数料の建築確認手数料、建築中間検査手数料のあたりを聞きます。１３８ページの雑入の宝くじ等助成金収入についてお伺いいたします。昨日も最後の質問の中で、建築確認の手数料について質問がございました。平成２２年度は補正はされましたけれども、２４５件とか、そういう件数になっているんですが、その算出の方法はどうやられているのか、教えてください。","respondent":"中村建築課長","answer":"確認申請の申請件数につきましては、来年度の社会情勢はちょっと見込むことは難しいので、考慮しますのが、前年度の確認申請の実績と、それから確認申請の数の中には、当然のことながら、１件当たり、例えば確認申請をとって工事をしていく中でも。","id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"これ、平成２２年度の２４５件というのは、平成２１年度は１４０件という、きのうの話で１４０件の申請があって、で、この２４５件というのは前年度を比較してという、実績を見てという話なんですが、何でこんな数字が出たのか。もちろん現段階で平成２２年度は１１０件という、きのう、話をいただいているんですが、この辺、なぜか教えてください。","respondent":"中村建築課長","answer":"平成２２年、あるいは平成２１年度の数ですけれども、その前までが平成１９年ですとか平成２０年度、このあたりが建築の区に対する確認申請が約２３０件ほどございました。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問・要望","question":"１回私も昨年、新築着工件数ということを含めた質問をさせていただいたんですが、大体品川区って４,０００戸以上新築着工件数が年間あると思います。要するに４,０００戸は新築ということですから、建築申請が出されます。要するに、４,０００戸あるわけですから、４,０００件の申請があるのかなとか、そういう疑問があるので、教えてください。","respondent":"中村建築課長","answer":"住宅の着工統計、４,０００戸ということですけれども、これは１つの確認申請に対しまして、例えば共同住宅ですとか、長屋、こういったものにつきましては、大規模のものですと、申請１件当たりで１００戸とか２００戸、そういった共同住宅などもあります。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問・要望","question":"実際の件数というか、建物を１つ建てる部分、戸数というか、件数という表現なのか、これは何件ぐらいになるんですか。そこを１つ教えていただきたいと思います。","respondent":"中村建築課長、片田防災まちづくり事業部長","answer":"確認申請１件当たりの平均の戸数ということでよろしいでしょうか。それを統計で示したものですので、件数的にはかなり、例えば１,０００件ぐらいが４,０００件になったりという開きがあるので、その辺はご理解いただければと思います。","id":"exchange-020"},{"speaker":"稲川委員","kind":"意見","question":"ということは、要は品川区全体で約１,０００件、多少誤差はあるかもしれませんけれども、その建築申請がある意味出されているということだと思いますが、これも昨日触れられていました。要するに民間の審査会社というんですが、民間に今出されている部分で、品川区が大体１５％とか、そういう話もきのうしておりました。しかし、民間は高い。この理由としてはどういうことが挙げられるか。","respondent":"中村建築課長","answer":"ただ、確認申請がおりるまでの期間、これは平均での話ですけれども、３日というのは非常に建設業者にとりましては重要な時間でして、着工がおくれることによって１日当たりの利益がかなりの額になりますので、その辺の日数が非常に重要なポイントになっているのかと思われます。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"今、民間に流れていますが、当時一番多いときは、逆に言えば１,０００件まではいかないかと思いますけれども、品川区が全部審査をしていたわけですから、実際そこで仕事量が増えてしまうことが品川区にとってマイナスなのか、プラスなのか。私、やっぱり法の番人として行政がしっかりと、きのうも話出ていました、行政がしっかりとそういった部分、建築行政というんですか、やるべきだと思っています。","respondent":"中村建築課長","answer":"先ほど委員おっしゃいました法の番人ですけれども、確認申請そのものの審査業務につきましては、人間が１個１個審査をしていくものでありまして、手づくりの商品というものに近いかと思います。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"３０秒しかございません。１３８ページの雑入の宝くじの部分で、１点だけお伺いしたかったのですが、できなさそうなので、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"渡辺委員","kind":"質問","question":"私は７１ページの埋設管路、６５ページの公園の使用料、それと７７ページ、住民票写の手数料、この点、伺っていきたいと思います。初めに、７１ページの埋設管路のところで、ほかの款でも、項目でも出てくるとは思うんですが、特に比重の高いということで、道路占用料のところで伺いたいと思いました。","respondent":"井浦土木管理課長","answer":"こちらの占用物件の大半を占めるところにつきましては、電柱、あるいは埋設管路のガス管等が大半を占めてあります。","id":"exchange-024"},{"speaker":"渡辺委員","kind":"確認","question":"ちょっとよく聞き取れなかったんですけど、電柱等もあるという中で、ちょっと想像していたのが、ガスは下に別途の項目があったので、ガスは違うのだなと。で、結構な料なので、上下水道なんかも主力なのかなと思って、確認で伺いました。先ほどの主要な管というのは何かのもう一度確認をお願いします。","respondent":"井浦土木管理課長","answer":"お答えいたします。使用料につきましては、道路法、あるいは国土交通省の通知によりまして、土地の価格に一定の率を掛けまして算定するということで、東京２３区につきましては、２３区の平均の土地価格というものを算定しまして、それに一定の率を乗じて算定しているものです。","id":"exchange-025"},{"speaker":"渡辺委員","kind":"質問","question":"そうはいいながらも、一般区民から見れば、公共の道路という中で、そういう中でそういう管の老朽化等、あるいは配管を変える時期、工事等のときに、どうしてもやはり窓口的に映り方として品川区となる中という意味で、そういうトラブル等の未然の防止という意味で、調査をしたり、把握をしていたり、そういう老朽化も含めた、そういったことを品川区がどこまでかかわっているのか。","respondent":"井浦土木管理課長","answer":"埋設物についての管理も含めまして、これは道路調整会議ということで、年に数回定期的に、関係事業者、具体的には東京電力、東京ガス、ＮＴＴ等々、先ほど申し上げた公益事業者ですが、連絡調整、埋設箇所等の情報の連絡、あるいはトラブルについての対応。","id":"exchange-026"},{"speaker":"渡辺委員","kind":"確認","question":"というのは、老朽化というのも１つありますし、工事のときにどうしても区民の方の声で多いなと思いました。一般の映り方としたら、工事というのは幅広く移る中で、これも責任の所在がどこかによって、対応がスムーズであったり、わかりやすさが出てくるという意味で伺いました。回数の中で、利用の種目等は、ここの中に、野球場という中では野球だけなのか、それともほかも含まれるのか、確認でお願いします。","respondent":"堀越文化スポーツ振興課長","answer":"公園の施設の件ですが、野球場、それからサッカーの違いですけれども、野球につきましては、主に３月から１１月まで、野球の抽選になっております。そのほか、１２月から２月までがサッカーの抽選という形になります。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問","question":"経緯もあるでしょうが、優先受付の、抽選の受付の時期、自分も承知している中では、３月から１１月までの９カ月が野球であり、残りの冬場の３カ月がサッカーと。これは経緯もあると思うんですが、ところで、割合の区分はいつからいまに至るのか、教えていただければと思います。それと、ほかの球技場でも、規定の中で、種目による抽選の受付の時期、これもいつから今に至るのか、それを伺えればと思います。","respondent":"堀越文化スポーツ振興課長","answer":"そのほか、野球の人口、サッカー人口、潜在的な需要がどこまであるかというところまではなかなか見込めていないところですけれども、そういった区でのいろいろな連盟の団体の数、それから、施設予約システムに登録をされている団体の数、そういったことからあわせ考えますと。","id":"exchange-028"},{"speaker":"渡辺委員","kind":"意見","question":"限られた都市部の中の施設の有効利用という点で、こういった配分というか、これはとても大切なことだと思っています。その中の１つとして、土日の抽選の形、その抽選が終わった後、あるいは平日の申し込みという一般受付という中では、かなり実数というか、状況が見られるのではないかと思いますが、現時点ではどのように把握されているのか、お知らせください。","respondent":"堀越文化スポーツ振興課長","answer":"抽選と空き予約という形での個別の数字は、すみません、今、ちょっと手元に資料はありませんが、野球とサッカーと、そういった形でご利用いただいていると認識しています。","id":"exchange-029"},{"speaker":"渡辺委員","kind":"質問","question":"恐らく年の大半は、例えば片方の種目は抽選にまず参加資格がないわけですから、そういう意味ではかなりな頻度の数字になるのかなと思っています。次に行かせていただきます。品川区で、これまでそういったことが検討されていたことがあるのかどうか。その必要性も今、日曜開庁や各サービスコーナーで十分満ちているという思いの中で伺おうという、そういう思いです。","respondent":"原情報システム課長","answer":"駅等での住民票の交付の件ですけれども、現在ほかの区で実施しているのは２通りあります。区の中で自動交付機を設置して、いろんな公共施設のところで住民票を発行する。そういったものが従前やっておりました。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"８４ページ、８５ページの子ども手当、聞いていきます。先ほど質問がありまして、２月１０日の段階で、法案に基づき資料を作成したということ。これ、平成２２年度における子ども手当の支給に関する法律というものに基づいて予算がつくられたということです。もしそういう何かご質問とかが今までにあったかどうか、その辺含めて教えてください。","respondent":"安井子育て支援課長","answer":"いろいろ問い合わせ等、お電話でいただいております。現在国で審議中ですのでということで、今のところはそういう形ですというようなお話をしています。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"今、３月８日です。３月いっぱいでこれが決まらなければ、当然平成２２年度の法案ですから、なくなりまして、今まで平成２１年度まで行っていたこの児童手当に戻ると思います。大事なのは、先ほどほかの委員もありましたけれども、いかなる制度であれ、６月に支給してさしあげることが、これが一番大事だと思います。６月に支給するためには、事務を始めなければなりません。６月に配れますか。配れませんか。","respondent":"安井子育て支援課長","answer":"先ほども申し上げたところなんですけれども、最善の方法を持って対応していくというような考え方でおります。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう要望にしますけれども、幾つか要望します。余計な労力を使って、お金を使うわけですから、これは区としてかかわっているものはしっかりと事務費として申請してください。だけど、出ていかないというような状況になっているわけですから、ほんとうにこれは区民の方に対して、しっかりとどういうふうになるのか。周りの人たちも、ほんとうに品川区の動きに期待していると思いますので、これは要望します。","respondent":"井浦土木管理課長","answer":"お答えいたします。車体ラッピング広告等につきましては、まずバス、あるいは電車に広告物を塗装する、あるいはラミネートを貼付するというような形のものが対象になります。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"品川区内を通過するものが対象となりますということは、区内で見かける、いわゆる鉄道会社全部が結局申請をしているということなんですか。例えば今回、これを伺ったのが、屋外広告物の件数等出ています。品川区、景観行政団体になりまして、今度、東海道のほうとか、いろいろやっていくと思うんですが、それによる今後、この辺、何か影響があるかどうか、教えてください。","respondent":"井浦土木管理課長","answer":"屋外広告物と景観との関連ですが、東京都の景観条例に基づきまして、品川区内につきましては、看板の規制ということで、いわゆる既存不適格というもので２件ございました。２件とも除却しています。品川区の景観条例に基づくそのようなものは現在具体的には想定しておりません。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問","question":"今、その２件というお話がありました。過去において、過去においてといっても、そんな過去じゃなくていいんですが、最近でも、いろいろ手続をされてきた中で、これはだめだよとお断りすることというのは実際あるんでしょうか。","respondent":"井浦土木管理課長","answer":"広告物につきましては、屋外広告物法の中で、広告物のプロの事業者を通じて申請をするということで法が整備されておりますので、最近では、不許可になるというものについては、ありません。","id":"exchange-035"},{"speaker":"浅野委員","kind":"質問","question":"私からは７７ページの住民票写、住民基本台帳カード交付、それと５８ページ、総務使用料の中から集会所使用料、文化センター使用料、公園運動施設使用料、これ、全般にわたりまして質問したいと思います。たしか平成２２年度は６,７００件の目標で、昨年の決算のときにお伺いしました数からいうと、９月３０日までに１,８９７件発行されているということだったと思います。","respondent":"梶戸籍住民課長","answer":"ちなみに、先ほども申し上げましたとおり、７月から２月の件数につきましては、平成２１年度と平成２２年度を比べますと、１６％ほど増となっていますので、即日交付の効果、また、金額が１,０００円から５００円になったという効果が確実に出ていると考えているところです。","id":"exchange-036"},{"speaker":"浅野委員","kind":"質問・要望","question":"この住基カードですけれども、先ほども話がありましたとおり、これから、先の決算特別委員会でも質問させていただきました、コンビニでの住民票、また印鑑登録証の発行を検討しているという答弁をいただいておりますけれども、その後の検討状況、どのような進捗かということをお伺いしたいと思います。","respondent":"原情報システム課長","answer":"は検討状況ですけれども、先ほども答弁させていただきました。渋谷区をはじめ、２３区でも数区がここへ来て始めている状況もあります。全国的にも約３０の自治体でコンビニでの交付、こういったものが実施されております。","id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"この住民票などを発行する証明書交付センターというものがあるかと思うんですけれども、サービス提供時間が午前６時半から午後１１時というのがどうも既定路線で決まっているらしいですが、このような中で、セブンイレブンが今対応していると思いますけれども、他のコンビニでの対応状況、進めているかと思いますけれども、これがわかれば、簡単で結構ですので、教えてください。","respondent":"原情報システム課長、梶戸籍住民課長","answer":"他のコンビニでの検討状況ですけれども、まだ詳細につかんでいるところではございませんが、セブンイレブンがスタートした背景には、端末等、キオスク端末、いろいろ交付する端末に対して投資をそれほどかけずに発行ができる。住民票の写し等につきまして、どのぐらい金額がかかっているのかというお尋ねですけれども、住民票の写しにつきましては、例えば平成２１年度では２２万５,０００件という形で出てあります。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"将来的な住民基本台帳カードの展開ですけれども、図書館カードでありますとか、また公共施設の予約、またこれもポイントカードとして、地域通貨みたいな形でサービスを提供しているところもありますので、このようなこともぜひともあわせて検討していっていただきたいと思います。発行手数料も、将来的には下げることも含めて考えていただきたいと思いますが、答弁お願いします。","respondent":"梶戸籍住民課長","answer":"こちらの状況等につきましても、先ほど情報システム課長が申し上げたように、今後のさまざまな状況を見ながら、考えて、検討していきたいと考えています。","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問","question":"このコストの概念というのは、本来は質問したかった各種の使用料の件、こちらのほうもコストの関係で質問したかったんですけれども、時間がなかったので、また機会を見て質問します。どうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"４４ページ、特別区民税、５８ページの庁舎使用料、それと７２ページ、自転車駐車場使用料、それと１２６ページの基金繰入金についてお伺いしますが、財源についてまずお伺いしたいんですけれども、同じ制度で、そして同じ条件である２３区において、特別区において、いろいろ区によって財政が厳しい、厳しくないというふうに出てきますが、まずそれはなぜ出てくるのかということと、それとあと。","respondent":"武内税務課長、阿部経理課長、藤木交通安全担当課長、金子企画財政課長","answer":"平均で２％から３％、２３区の平均よりも高いというのが、区税の安定した部分があるのかなと考えています。庁舎の駐車場の貸し付けの件ですけれども、これは庁舎の耐震化が終わった後、７月１日から行政財産の貸し付けという方式で。現在の利用者数のうち、当日利用につきましては、現行維持する見込みですけれども、定期利用につきまして。公共施設整備基金であるとか、義務教育施設整備基金、これを基金として設定している理由は、やはりこういった施設ものに関しましては。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問","question":"ですけど、私はそこを変えていくべきだと思うんですね。自転車使用というのをもっと積極的にやっていく転換期に来ていると思うんですけれども、その辺はいかがですか。というのに当たって、例えば緊急経済対策に充てるための基金とか、そういう施設とかではなくして、そういう意味合いの基金をこれからつくっていったほうがいいと思うんですけれども、その辺についてはいかがですか。","respondent":"武内税務課長、金子企画財政課長、藤木交通安全担当課長","answer":"品川区におきましての税額の最高の方が、１億円以上の方が１人いまして、あと５００万円以上の方がトータルで３６５人、そういう納税義務者がいます。税外収入ですけれども、委員ご指摘のとおり、こういった厳しい情勢の中で、公有財産を有効に活用して、それで収入が見込めるものについては。現状では自転車の事故等増えておりまして、さまざまな総合対策をやりつつも、自転車の利用は自粛ということで引き続きやっていただきたいと思います。","id":"exchange-042"},{"speaker":"沢田委員","kind":"質問","question":"９７ページの国庫補助金の教育費補助金の図書館維持管理費についてと、１３４ページの諸収入の中の図書館資料等についてお伺いします。９７ページの国庫補助金の図書館維持管理費についてなんですけれども、これ、昨年度の予算には載ってなかったんですが、今年度これはどういった形で使われるのでしょうか。","respondent":"小川品川図書館長","answer":"こちらは、平成２３年度に二葉図書館の耐震改修工事を予定しています。","id":"exchange-043"},{"speaker":"沢田委員","kind":"質問","question":"今、図書館というのは、ほんとうに重要だと思います。そういった中で、平成２２年度の事務事業評価によりますと、図書館の維持運営について、Ｃということで、見直しとなっておりますが、効率的、効果的な図書館運営に向けて、委託方式等の見直しを進めるということなんですけれども、どういった点が非効率で、どういったふうに、どのように見直していかれる予定でしょうか。","respondent":"小川品川図書館長","answer":"図書館では、具体的には平成１６年度より窓口業務等の委託を開始しています。","id":"exchange-044"},{"speaker":"沢田委員","kind":"質問","question":"今後、高齢者の方の利用が増えていく中で、図書館としても、お年寄りに対しての、高齢者の方々に対する、これから使いやすさとか、そういう点での改善とか、現状の対策とか、そういったことはどういうことをやられているのか、あれば教えてください。","respondent":"小川品川図書館長","answer":"特に高齢者対策ですけれども、高齢者にかかわらず、どなたにでも親切にサービスをさせていただいているところです。特に拡大本など、比較的文字の大きい本なども多く用意してございまして、そういった部分でのサービスも充実させていただいているところです。","id":"exchange-045"},{"speaker":"沢田委員","kind":"質問","question":"図書館の利用で、自分もよく使っているんですけれども、タッチパネルで本の検索とかができる機械があると思うんですけれども、利用していると、本は調べることはできるんですけれども、どこに本があるかというのが画面上には表示されないで、レシートみたいなのを印刷すると、そこに出てくるようになっていたと思うんですけれども、図書館の本の記号というのは全国共通のようですけれども。","respondent":"小川品川図書館長","answer":"各館個別にすべての場所を画面上に表示するということになりますと、大変な開発になってしまいますので、それは基本的には難しいことかと思います。何かわからないことがありましたら、カウンターに必ずスタッフ等おりますので、気軽にお聞きいただければ、ご案内します。","id":"exchange-046"},{"speaker":"沢田委員","kind":"質問","question":"図書館の中にある読書するスペースなんですけれども、品川図書館の場合だと、毎朝開館前に結構並んでいる方がいらっしゃいまして、あいてすぐに、図書館で本を借りるというよりも、机に行って、自習とか勉強されている方がすごくいまして、それで場所も、特に夏休みとか冬休みとか春休みのころには、席もすぐいっぱいになっちゃいまして、本を読むためにあるはずのそういうスペースが。","respondent":"小川品川図書館長","answer":"委員ご指摘のとおり、図書館に毎朝並んで、同じ場所にお座りになって、確かに学習等をされていらっしゃる方も見受けられるのは事実ですが、図書館の本を利用しているのかどうかということによって排除をすることは難しいと考えておりますので、基本的には静かに調べ物等。","id":"exchange-047"},{"speaker":"沢田委員","kind":"質問","question":"図書館の中で、そういう方がいらっしゃるというのはわかるので、例えば別の自習室みたいなスペースを図書館の中に、そういう専門のスペースをつくって、そこで利用料とか、安い値段で使える利用料とかをとるという方法とかは考えられないのでしょうか。","respondent":"小川品川図書館長","answer":"各図書館には各規模に応じまして閲覧席等を既に設けているところです。特に品川図書館では大規模なために小中学生用の読書スペースも設けているところです。新たにそういったスペースを設けるということは物理的には難しいと考えております。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"１４０ページの特別区債、教育債の内容をお伺いしたいと思いますが、学校校地の取得とありますけれども、ここ、２校書いてあるんですが、そのうちの品川学園の校地取得についてお伺いしたいと思います。ここの取得するまず面積、広さと、あと現在の所有者と取得に至った経緯を教えてください。","respondent":"田村庶務課長","answer":"交渉経過ですが、やはり第一三共、民間企業ですので、細かい内容まではこの公の場でお話しできませんけれども、第一三共は会社として研究部門をどこに集約するかという話と、品川区に土地を売るだけではなく、買いたい土地もあるということで。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"五、六年交渉かかったということと、この品川学園の校地が狭いので、ぜひ広くしてほしいというような要望がこの間あったと聞いていますけれども、きょう今伺った、その隣の３,６６５.４２m2のところが、あちらから一緒に買ってくれないかと言われた、その辺は何か経緯があるのでしょうか。その話がいつぐらいからあったのかもお答えをいただきたいと思います。","respondent":"田村庶務課長","answer":"そうしましたら、それも可能ですよというようなお話がありましたので、私では判断できないので、持ち帰らさせていただいて、区の首脳部と検討して回答したいということで、今回に至ったです。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"種類が幾つもあるので、その辺、どんなものがあるのか、教えていただきたいのと、教育債の性格ですか、どういうもので、どういうところに使えるのかというのをお聞きしたいのと、あと、率直な疑問でお伺いしたいのは、学校施設整備費として使っていくんですけれども、基金の残高が、たくさん公共施設の整備基金とか、財調の基金とか、義務教育施設の整備基金とか、いろいろ基金があるにもかかわらず。","respondent":"田村庶務課長、金子企画財政課長","answer":"ですから、整備としますと、校庭ということですが、区長もいろんなところで施政方針等でも言っているように、学校が使う以外のときについては、少年少女のスポーツの拠点の場所としたいと考えていますので。なぜ基金を使わないのかというお話かと思いますが、学校用地の取得を起債で取得しますと、９割を起債できるわけなんですけれども、この起債の部分については、今年度財調で措置されるということがありますから、端的に申し上げますと。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私、きょうここでお話ししとかなくちゃなと思っているのが、とにかく大変広い貴重な土地だということにおいて、今後やはり区が区民の皆さんの要求を実現していくために当たって、土地の取得というのはすごく大事であるので、こういう機会にはぜひほんとうに取得をしていただきたいなと思うんですけれども、私、この間の区民の願いの優先順位を考えたときに。","respondent":"金子企画財政課長","answer":"公園関係では、制約がいろいろありますけれども、都市計画交付金の対象になった場合にも措置されるというケースがありますが、それ以外に関しましては、起債について特段の後年度の措置というものはございません。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろあるときに、どこを最優先にするのかというあたりで、今回この校庭の拡充ということに決められたのがどういう経過で決まったのかなというところを聞かせていただきたいのと、こういった区民要望の優先順位はどういう仕組みの中で決められていくのかなというところをお答えください。","respondent":"田村庶務課長、久保田行財政改革担当課長","answer":"品川学園の校地については、もともと敷地が続いているということで、工事に当たって、やはり何らかの形で交渉できないのかなというのを区も思っていましたし、地元の町会からも、ぜひ、地続きなので、利用できないかという交渉で。杜松小学校の跡も活用いたしまして、小規模の特別養護老人ホームを建設していく予定ですので、全体の計画の中でそういった形で区民の要望とともに長期基本計画の実現を着実に進めているところです。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとその辺をお伺いしたいのと、特養のほんとうに切望されているというのは、きょうの新聞にも出ていたんですけれども、特養の待機者が１０年間で４倍に膨らんでいるんですよね。特養の待機者は４倍に膨らんでいます。だから、私はここはちょっと断念していただいて、特養を建てていただきたいんですが、特養増設に当たってのそこの部署の関係の部長はいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"学校の跡地等の活用につきましては、全庁的に跡地活用検討委員会を設けまして、有効に活用するような形で検討を推進しています。","id":"exchange-054"},{"speaker":"石田委員","kind":"確認","question":"私からは、７２ページ、公園占用料、ロケーション・写真撮影等についてお伺いします。それと、補助金の国庫と都と両方の高齢者世帯の安否確認事業について、それと６５ページから６７ページの各こども野球場、公園等についてお伺いします。それと、補助金、国庫と都と見ている中で、同じ事業名で高齢者世帯の安否確認事業というのが全部で４つあります。その２つ、よろしくお願いします。","respondent":"井浦土木管理課長、冨岡高齢者福祉課長","answer":"件数的には、それぞれ年間約２００件程度ということで見込んです。その１つ下の高齢者世帯の安否確認事業、社会資本整備総合交付金ですけれども、これは平成２３年度ということでありまして。ロケーション等の予算の見積もりですが、ロケーションにつきましては２６１万円、写真撮影については２９万５,０００円ほどを見込んです。","id":"exchange-055"},{"speaker":"石田委員","kind":"質問・要望","question":"このロケーションについても、多分大小さまざまな料金体系があるのかなと思うので、わかりました。今月の頭に東京都がドラマや映画などのロケ地になった場所を紹介する東京ロケ地マップというものを作成したということで、品川も観光に非常に力を入れている中で、こうした東京都の動きともぜひとも連携をしていただきたいのですが、その辺のご見解をお願いします。それと、公園の件に移ります。","respondent":"井浦土木管理課長、堀越文化スポーツ振興課長、藤橋都市整備下水道課長","answer":"東京都のロケ地マップというような動向もありますので、東京都とも連携しながら、このようなものの情報発信ということについても、占用関係を通じてですが。土日ですと、少年野球として、ほぼ１００％に近いような利用率ですので、あいている時間帯、平日ですと。現在の施設の整備状況ですけれども、しながわ区民公園におきまして、既存の施設の有効利用という観点から。","id":"exchange-056"},{"speaker":"石田委員","kind":"質問・要望","question":"それぞれありがとうございました。その中で、ロケ地の観光スポットの１つとして品川を選んでいただければなと思うので、ぜひとも品川区でも独自でやれる部分はやっていただいて、また都と連携できる部分は連携していただきたいなと思います。これは要望で終わります。これも要望で終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"山元委員","kind":"質問・要望","question":"最初にいただいた、先ほどもちょっとお話がありましたが、周知方法といいますか、このようにお知らせをつくっていただいて、また気を使っていただいて、最初のほうにはなかったのが、ちゃんとバスの時間等も書いていただいて、入っていて、すごい気を使っていただいておりますけれども、先ほどお話を聞くと、文化センター等のところにもそういうお知らせ等が置いてあるとおっしゃっていましたけれども。","respondent":"堀越文化スポーツ振興課長","answer":"八潮での説明につきましては、自治会の役員会等にご説明させていただいたほか、地域センターでのパンフレット、それから八潮だよりを使いまして、オープニングのイベントの紹介をさせていただきました。","id":"exchange-058"},{"speaker":"山元委員","kind":"質問・要望","question":"それで、今はちょうどこの入り口のところにこみゅにてぃぷらざ八潮という手づくりの看板が立ちましたが、こんなこと言っては大変申しわけないんですけれども、どうせできるなら大きな看板をつくっていただきたいなと要望させていただきたいのと同時に、今言ったように、できれば案内図とか、こみゅにてぃぷらざ八潮を利用するにも案内図なんかを設置する予定があるのかどうかも教えていただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"看板の件ですけれども、八潮南中学校跡に特別養護老人ホームが５月にオープンをする予定です。その時期に合わせて、２つの施設について表示できるような、入り口のところ、スロープを上がるところに看板を設置するよう、今準備を進めているところです。","id":"exchange-059"},{"speaker":"山元委員","kind":"質問・要望","question":"この中にコインロッカーと書いてあります。このコインロッカーというのは、どなたたちが使うコインロッカーなのかを教えていただきたいというのと、これは無料かどうかというのもちょっとお聞きしたいということです。ここを利用するのに、入り口は何カ所あるのか、その辺も教えていただきたいというのと、それからもう１点、こみゅにてぃぷらざ八潮の一覧の中に料金表が書いてあります。","respondent":"堀越文化スポーツ振興課長","answer":"コインロッカーにつきましては、有料で設置をしているものでございまして、１日当たりのご使用で１００円いただいております。有料の形で、荷物等を置いていただくために設置をしているものです。","id":"exchange-060"},{"speaker":"山元委員","kind":"質問","question":"入り口は２カ所とお聞きしました。これは当てはまるかどうかわかりませんが、小学校の校庭側の電気は大変薄暗くて、利用している人たちが歩くのにちょっと怖いというお話がありましたので、この辺、明るい電気にしていただければと思いますので、よろしくお願いしたいと思います。一応それだけです。","respondent":"堀越文化スポーツ振興課長","answer":"アスレチック広場につきましては、できるだけ多くの方にご利用いただきたいということで、説明書を設置しています。ごくごく簡単な器具ではありますけれども、ご説明ということであれば、どういった対応がとれるか、これについては検討させていただきたいと思います。","id":"exchange-061"},{"speaker":"山元委員","kind":"質問・要望","question":"よろしくお願いします。電気に関しましては、門を出た通路のところです。道路と校庭の間といいますか、その電気ですので、ぜひ見ていただきたいと思います。では、すみません。時間がないので次に行かせていただきます。６７ページの鮫洲運動公園こども野球場です。こちらの新しくできる運動場だと思いますが、内容といいますか、教えていただきたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"整備の内容につきましては、これまで土のグラウンドでございましたけれども、全面的に人工芝に改修いたしまして、これまでどおり野球が行われるような形にするとともに、今後ミニサッカー等ができるような形での利用を考えてあります。","id":"exchange-062"},{"speaker":"山元委員","kind":"質問・要望","question":"それは今度、今までは自由に勝手に一番早かった人たちが使えるみたいな、そんな利用方法でありましたけれども、これから人工芝になったということは、勝手に使うわけでなく、ちゃんと抽選とか何か、そういうものがあるのでしょうか。もし、あと利用する場合、料金とかはとられるのであれば、料金も教えていただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"今度の改修に伴いまして、４月より、利用料につきましては、その他の少年野球場と同じように、２時間当たり小学生が５００円、中学生以上が１,５００円という形になります。","id":"exchange-063"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、管理人の人というか、利用するに当たって、管理する方がいらっしゃるかどうかをお聞きしたいんですけれども。今見てみましたら、野球場のところに駐輪場は見えました。駐車場は何かお考えになっているんでしょうか。","respondent":"齋藤道路公園課長","answer":"有人の管理になります。委託業者の人間が必ず１人張りついておりまして、施設の維持管理、受付業務を行います。駐輪場は７５台ほど用意しておりますけれども、駐車場は用意しておりません。","id":"exchange-064"},{"speaker":"山元委員","kind":"意見","question":"実は近隣の方から車をとめちゃいけないのに、まあ、ちょっとだけなのかもしれませんが、ある会社の隣にずっととめてあったなんていう苦情がありました。その辺、利用する方に関しては、ご説明をぜひお願いしたいと思います。もう１点、もちろんここにはＡＥＤもついているんですよね。","respondent":"齋藤道路公園課長","answer":"ＡＥＤ１台を設置いたします。","id":"exchange-065"},{"speaker":"伊藤委員","kind":"確認","question":"私は、歳入全般に関連して１つ、それから、８２ページから９８ページの国庫支出金に関連をして、それから、８５ページ、子ども手当について質問します。これに伴って、いわゆる回収不能額が４倍に増えているということがありましたので、やっぱりこのことに対してはしっかり議会としても指摘をして、対処を確認したいと思いますが、回収不能額の対応についてお聞かせください。お願いいたします。","respondent":"金子企画財政課長","answer":"細かいところは所管からご説明すると思いますが、そういう意味では、私どもの会計全般としては、確かに支障なく健全な財政であるというところはありますけれども、幾つかの問題点については、今後とも私どもとしては努力をしていきたいと考えているところです。","id":"exchange-066"},{"speaker":"伊藤委員","kind":"確認","question":"そこで、確認したいのが、この２１５億円のうち万が一この歳入関連法案が不成立になった場合、品川区にどういった影響を及ぼすのかということ。そういう現実的なことがこれから起こってくる可能性が高いわけですから、やっぱりそのことについても、品川区としてはどういった体制をしていくのかということをお聞かせください。お願いいたします。","respondent":"金子企画財政課長","answer":"今ご指摘の部分につきましては、私どもも鋭意情報を収集しながら進めていくところですが、ただ、予算編成というのは、予算案をつくって、第１回定例会にかけなければいけないところで、私どもとしましては、編成の段階での最新情報で組んでいったところでありますけれども。","id":"exchange-067"},{"speaker":"伊藤委員","kind":"質問","question":"品川区にどう影響があるかというのが一番大切なことなんですから。だけれども、今の答弁はわかるんだけれども、それでいいんですか。それが今、私たちとしてそんなことになってほしくないと思っているんだけれども、万万が一そうなってしまった場合どうするんですかということを聞いているので、あわせて、どういう影響があるかということも聞きますので、ご答弁をお願いいたします。","respondent":"金子企画財政課長","answer":"私どもの財政運営の中では、当然のことながら、４月１日以降もきちっと事業を進めていかなければ、区民の方に非常に迷惑になり、支障になるということがありますので、私どもとしましては、今の段階では、鋭意情報を収集しながら。","id":"exchange-068"},{"speaker":"伊藤委員","kind":"質問","question":"品川区のレベルですけれども。今の答弁はわかるんだけれども、だけれども、現場を抱えながらでも、品川区の財政に責任を持つ立場であるとするならば、情報収集だけではなくて、もっとさまざまな形で、具体的にシミュレーションしていくとか、新たな一歩を踏み出していくべきだと思うんですが、いかがでしょうか、お聞かせください。","respondent":"日下部企画部長","answer":"ですから、その点をしっかり見きわめながら、いずれにしましても、区民生活に支障のないような形での財政運営ということで、きめ細かな情報の把握、それからいざ、いざといいますか、最悪の事態は私ども考えたくはありませんけれども、しっかりした財政運営をできるように。","id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問","question":"次に子ども手当であります。これは午前中質疑がありました。だから、先ほどの議会の中での答弁では、区民に迷惑はかけないことをつくっていくと言ったんだけれども、でも、これだけのことをこれからの短期間の間で判断をして、区として責任を持って対処していくためには、今からさまざまなシミュレーションを組んだ上で、どう転んでもいいようなことをつくっていくべきではないでしょうか。お願いいたします。","respondent":"安井子育て支援課長","answer":"子ども手当の件ですけれども、現在のところ、国会でさまざまな議論がされているということは、私どもも把握しております。したがいまして、そこら辺でさまざまな検討は内部では進めているところです。いずれにしましても、最善の対応をとれるようにということで、検討しています。","id":"exchange-070"},{"speaker":"伊藤委員","kind":"意見","question":"今の課長の答弁は、現時点、わかりますよ。だから、最善の努力の、もう少し具体的なところを詰めていって、例えばいついっか、何月何日と仮定して、この日に国の予算が不成立だった場合にはこうしていくとか、より具体的な対処をしていきませんと、６月１日支給、どちらの制度になるにせよ、品川区民に対する責任ある行政はとれないと思うんですが、改めてのご答弁をお願いいたします。","respondent":"古川子ども未来事業部長","answer":"それぞれの方々に新しい子ども手当になるのか、あるいはそうではない従前の児童手当法に基づく制度に戻るのか、どのような形にいたしましても、その時点時点をとらえながら、最善の判断をしてまいりたい、このように考えております。","id":"exchange-071"},{"speaker":"伊藤委員","kind":"意見","question":"ぜひ私たち議会の者としては、この制度がどうあったとしても、区民に影響が必要最小限になりますように対処していただきますことをお願いしておきます。それから、子ども手当の現状を踏まえた上で、品川区の最高責任者としての感想と、それに対する品川区の方向性、それから、こういう状況の中であったとしても品川区を導いていくんだという、品川区を守っていくんだということの答弁をお願いいたします。","respondent":"濱野区長","answer":"そういう意味で、いろいろ事態は変化しておりますけれども、その変化にいかようにも対応できるような、そういう方策をしっかりと持って対応していきたいと考えています。物事が先を見通せないというのは、仕事もそうでありますし、それぞれの生活も同じであります。","id":"exchange-072"},{"speaker":"高橋委員","kind":"質問","question":"ということと、もう一つは、各、例えば減債基金は８億円取り崩す。例えば財政調整基金は１３億円取り崩すという、この表の中で、そこの数字を見れば、どれだけ取り崩すかということがわかると認識してよろしいんでしょうか。","respondent":"金子企画財政課長","answer":"委員ご指摘のとおり、１２６ページの基金繰入金合計１０２億６,０００万円余でありますが、これを大きくまとめて１０３億円と表示しているものでありますので、委員ご指摘のとおりであります。","id":"exchange-073"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、これは平成２１年度の基金運用状況審査意見書の中に、基金のところで、増減と平成２１年度書いてあるんですけれども、増減というのは、減というのは使ったもの、増というのは戻したものという考え方でよろしいんでしょうか。なぜそういうふうにそれをお聞きするかというと、最終的に、これは当初予算ですよね。でも、本来は例えば１０億円であったとします。基金に入れて使ったのは。","respondent":"金子企画財政課長","answer":"例えば昨日ご説明申し上げましたとおり、財政調整基金については、平成２２年度、１９億円で計上しておりましたが、ほかの財源については、財源不足を解消いたしましたので、結果的に年度末において、最終補正において、それを取り崩さなくても済むというような形で。","id":"exchange-074"},{"speaker":"高橋委員","kind":"質問","question":"積み上げていって使う金額はわかるんですが、増というのは、運用益だけではないと思うんですが、平成２１年度中の増減というのは積み立てたということなんですかね。","respondent":"金子企画財政課長","answer":"財源に余裕分ができて、年度末に改めて積むもの。大きく分けるとそういう２種類のものがありますので、そういうものを含めて、最初に申しました、この積み立ての増というところに載っているです。","id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、品川区財政調整基金条例というのがあって、第５条に区長は財政上必要があると認めるときは、確実な繰り戻しの方法および期間を定めて、基金に属する現金を歳計現金に繰り替えて運用することができる。これに基づいてここの繰り入れをされているんですか。","respondent":"福田会計管理者","answer":"繰り替え運用というのは、区がいろいろ歳計現金をキャッシュフローとして活用しておりますけれども、それがかなり細くなって、通常の運用ではできないときに、基金から一時繰り替えまして、それをキャッシュフローとして活用し。","id":"exchange-076"},{"speaker":"高橋委員","kind":"質問","question":"平成２２年はまだ決算が出ていませんので、今平成２３年ですね。これは予算現額ですけれども。つまり、繰り入れをこれだけ予定しているんですが、どうしてそういった変化があるのかということと、平成２３年度もそういった形、これは先の話ですから、いろいろな事業の進捗状況にもよると思うんですが、平成２３年度の収入率の見通しは、今のお話を踏まえてどのような状況になるのでしょうか。","respondent":"金子企画財政課長","answer":"最終的に、基金に積み立てる財源余裕分というのは、最終補正でお示ししますように、年度の末にならなければわからないものです。現在当初予算をお示ししている段階ですので、それについてはまだ見通しを持っているわけではございません。","id":"exchange-077"},{"speaker":"高橋委員","kind":"質問","question":"時間がありませんので、もう一つは、１３種類の基金があるわけなんですけれども、４つで９０％以上、重要な形で構成されていますが、今後かなり社会情勢が変化してきた中で、基金の構成といいますか、もちろん多額の費用がかかる基金はそうですけれども、例えば奨学金の事業のほうを増やすとか、あるいは問題になっている施設の修繕、そういうのの基金をつくるだとか、あるいは介護関係だとか。","respondent":"金子企画財政課長","answer":"それは１つの政策判断でありますし、今考えているところは、最前から申しましたとおり、施設整備基金についてはこれから重要になってくる。こういった経済情勢が続く場合には、財政調整基金も今以上に必要かなと考えているところです。","id":"exchange-078"},{"speaker":"武内委員","kind":"質問・要望","question":"７３ページの自転車駐車場使用料、それから１４５ページの議員報酬等と、それからプレスの７９ページについてお伺いしたいと思います。それから、プレスの７９ページ、これはＡＥＤの自販機設置なんですけれども、プレスによりますと、約６００万円の入りを見込んでいるということなんですが、予算書の歳入のどこに入っているのか、教えてください。","respondent":"藤木交通安全担当課長、桑村区議会事務局長、金子企画財政課長","answer":"これは平成２２年度の平均ですけれども、一番高いところが、大森駅の水神口で１１３％です。反対に低いところが下神明の２６％です。議員報酬等のご説明を申し上げます。一番最後のお尋ねの自販機の運営費収入でありますが、これは１４０ページの、款で申しますと諸収入の雑入、２４節の雑入。","id":"exchange-079"},{"speaker":"武内委員","kind":"確認","question":"当時、いわゆる定期利用のほうも設置すべきじゃないかという声もあったようですけれども、経過を見ながら検討するという、たしかそういうやりとりが議会の中でもあったと思うんですが、例えば定期利用に少し一部するとか、下神明は今全部当日利用になっていると思うんですが、そういうふうな検討をしていくのかどうかということを教えてください。自転車と議員報酬について教えてください。","respondent":"藤木交通安全担当課長、桑村区議会事務局長","answer":"現時点ではまだ当日利用を定期利用に振りかえるとか、そういう具体的な検討はしておりませんが、過去にも利用率を向上させるために、料金を下げたり、いろいろと工夫して今まで区もやってまいりましたので、今後いろんな形で。今回はここの増減が約２億１,０００万円ぐらい出ているわけですけれども、これはほとんど共済費の増ですので、来年度予算等にその共済費の動きというのは、これからも大分変動してくると予想されますので。","id":"exchange-080"},{"speaker":"武内委員","kind":"質問・要望","question":"その辺、もし下げたようなケースがあるならば、ちょっと教えていただきたいのと、あと、２年前ですかね、私、建設委員会に所属していたときに、委員会の中の議論で、指定管理者の方が、例えば１０分とめても、ほとんど丸一日とめても同じ料金だということで、時間に応じた料金設定を例えば２０分まで無料だよとか、そういうことの話し合いが出たときに、指定管理しているところが何かそういう工夫をして。","respondent":"藤木交通安全担当課長","answer":"旗の台の駐輪場につきましても、２,０００円のところを１,６００円に下げたというような経緯があります。もう１点の短時間の料金制度につきましては、特に具体的な結論というものは今のところは出ておりません。","id":"exchange-081"},{"speaker":"武内委員","kind":"質問・要望","question":"時間がちょっとあるので、通告していなかったんですけれども、さっきの子ども手当の件で、品川区はもともと所得制限がないんですけれども、今回仮に法案が通らない場合に、児童手当に戻った場合に、ほかの自治体ではシステム改修等で時間と経費がかかると言われているんですけれども、品川はそういうことと比べると、比較的スムーズにできるのかなと思っているんですけれども、その辺はどうなんでしょうか。","respondent":"安井子育て支援課長","answer":"まだ未受給の方が児童手当についてもいらっしゃるということなので、システムとしては別に動かしております。そういう意味では、全くつくりかえる、新しいものをつくるということにはならないので、比較的コスト面では安くいけると考えております。","id":"exchange-082"},{"speaker":"大沢委員","kind":"質問・要望","question":"私、ここの議会へ入らせていただいてからずっと聞こうと思って、ようやく今回聞かせていただくようなことなんですが、都と国の負担金そして補助金があるわけですけれども、これが私、長年の疑問でありまして、初めて聞かせていただきますけれども、分母、２分の１、３分の１、６分の１、１０分の１と、それで今回に至っては３９分の１とか、３９分の２９とか、３９分の３３とかとあるんですけれども。","respondent":"金子企画財政課長","answer":"今回、子ども手当給付金等々では、３９分のというふうなものが出てきてまいりますが、これは全体、一定の部分は１０分の１０であるけれども、一定の部分は従前の児童手当の負担割合を生かすということで、それを両方掛け合わせたがために。","id":"exchange-083"},{"speaker":"大沢委員","kind":"質問","question":"子ども手当、児童手当の是非については、私、今回は問いませんけれども、この３９という、今おっしゃっていた率に基づいて分母が決められたということですけれども、これ、需要に対する率とか、さまざまなものがあるんですけれども、具体的にはどのようなものが基準になって率が構成をされているのか、おわかりになったら教えてください。","respondent":"金子企画財政課長","answer":"ちょっと一言で申し上げるのは難しいところもありますが、国においては、多くの事業で、例えば、要するに国負担、都道府県負担、市区町村負担という形を、例えば３分の１、３分の１、３分の１でやるとか、あるいは国が２分の１をもって都道府県と市区町村で２分の１ずつやるとか。","id":"exchange-084"},{"speaker":"大沢委員","kind":"質問・要望","question":"多少私自身の勉強不足というのも否めませんので、十分に資料をそろえてから、また課長のほうにお尋ねをさせていただきたいと思います。次に移らします。先ほど２つにまたがるということで、７９ページの広告手数料、それと雑収入で、１３４ページ、雑入ということで入っております広告料収入というのは、これはホームページの広告料収入ということで理解をしてよろしゅうありますでしょうか。","respondent":"金子企画財政課長","answer":"この広告料収入でありますが、広報しながわ、それからホームページ、それからリサイクルカレンダー、こういったところに有料広告という形で載せているものの収入です。","id":"exchange-085"},{"speaker":"大沢委員","kind":"質問・要望","question":"しかし、なぜ区のところの公共という部分で、１７件アクセスがあるということですけれども、このバナー広告、約二十何件載っておりますけれども、この公共の部分で、かたや、ホームページには公共のページの上に広告が載っておることは要綱で許されている。この公共というものに掲げる広告物に関して、このような整合性が整わないのはなぜか、教えていただきたいと思います。","respondent":"井浦土木管理課長","answer":"７９ページの屋外広告物につきましては、いわゆる物理的に５ｍ以上、あるいは１０m2以上ということで、屋外に設置する看板に対する景観、あるいは安全上の確保という法の目的で許可を行っているものです。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問","question":"屋外における安全の確保ということの今お話をいただきました。しかしながら、これは公共物に要は私物をかけてはいけないというような形で私は読み取るんですけれども、そういう読み取り方でいいんでしょうか、いけないんでしょうか、教えてください。","respondent":"岩田都市環境事業部長","answer":"７９ページの屋外広告物の手数料は、許可を行う場合にかかる人件費等の事務手数料をとるという、こういう性格のものです。それから、委員ご指摘の屋外広告物法によりますと、道路、公園は広告物を出してはいけない、禁止区域となっております。","id":"exchange-087"},{"speaker":"大沢委員","kind":"質問","question":"広告という部分で言った場合に、某国営放送、これは放送法というものがあって、特定のものの宣伝は禁じられているということですが、これは先ほども要綱にありましたように、これは否ということで話をさせていただいているわけではなくて、どんどんこれは今これからいろんな部分で区を取り巻く経営環境が厳しくなる上で、アイデア一つで、これで言えば、手数料収入なり。","respondent":"岩田都市環境事業部長","answer":"直接のお答えにはなりませんが、いわゆる行政が事業を行う場合、当然税外収入はとれるものはできるだけとっていかなければいけませんけれども、法律上やってはいけないということを我々公務員はできないわけです。","id":"exchange-088"},{"speaker":"大沢委員","kind":"質問・要望","question":"最後高齢者クラブ等支援事業についてお尋ねをします。そこの一歩上を行く団塊の世代、これからまさに地域デビューをしていただかなければいけないという話が、そういうお話を聞いて数年がたとうとしておりますけれども、改めて今後どのように団塊の世代に対して区にかかわっていただくか、地域にかかわっていただくか、そのようなお考えをもう１回改めて伺いたいと思いますので、よろしくお願いいたします。","respondent":"間部高齢者いきがい課長","answer":"一方では、従来型のゲートボール等を好まれる方もいらっしゃいますし、また若い世代では、ゴルフなど、グラウンドゴルフですね、そういうようなものもありますので、やはりこれからは、そういった点で多様な魅力あるクラブづくりを進めることが大切だと思ってあります。","id":"exchange-089"},{"speaker":"阿部委員","kind":"質問","question":"りんかい線、これは収入のところで伺う話かどうかちょっとわからないんですけれども、歳出でなかったものですから。これは一義的には東京臨海高速鉄道が変化があるたびにリカレントするべきものだと思うんですけれども、区としても、やっぱりこれは利用者にとっては駅のサインも区のサインですし、こういったことは時々見直したりすべきではないかと思うんですが、その辺どうなっているでしょうか。","respondent":"井浦土木管理課長、安井子育て支援課長、梶戸籍住民課長、松代都市計画課長","answer":"１,６７８万１,０００円の中には、五反田ふれあい水辺広場内地域貢献施設の行政財産使用許可料が含まれてあります。年額５１２万５,８００円です。そういうご説明になります。さまざまな資料の内容については、またこれからも調査、検討するところです。大井町駅周辺では、周辺の案内看板等も含めて、今見直しをしていますので、その辺もあわせて改善に取り組みたいと考えています。","id":"exchange-090"},{"speaker":"阿部委員","kind":"質問・要望","question":"五反田ふれあい水辺広場のほうなんですけれども、使用者がタウンマネジメントということで、つまり、区とタウンマネジメントと業者との関係がどうなっているのでしょうか。悪いとは言っていません。そういったもの、ちょっと仕組みをもう少し詳しく教えていただければと思います。ですので、そういった観点からも、ぜひ積極的に検討していただきたいと思うんですけれども、再度ご答弁をお願いいたします。","respondent":"梶戸籍住民課長、井浦土木管理課長","answer":"それにつきましては、毎年、例えば窓口における指導をしたりとか、あるいは、そういった指導のポスターを張ったりとか、掲示をし直したりしていますので、そういった点で含みながら、今後も検討していきたいと考えているところです。五反田ふれあい水辺広場の行政財産使用許可に関するご質問ですが、使用許可の当事者としましては、一般社団法人大崎・五反田タウンマネジメントということで許可を出しておりますので、当事者はレストランを経営している会社ではなくて。","id":"exchange-091"},{"speaker":"阿部委員","kind":"質問","question":"ですから、言っているわけです。それから、広場のほうなんですけれども、すみません、幾つか質問した中で、あまりお答えの数は多くなかったかと思うんですが、区とタウンマネジメントとの間の契約関係ということはわかりました。それから、その際、業者の選定というのはタウンマネジメントが行って、区としては特にそれは何らもの申す権限も基準もないということなんでしょうか。","respondent":"井浦土木管理課長、岩田都市環境事業部長","answer":"ただいまの件につきましては、直接区との法律関係ということでは、大崎・五反田タウンマネジメントですので、行政財産使用料として区に直接大崎・五反田タウンマネジメントからおさめられるという関係になっております。ちょっとややこしいんですけれども、もともと都市公園における考え方というのは、これが公園であれば、都市公園法に基づく管理許可という制度を使います。","id":"exchange-092"},{"speaker":"阿部委員","kind":"質問","question":"最初の話、ちょっと繰り返しになりますけれども、公園の種類によっても限定されてくるかもしれませんけれども、公園の中にこういった施設があるというのは、私は悪いことではないなと考えています。こういった形で、区立公園の中に何か民間で、商業施設と言ったらいいんでしょうかね、飲食の施設などを展開していく、今後も方向性としてあるのかどうかも教えてください。","respondent":"井浦土木管理課長","answer":"公園施設に該当するというものについては、区としても研究しまして、利用しやすい公園ということで進めてまいりたいと考えています。","id":"exchange-093"},{"speaker":"安藤委員","kind":"確認","question":"去年の予算書と比べましたところ、納税義務者数というのは、２２万５,２００人から、ことしの予算書の２２万７,６００人ということで、増えているわけですけれども、細かく見てみますと、普通徴収のほうの納税義務者数は１万１,１００人減り、逆に特別徴収の義務者数のほうが１万３,５００人増えているということなんですけれども、その主な理由なんですけれども。","respondent":"武内税務課長","answer":"平成２２年度から年金の特別徴収が全面的に開始しましたので、わかりやすいように特別徴収に組み入れました。","id":"exchange-094"},{"speaker":"安藤委員","kind":"質問・要望","question":"これ、１％とはいえ、３億円余ですから、なかなか大きな額だと思います。もう少し詳しく教えていただきたいと思います。税務課のほうでは、区民税の納税者を２００万円以下の方、７００万円以下の方、７００万円以上の方で分類し、統計をとっていると伺っておりますけれども、この分類などに照らして、どういう方が増えて、増収になっていると分析しているのか、ご説明をお願いします。","respondent":"武内税務課長","answer":"去年に比べて、金額にして約１億円ほど弱ということで、減ということで計上しておりまして、普通徴収については、雇用情勢だとか、景気が回復しているという状況の中で、１.６％の増ということですので、１８万８,０００円という１人当たりの税額ということで。","id":"exchange-095"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとすみません。去年に比べるとかなり減っているんですよね。なんですけれども、逆に均等割のみの方が予算書によると昨年は６,０００人なんですね。これが８００人の絶対数を増やして見込んでいるわけですけれども、これは普通徴収の納税義務者数が減っているのに、均等割のみの方は増えると。これはなぜなのか。どういう区民生活実態が反映していると区はお考えなのか、あわせてお伺いします。","respondent":"武内税務課長","answer":"所得割がかからないという方については、所得が年間で３５万円以下の方について、また給与所得の方については１００万円以下の方については均等割が発生しません。","id":"exchange-096"},{"speaker":"安藤委員","kind":"質問","question":"普通徴収で均等割のみの方という方なんですけれども、３５万円、給与所得で１００万円以下の方だということで、かなり生活的には実態的に厳しい方なんじゃないかなと思うんですけれども、区としてはどういう普通徴収で均等割のみの方。どういう区民生活実態の方、自営業の方とかなのか、そこら辺をどういうふうにとらえているのかというのをお伺いします。そこら辺の分析ももう一度お願いします。","respondent":"武内税務課長","answer":"１人当たりのどのように見ているかということですけれども、この予算上では、普通徴収と特別徴収という形で計上していますので、個人の税額の部分でいきますと、普通徴収については、１２万３,０００円という１人当たりのトータルで考えているものを、ことしについては。","id":"exchange-097"},{"speaker":"安藤委員","kind":"質問","question":"この４年間、もう少し長いスパンで見てみますと、予算書で比べてみますと、区民税の納税義務者数、増えております。区はどうしてこういうふうに区民税を増収に転じ、この数年間続けてきているのか、分析しているのか、お伺いしたいと思います。","respondent":"武内税務課長","answer":"やはり品川区民になりたいという、そういう希望の方がたくさんいらっしゃるのではないか。私も、区民の声をよく見ているんですけれども、区民にアンケートをとると、８９％の方が引き続き住み続けたいという回答が出てくる、そういう波状効果というんでしょうか。","id":"exchange-098"},{"speaker":"安藤委員","kind":"提案","question":"共産党の今回ことしも区民アンケートとりましたけれども、７５０人の方から回答いただきました。３６条の住民税減免の周知、適用拡大についてお伺いしたいんですが、これは品川区でホームページでも周知してないわけですね。他自治体ではきちんと条件も示して、こうした制度を周知しているわけですが、このことに関して、もう少し周知の拡大、充実を求めるんですけれども、あわせてお伺いします。","respondent":"武内税務課長","answer":"減免制度につきましては、何も品川区だけの固有のものではなくて、地方自治法に決められた減免制度というのを品川区も取り入れておりますので、あえて品川区だけ特筆した減免制度を周知するということではなくて、これは国の政策の中でそういう税の負担が厳しい方については。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問","question":"私は５８ページの１２款使用料及び手数料、１３４ページ、１９款諸収入の雑入、１４０ページ、２０款特別区債、歳出１４４ページの議会費から質問します。２は、前項の場合において、地方債の起債の目的、限度額、起債の方法、利率及び償還の方法は予算でこれを定めなければならないとあります。そこで、自治体に限度額を定めなければならないとした意図についてお伺いをいたします。","respondent":"金子企画財政課長","answer":"減債基金の残高が、平成２２年度末で申し上げますと、１３６億円ほどあります。さらに財調で今後措置される予定のものが１３０億円ほどあります。そういう意味では、２６６億円ありますので、約３億円余、一般財源で負担をしなければならない。","id":"exchange-100"},{"speaker":"井上委員","kind":"質問・要望","question":"それともう１点、この品川学園の校地取得について、先ほど説明がありまして、ほかの地域から見れば、大変うらやましい話と思うんですけれども、品川区でもいろいろなところでこういう要望の声があるんですが、そういった場合には、同じような購入という判断をしていこうとされているのか、その点についてもお考えをお聞きします。","respondent":"金子企画財政課長、田村庶務課長","answer":"そういう意味では、財源をいかに措置していくのかというのは、毎年度毎年度検討しているところでありますけれども、非常に高額であることから、これについては、後年度負担を含めて起債をして、財源措置しようというふうな考え方です。そういう相手方があることなので、無理無理強制収容というわけにいかないのですが、交渉の手だてをとってご了解いただくという形になりますけれども、どこの地域についても、交渉していきたいと思いますし、しております。","id":"exchange-101"},{"speaker":"井上委員","kind":"質問","question":"議会費についてお伺いをいたします。議会費の中で、全国市議会議長会の分担金というのはどのような用途に使われていくお金なのかということをお伺いします。","respondent":"桑村区議会事務局長","answer":"全国市議会議長会ですけれども、よく報道等、あるいは会報等でご存じのことと思いますが、いわゆる会議費ですとか、それから調査研究ですとか、それからまたいろんな要望活動等もやられていますので、そういったものの経費ですとか、またそれを支える事務局の人件費ですとか。","id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"全国市議会議長会表彰規程というのがあって、永年在職表彰があるんですが、これの経費というのはここから支出をされていると考えてよろしいでしょうか。","respondent":"桑村区議会事務局長","answer":"そのとおりです。","id":"exchange-103"},{"speaker":"井上委員","kind":"提案","question":"今議会改革が盛んに話題になっておりまして、その中心が残念ながら議員定数の削減ということになっています。そこで、生活者ネットワークはたびたび議員特権の廃止を提案してきたものですけれども、そこで今回の全国市議会議長会の表彰も廃止をしていくべきだと思いますので、お伺いをいたします。","respondent":"桑村区議会事務局長","answer":"いつからというお話ですけれども、全国市議会議長会に品川区議会が入ったのは、いわゆる都区制度改革の後ですので、平成１３年から入っているという形です。","id":"exchange-104"},{"speaker":"井上委員","kind":"質問","question":"表彰を辞退する議員が品川区議会でも出てきているんですけれども、個人の意思ではなく、議会の意思として廃止をすべきと考えておりまして、この制度上、この議長会に所属したまま品川区議会として表彰を行わないと決定すれば、それは可能なことなのでしょうか。","respondent":"桑村区議会事務局長","answer":"正直言いまして、区議会事務局長の立場で答えられる問題ではないですけれども、もちろん品川区議会の中でいろいろなご議論の結果、全員の方がそういった表彰を受けないとお考えになられるということになれば、そういうことはあり得るということでございましょうけれども。","id":"exchange-105"},{"speaker":"井上委員","kind":"意見","question":"当然議会の中で検討していくことだと思いますけれども、貴重な税金がこういったところに投入されている以上、議会としても真摯に考えていかなければならないと思っています。次に、諸収入の雑入のところなんですけれども、公園へのＡＥＤ付自動販売機の設置目的と１０公園に設置予定ということがプレスで発表されておりますけれども、この１０カ所はどこなのか、お教えください。","respondent":"齋藤道路公園課長","answer":"こういう副次的な機能も持たせることができるです。どこに設置するかですが、１０個の公園に予定しております。しながわ区民公園、東品川海上公園、戸越公園、鮫洲運動公園、西大井広場公園、大井水神公園、大井公園、子供の森公園、池田山公園、大森貝塚遺跡庭園です。","id":"exchange-106"},{"speaker":"井上委員","kind":"質問・要望","question":"災害の場合ということが目的の１つに挙げられていたんですけれども、その前に、税外収入というか、そういった有効活用で税収を求めるということには反対するものではありませんけれども、この施策については、安全対策であれば、ＡＥＤの設置ということで、まず自販機の設置は必要ないというところの立場で今質問していますが、マイカップや使い捨て容器などの。","respondent":"齋藤道路公園課長","answer":"発生した空き缶、空きペットボトルについてはきちんと事業者が自主回収するように、これはきちんと入札の条件として入れております。２つ目のご質問ですが、自動販売機を無料で４８時間提供できるということは画期的なことだと思いますので、ご理解のほど申し上げます。","id":"exchange-107"},{"speaker":"井上委員","kind":"質問","question":"それからもう一つは、ＡＥＤの維持管理の問題についてお伺いいたします。バッテリーやパットの交換が定期的に必要なんですけれども、そういったことが飲料会社に徹底できるのかということが疑問にありますけれども、そういったところはどのように検討された結果なのかということと、関連して、区内に設置されているＡＥＤの交換なんかは今どのような状況で行われているのかを伺います。","respondent":"齋藤道路公園課長","answer":"ＡＥＤにつきましては、雨風がしのげる場所を確保できないと、ＡＥＤ付きの自動販売機は設置できません。","id":"exchange-108"},{"speaker":"井上委員","kind":"質問・要望","question":"ごみの減量というところはやっぱり重要な問題だと思っているので、単純に便利イコール区民サービスということにはつながらないということで、慎重に検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"堺委員","kind":"質問・要望","question":"同じく箱根荘につきましても、箱根荘の運営費としては、当初予算のほうでは８,１０４万６,０００円計上されておりますけれども、同じく使用料については、２,１９９万３,０００円ですので、これについても、単純に計算しますと、約５,９０５万３,０００円が区の持ち出しということになるのかなと思いますが、いずれにいたしましても、それだけ区の持ち出しがあったとしても。","respondent":"中山地域活動課長","answer":"平成２１年度の実績です。それで、人数としては、平成２１年度、８,４９１人の方が延べでお泊まりいただいたです。箱根荘ですけれども、部屋の利用率としては５６.５％。宿泊者としては７,０７７人のご宿泊をいただいたです。","id":"exchange-110"},{"speaker":"堺委員","kind":"確認","question":"今お答えいただいた内容につきましては、今回の平成２２年度の事務事業評価結果一覧の中に、確かに品川荘については４８.８％、評価結果としてはＢと。箱根荘については、今お話しのように５６.５％。この結果を出したというか、出てきた、その背景といいましょうかね、理由といいましょうか、その辺については、我々はどのように考えればいいのか、ちょっと確認をします。","respondent":"中山地域活動課長","answer":"事務事業評価の説明にもあるんですけれども、まず箱根荘、施設の老朽化です。昭和４４年の築ということで、築４２年になろうかということですけれども、一部雨漏りだとか亀裂があり、応急補修を重ねているという状況です。","id":"exchange-111"},{"speaker":"堺委員","kind":"質問・要望","question":"約４２年経過をした建物、かなりの人が利用されてきた。ある人にとっては非常に懐かしい施設だったかなと。あるいはある既存の施設と提携をして区民が利用できるようにするのか、その辺のところも、廃止にしたら終わりだよということではなくて、やはり区民へのサービスというんでしょうか、それについてこういう施設についてもぜひ確保していただきたいと思うんですが、この辺についてはいかがでしょうか。","respondent":"中山地域活動課長","answer":"施設のありようとしてはそういう方向性です。当然保養所全体のあり方も踏まえてですけれども、こういう廃止に伴う対応も考えながら、今後さまざまな検討を加えていきたいということで、その段階ではいろんな声を聞きながら考えてまいりたいと考えています。","id":"exchange-112"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひそういう方向で、箱根という、いい場所ですので、ぜひ区民のためにいい施設を利用できるように確保していただきたいと思います。それから、教職員住宅、この件ですが、まずこの入居対象者と現在の利用状況についてどうなっているのか、ちょっと確認をしておきたいんですけれども。","respondent":"冠木指導課長","answer":"現状ゆたか教職員住宅については、所帯用、単身用合わせて２６戸、それから、伊藤教職員待機寮については１２戸ということで、今現在空き室がゆたか教職員住宅が２部屋、伊藤教職員待機寮も２部屋ありますので、募集をかけているという状況です。","id":"exchange-113"},{"speaker":"堺委員","kind":"質問","question":"わかりました。２つそれぞれあいているですが、ちょっとここ、参考までに、ゆたか、伊藤、それぞれ建築年月日を教えていただけますか。","respondent":"冠木指導課長","answer":"ゆたか教職員住宅については、昭和４８年の１１月の建築です。伊藤教職員待機寮については、昭和６３年の８月と聞いております。","id":"exchange-114"},{"speaker":"堺委員","kind":"質問","question":"伊藤については６３年の８月ですかね。そうすると、ゆたかのほうが４８年というと、かなり経過してきているんですが、外から見るとかなり古いなという気がするんですが、これの建てかえについてはいかがでしょうか。考えておられますか。","respondent":"冠木指導課長","answer":"築３０年を超えているということで、近い将来施設更新も迎えることですけれども、コストパフォーマンス等も考慮いたしまして、民間施設等も含めて考えてまいりたいです。","id":"exchange-115"},{"speaker":"鈴木委員","kind":"確認","question":"１４０ページ、特別区債、歳出の公債費に絡んでです。公園においても、そういう福祉関係の団体が自動販売機を設置していると思うんですけれども、その考え方は変わらないですねということの確認です。今度公園で財産管理の税外収入を上げようという考え方と、これをすべての庁舎に結びつけて、税外収入を上げていこうという考えではないかと、そこの確認を１点したいと思います。","respondent":"久保田行財政改革担当課長","answer":"そうしたものも基本としながら、財産の有効活用を図っていきたいということで、今回公園の部分については貸し付けという形で有効活用を図るものですが、今までのそういう経過もありますので、そういったものを基本と置きつつ。","id":"exchange-116"},{"speaker":"鈴木委員","kind":"質問・要望","question":"わかりました。新たなものについて、新規でとっていくというのはわかるんですけれども、今のものをなくしていくということで、ちょっとその辺は控えていただきたいなという思いで質問させていただきました。財調ですから、そのお金がどこへ使われるかというのは、自由な部分もありますけれども、この算定として、この部分が何でなくなったのか、その見直しをされた理由を教えてください。","respondent":"金子企画財政課長","answer":"旧老人福祉保健法に基づいているところがありましたので、その根拠法令がなくなっているという、その２点から今回これについては見直したということで、そういう意味では、整理するということで、全く廃止するという意味合いではないということでご理解いただければと思います。","id":"exchange-117"},{"speaker":"鈴木委員","kind":"確認","question":"それと同時に、５５０円でしたっけ、保険料をいただいて、これは保険に入ってそのまま、右から左に出る分だから、区の中には出てこないと思うんですけれども、都の補助金が６,５００万円ですか、そういうのが出てくる中で、５００万円という数字をどういうふうにとらえたらいいのかなというのが、私、ちょっとはっきりわからなかったので、全体の、歳出になってしまうので。","respondent":"田村庶務課長","answer":"すまいるスクールは全児童対策ということで、平成１３年度からモデル的に１校、３校、１５校と拡大しておりますが、その中で、全児童対策、スタート切ってからちょうど１０年、全校展開してからちょうど半分で５年という時期でございまして、歳入歳出差っ引きでやっていきますと。","id":"exchange-118"},{"speaker":"鈴木委員","kind":"質問","question":"一気に上げろとも言いにくいところなんですけれども、増えるというのは、保護者の負担というところもあるんですけれども、ただ、数字出た中で、運営費１１億円ぐらいという数字がたしかあったと思います。その中どう判断するのかなと、私は非常に考え込んでしまったんですけれども。逆に今すまいるの指導員の方もなかなか集めるのも大変だというお話もお聞きしています。そこら辺はどうお考えでしょうか。","respondent":"田村庶務課長","answer":"今、区の中では、すまいるの常勤職員は１校１名、区の職員がいるということで、全校３８校はすべて職員を除いて委託しておりますので、手をこまねいているのではなく、努力はしてきたけど、ただし。","id":"exchange-119"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その辺、よく検討していただきながら、また議会のほうともいろいろ先に相談していただきながら進めていっていただきたいと思いますので、よろしくお願いしたいと思います。プライマリーバランスですか、この資料でいくと、基礎的財政収支が、赤字と言っていい形ですね。マイナスになっている部分ですから。ただ、どうしてもこれからまた出てくる中で、抑制をしながらも、今、区の基金は残していく。","respondent":"金子企画財政課長","answer":"今後につきましても、起債につきましては、何回かご答弁申し上げているとおり、後年度に措置されるということで、区負担が極力少ないものについては起債することがあり得ますけれども、基本的には起債することは抑制していこうという考え方です。","id":"exchange-120"},{"speaker":"鈴木委員","kind":"質問","question":"改めてありがとうあります。そうすると、前年比にこの比率が上がってくる。そこが一般的に見たとき数字が悪くなったというふうにしか見られない。ただ、財源は確保されているんだということをどこかに示すことができないのかなと思うんですけれども、その辺は方法はないんでしょうか。","respondent":"金子企画財政課長","answer":"ご質問は財政健全化判断比率の中の実質公債費比率等々の比率のことだと思いますけれども、これはルール上一定の式がありまして、そういう意味では、出てきた数字を変えようがないので、これはそのままいくしかないんですけれども、例えば実質公債費比率等々につきましては。","id":"exchange-121"},{"speaker":"鈴木委員","kind":"質問","question":"そこが例えば区民の方に、例えば広報で出すときに、こういう比率が上がっているけど、実質的には財源としてはもう確保されているから、これは問題ないんですよというような、そういう説明がつけられないでしょうかという意味なんですがいかがですか。","respondent":"金子企画財政課長","answer":"失礼いたしました。委員ご指摘のとおり、私ども、財政状況の公表のときに、この数字も出しておりますけれども、ただ、漫然とその数字を公表するだけではなく、今委員の皆様にも説明しているように、わかりやすい形でコメント等をしていきたいと考えております。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"私から、まず国・都支出金全般に関してお聞きいたします。当然だとは思います。それで、ですから、品川区としてどういう考え方で説明していくのかということをやっぱりきっちりと話をしていただきたいなと考えています。それから、１０２ページの水道管直結化事業、これは確認です。１０時園というところがありますけれども、そこの動きがどうなっていくのかということをお聞きします。","respondent":"金子企画財政課長、田村庶務課長、安井子育て支援課長、吉岡保育課長","answer":"都区のあり方検討会の関係ですが、今、事務事業の内容についての検討を行って、一通りの検討が終了した段階ですけれども、事務の移管が決まれば。残り改築校を除きますと、１４校ですので、東京都の水道局の話では、平成２８年度までこの事業、１０分の８の事業ですが。子ども手当の関係ですけれども、現在国で検討されているというところを基本として実施されるということが望ましいと考えているんですけれども。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"地方分権をこれから推進していかれると思うんですけれども、やっぱりもらうべきものはきちっともらってくる。そして事業展開していくというような形で、区長はじめ、頑張っていただきたいと思います。東京水と言われるぐらいですから、非常においしい水だと思いますので、子どもたちも大変環境的にはいいかなと思いますので、推進をよろしくお願いします。それと子ども手当。","respondent":"安井子育て支援課長","answer":"子ども手当については、最前、ご説明していますように、基本的には国の法案で定められて、あくまでも法定受託事務という中で行われているものですので、そちらで決められた形でやっていくということで考えているところです。","id":"exchange-124"},{"speaker":"川西委員","kind":"質問","question":"すみません。それで、この平米当たりの使用料単価については、それまでありました天王洲、西大井、それらのところと平米当たりの単価が変わらないのかどうか、１つ伺います。あるいは同じ７１ページにあります、工場協会連合会、東京商工会議所、観光協会とありますが、これらの平米単価については、どういうふうな意図でやっていらっしゃるのか、伺います。１回終わります。","respondent":"福島ものづくり・経営支援課長、諸岡商業・観光課長","answer":"店舗につきましては、割引をしておりまして、平米単価４,０００円を０.７でやってあります。それに対しまして、賃貸オフィスにつきましては、平米単価４,０００円ということで、ほかの創業支援施設とそろえているものです。これは上のほうは観光協会で行いますけれども、大井町におきまして、今までのような４階という、なかなか目立たない場所とは異なりまして、大通りに面した多くの人の目に触れる場所。","id":"exchange-125"},{"speaker":"川西委員","kind":"意見","question":"そうしますと、これまであった天王洲、西大井の平米単価と変わらないかどうかというところはご答弁ありましたかね。","respondent":"福島ものづくり・経営支援課長","answer":"西大井ですけれども、こちらは２つありまして、ブースと店舗という形になっています。ブースの部分は事務所という形になっています。ブースの場合は、簡易パーテーションで仕切られているものですので、安くなってあります。それ以外については一緒です。","id":"exchange-126"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、使用料で１つ伺いますが、公園の使用料というのが出ておりまして、ちょっと関連で申しわけありませんが、子どもの野球場については、やはり土曜、日曜、祝日という、あるいは夏休み、春休み、そういうときしか使わない。しながわ区民公園なんかもそうですけれども、ふだん使わないときに、ゲートボールの利用をさせているこども野球場というのはどこでしょうか。","respondent":"堀越文化スポーツ振興課長","answer":"子供の森公園、それから区民公園の少年野球場等ですが、平日空きのある場合に、子供の森公園など、グラウンドゴルフのご利用等があります。","id":"exchange-127"},{"speaker":"川西委員","kind":"質問・要望","question":"そのときに、なかなかこういう施設を利用させてくれる地域とそうでない地域とあって、何とかならないもんかということを伺ったことがあります。ですから、人工芝だし、何でも利用できるんじゃないかなと思いますので、ぜひ要望としてお願いをしておきます。ただ、縮小するだけでなくて、ほかにどこかなかったのかなと思いますけれども、その辺について伺います。","respondent":"藤田水とみどりの課長","answer":"別な場所をという点では、常にそういう目を持ちながら、区内の遊休地、これを探しています。そういう場所があれば、私どももぜひマイガーデンとしていきたいと考えているものです。","id":"exchange-128"},{"speaker":"川西委員","kind":"質問・要望","question":"ぜひこれからも、区内全域にわたってバランスよく実行していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"私は、４４ページ、特別区民税の滞納についてお聞きしたいと思います。納税義務者の中で滞納者数は何人ぐらいいますか。そして、その中で、所得が、年収を含めて３００万円ぐらいでいいですが、以下の方は滞納者数の何割ぐらいを占めますか。おおよその数で結構ですが。","respondent":"武内税務課長","answer":"滞納者の人数は、非常に微妙で、日々、現年については、それぞれ期別がありまして、１カ月を過ぎますと滞納者とカウントしますので、なかなか数字をとらえることが難しいんですけれども、新年度を迎えたとき、では。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"給与所得者の３分の１は非正規雇用という状況にあり、さらに廃業や倒産、リストラなどにより給与所得が大幅に減っている方も大勢いるということがいろいろ報道等で知られています。そこでお聞きしたいんですが、大変な方が区民税をおさめられないということなんですが、実際延滞金の利息はどれぐらいなんでしょうか。何％でしょうか。","respondent":"武内税務課長","answer":"地方税法の規定によりまして、年１４.６％です。ただし、納期限間１カ月間の間は７.３％という数字です。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"今もちょっとお話ししたんですが、滞納者の方には、今の経済状況でリストラに遭ったり、働くために仕事を探している方も大勢いると思いますが、その時点で、前年度分の区民税が来るわけですから、実際生活をその間しているわけで、じゃあ、そうしてみますと、区民税をおさめてくださいと来たときには、お金がないという方ももちろん出てきますよね。その辺教えてください。","respondent":"武内税務課長","answer":"延滞金については、委員言われるとおり、非常に高額な延滞金です。これは９８％の方が現年については納税している。公正という視点から、こういう高い利率になっているのは事実です。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"一部はとっておられるということですが、基本的には１４.６％という金利がかかっているわけですね。品川区にお金がないならわかる。でも、実際今このような状況で雇用、勤めたくも勤められないという方がいる。その中で平然と、何年前に決められた金利かわかりませんが、１４.６％という高金利を区民に負わせるということをどう思うんですか。現実、区の考え方をきちっとお答えください。","respondent":"武内税務課長","answer":"もちろん現状の生活対応がどうなっているかということが非常に大切なわけです。延滞金の全額を徴収する際という例を１つ挙げますと、今、全然所得がないというような形で、以前不動産を売買して、かなりな所得があって、住民税がかかって、そのまま滞納になっている。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"今、土地の売買というお話をしていました。ほんとうにそういう方は私はまれだと思いますよ。課長、税金、区民税集めていて、実際もう大変な状況というのはおわかりな現状。それはもう区のほうでも認識していると思います。大変な方がいて、働くに働けない。やむを得ず延滞した。それが、何年前できたかわからないけど、１４.６％という高金利。果たしてこれでいいんでしょうか。もう一度お答えください。","respondent":"武内税務課長","answer":"ただ、生活対応がそういう状況であれば、見直していくということで考えております。","id":"exchange-134"},{"speaker":"若林委員","kind":"確認","question":"私は税外収入全体像をお聞きしたいのが１点と、それから、１３２ページの河川維持管理費収入と１１８ページの障害児（者）基礎調査費の３点伺います。税外収入のお話がたくさん出てきます。それから１１８ページの障害児（者）基礎調査費については、５年に１回というご説明がございましたので、５年ぶりに行われるということで、内容と今後の調査のデータ、内容とその活用とかを確認しておきたいと思います。","respondent":"金子企画財政課長、永尾障害者福祉課長、藤田水とみどりの課長","answer":"そういう意味では、ざっくりで申しわけないんですけれども、前年の比較ということでは、ちょっと今単純に手元で大ざっぱに計算しますと。その前の年、平成１７年は知的障害者を対象にやっているということで、これまでは障害別にやっておりましたけれども、平成２３年度の調査につきましては。まさに今後のあり方を検討するために、目黒区から品川区にお金を入れていただき、要は品川区が目黒区から受託をして、この浄化実験の効果のほどの検証をし。","id":"exchange-135"},{"speaker":"若林委員","kind":"確認","question":"それから障害児（者）の基礎調査のほうは、そうしますとこれはいわゆる発達障害が入っていないということの確認と、いわゆる個別で、いわゆる手帳の方々が対象になるのかということ。逆に言うと、手帳がない方のところはなかなか調査がし切れないのかなというところをお聞きしておきたいと思います。","respondent":"金子企画財政課長、永尾障害者福祉課長","answer":"その中でみんな、結果に結びついているのが、先ほど来話に出ている、例えば自販機の件であるとか、そういったものが成果に結びついていると思いますけれども、それ以外についても、各事業部で検討していると思いますので。この調査の対象ですけれども、現在国で出されているのは、先ほどのとおり、障害者手帳の有無にかかわらず、長期にわたる身体、知的、精神、または感覚的な機能障害により日常生活、社会生活が制限される。","id":"exchange-136"},{"speaker":"林委員","kind":"質問・要望","question":"未熟ゆえに何度も同じことを聞く場面があると思うんですけれども、我慢してお答えをいただきたいと思います。最初に借上型の区民住宅について、確認といいますか、させてください。いろんなところに出てきます。使用料としては、２７７戸分という使用料が４億８,０００万円強入っている。４７億円、４８億円というお金があらわされているんだけれども、債務負担行為で乗り切っていけるんですかね。","respondent":"柏原住宅担当課長、吉田保健予防課長、工藤環境課長、金子企画財政課長","answer":"全戸入りますと２９８戸ですが、このあいている部分につきましては、なかなかどういった所得階層の方が入るかという見込みが難しい部分がありますが。子宮頸がん自体は約１５種類ほどのがん化する可能性のあるウイルスが原因と言われておりますが、現在日本で発売されているワクチンは。マウントしながわ活用事業におきましては、里山の道づくりを中心に進められていたものですけれども、植林などの森林作業の体験をするなど。","id":"exchange-137"},{"speaker":"林委員","kind":"質問","question":"それを後で教えてください。それから、子宮頸がんについては、年によって受けられる人が決められてきているわけで、中学生から二十歳までに３回ということになると、打ち損なっちゃった、ワクチンを入れられなかったという人に対して、区はどういう、責任とまで言わないけれども、区としてはどういうふうに、二十歳までにいつでもいいですよと、３回受けてくださいよということにはできないんですかね。","respondent":"柏原住宅担当課長、中山地域活動課長、吉田保健予防課長、金子企画財政課長","answer":"空き家対策ということで、家賃を下げるであるとか、定期借家にするといったような対応をとらせていただきまして。逆に言うと、環境課のマウントしながわを入れて６回やっていたものを、環境課部分を廃止ですが、もともとこれは交流と同時に。これとあわせまして、一応がんの対策の一環ですので、やはり検診を重点的に行っていくことが大変重要ですので。これにつきましては、計画的に財源構成も検討しておりまして、十分これには対応できると考えているところです。","id":"exchange-138"},{"speaker":"林委員","kind":"質問・要望","question":"たくさん質問したので、絞って。もしあそこでワクチンを接種していればがんにならなかったのにとか、そういう女性の幸せについて僕は考慮してあげることが必要だなと思うので、毎年、去年打てなかったから今年打ってくださいという人を受け付けるということをぜひお考えいただきたいなと思いますので、要望しておきます。いろいろありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"土井委員","kind":"質問・要望","question":"都委託金の理科指導力向上事業ですが、額は小さいんですけれども、中身としてはえらい大きな話に聞こえたんですが、ぜひ私も理科指導力を上げてもらいたいんですけれども、この経費も委託金ですから、向こうから委託がなきゃしようがないのかもしれませんが、継続的にいくものなのか、どうなのかということと、仮に継続的に来なくても、そうなったらこれくらいは品川区の根性があれば幾らでも出せるわけで。","respondent":"金子企画財政課長、和氣学務課長、冠木指導課長","answer":"それから比べると、このような形で平成２３年度は見込めるだろうということで、これは平成２２年度実績から見ておりますので。私どもとしては、この３年間をかけて、専門知識を業者から教示を受けて、運営委員会というのをつくってありますので。理科の教員の質の向上、実験、観察等の向上については、当然委員のお話のように、水準を上げていくべきものである、それから。","id":"exchange-140"},{"speaker":"土井委員","kind":"質問・要望","question":"ただ、平成２９年までの時限ということだということはもう決まっているわけですから、その間に、今先ほどあったように、自己管理がしていけるような状況というものをしっかりつくっていかなきゃならないんだろうと思いますし、そのことがうまくいくか、いかないかが、そのほかの学校等でこれをやるか、やらないかにかかってくるんだろうと思うので。","respondent":"和氣学務課長、田村庶務課長、金子企画財政課長、冠木指導課長","answer":"ということで、委託業者がやる部分と、それから運営管理でやる部分としっかり分担しながら、だんだん技術を伝授していただくという形で。都市部ですから、地域開放の話も当然出てきますので、あくまで第一日野小学校を検証して、その結果によってどうするか考えていくと。これは預金の利子に対してかかるものですから、いわゆる市中金利。理科指導力向上事業の中で育ててきた教員が、１人、２人と育ってくるわけですけれども。","id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私、歳入のところで、区長の政治姿勢について伺いたいと思います。ここでまず伺いたいんですけれども、効率的区政運営という考え方と福祉の充実、きょうは特に保育の整備の角度から、効率的な運営と福祉の充実、この問題についてどういうふうに考えているのか、まず聞きたい。あわせて、保育事業についても、どういうふうに見ているのか、伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"そうした中では、当然ながら、施政方針にも書いてありますが、労働力人口の減少や、また女性の社会進出といったものも考えられてきますので、そういったものに対応していくためには、やはり今後は、一段と厳しさが増す中で、行財政改革をさらに推進いたしまして、効率的。","id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、今の区のほうの考え方とこの効率性というのは、全く私、違うと思うんですけれども、効率的区政運営の考え方から見ると、こうした、いつでも入れる、そういう余裕というか、そういうのをどういうふうに考えるんでしょうか。ところが、今、そうした未認可も、もう４月でいっぱいなんですよね。去年は、両親共働きフルタイムが４７人、育休明けが３４人でしたけれども、ことしはどうなんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、その後、出産期にある女性の人口は、今と比較しまして、１０％、２０％減っていくという見込みが出ておりますので、これを見越した上で対策を立てていくことは当然必要だと考えております。それから、４４１人の実態、親の就労状況ですが、こちらはまだ途中経過です。","id":"exchange-143"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところは伺いたいと思います。もう一つ、両親フルタイムで入れなかった。これは保育園をしっかり効率的運営していくには、入れない人が出て当然なんだとお考えなんでしょうか。それとも、やっぱりちゃんと受け入れるには、そこそこ余裕を持った施設整備ということが私は必要だと思うんですけれども、そこら辺の考え方、あわせて伺いたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"保育の需要につきましては、これまでも申し上げてきましたとおり、認可保育園を軸にすることが基本ですけれども、認証保育所や保育ママなどさまざまな施策で対応してまいります。それは、この先変わることはございません。","id":"exchange-144"},{"speaker":"宮崎委員","kind":"質問","question":"私、昨年が両親共働きでも入れなかった、こういう事態を効率的な運営という角度から見たらどうなんですかということを評価ですね、区の考え方を聞いたんですけれども、そこを改めて伺いたいと思います。将来どうするのか。それをなぜ今、保育をつくるのを積極的になれないのかということなんですね。なぜ、１０年後の問題で、今の人たちが保育園に入れない。これを我慢しなきゃいけないんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"このように、多様な施策で対応してきているところです。今後もさらなる民間事業者への支援は充実させて、対応を図っていく計画は立ててまいりたいと考えております。計画というのは、計画の策定時の社会情勢のもとで最適と思われるものを立てております。","id":"exchange-145"},{"speaker":"宮崎委員","kind":"質問","question":"もうちょっと聞きますけれども、平成３０年、あと１０年間は増え続けるということですと、この１０年間で未就学人口は何人増えると見込んでいるのか。増えると見込んでいるのか。その数を予測しているということであれば、伺いたい。で、民間もとおっしゃっていましたけれども、民間にどういうふうに持ってもらうのか。この数を伺いたい。そこは、区のほうはどういうふうな説明の仕方をしているんでしょうか。","respondent":"古川子ども未来事業部長","answer":"効率的な行政を進める上で、私どもは直近の保育需要を勘案しながら、それに必要な受け入れ枠を常に準備している、こういう中で対応しています。","id":"exchange-146"},{"speaker":"三上委員","kind":"質問","question":"私も、軽四輪という自家用車を昔持って、乗っていたことがあって、税金払っていたというのを覚えていますけれども、そのほかに、自動二輪というんでしょうか、通常で言えば、原動機付自転車というような表現があると思いますけれども、こういったところが一くくりになって、課税基本台数が３万７,４００台と、こう数字出てきちゃっていると、何がどうなのかということがわからない。","respondent":"武内税務課長、工藤環境課長、田村庶務課長","answer":"それぞれ調定額につきましては、１億円前後で今回はそれを前年に向けて１％ほどマイナスということです。その工事の前段階でアスベストの調査を実施する必要がありまして、その調査費用を助成するということになっております。水道管の直結化事業ですが、改築校については、先ほども答弁しましたように、やはり水飲み場の位置が大変複雑だということ。","id":"exchange-147"},{"speaker":"三上委員","kind":"質問・要望","question":"軽四輪についての、しっかりとそこの標準についても、これは企画のほうになるでしょうけれども、そういった点での、少なくとも軽四輪とか自動二輪とか、そういう表示という、それもすべて軽自動車だという一くくりにするのではなくて、一目で見て、あっ、こういうものが計上されているんだなということで、ぜひ記載していっていただきたいとお願いしたいんですけれども、いかがでしょうか。","respondent":"武内税務課長、金子企画財政課長、工藤環境課長、田村庶務課長、山岡健康課長","answer":"この辺については、確かに電気自転車という部分もあると思いますけれども、やはり何といっても、品川区の場合については。予算書の軽自動車税の表記の問題ですけれども、区民に対するわかりやすさという観点から、ご指摘の点も踏まえて検討してまいります。アスベスト関連につきましてのお尋ねです。やはりアスベストに関しましては、いろいろと対応、所管がまたがってあります。直結化した学校の声を聞きますと、やはり水がおいしいだとか、安心だとか、あるいは、冷たい水で。","id":"exchange-148"},{"speaker":"三上委員","kind":"質問・要望","question":"アスベストに関して、ぜひともそういう、各課にまたがるということになっておりますので、解体時に相談があったという、その時点から、その先については、こういう形の相談窓口がありますよと。そういう最初の窓口というのが大事だと私は思いますので、ぜひともそういった取り組みやっていっていただきたいと思います。軽自動車税もわかりやすいようによろしくお願いしたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"松澤委員","kind":"質問","question":"今年度中に完成だったものを３カ月前倒しで完成するということで、大変に近隣の方々が喜んでいるというお話も伺っておりますけれども、この都市計画道路、すぐそばが補助２６号線、交差して補助１６３号線ということですけれども、補助２６号線は東京都が工事施工して、補助１６３号線は品川区がやっているんですけれども、どういう形で区別というんですか、仕分けができているんですか。","respondent":"藤橋都市整備下水道課長","answer":"補助１６３号線の東急大井町線の交差部分から北側の部分につきましては、都道の部分と区道の部分がありますので、道路の真ん中付近で都道の部分と区の部分があって、その部分については管理を分担しながらやっているという状況です。","id":"exchange-150"},{"speaker":"松澤委員","kind":"意見","question":"今詳しく聞きましたけれども、そうではなくて、補助２６号線、補助１６３号線、ほかにもありますよね。補助４６号線とか補助２０５号線とか。何で東京都と区でやるものの仕分け、何でここは東京都なの、何でここは品川区なのという、その理由を聞きたいと思います。","respondent":"岩田都市環境事業部長","answer":"それ以下のものについては、区が施工する、こういう取り決めになっております。ただ、これは、実施主体がそう決めてあるのでありまして、できた後、どこが管理するかというのはまた別になります。","id":"exchange-151"},{"speaker":"松澤委員","kind":"質問","question":"今お話を伺いましたけれども、そうすると、補助１６３号線は、できた後の植栽の整備とか清掃というのは品川区がやるんだというお話でよろしいですよね。昨年のお話の中で、あそこが電線類地中化ということで、重複で、区道にも入るようにしたというお話を伺っています。それで、今年度の予算の中にも、電線類地中化の予算がありますけれども、その中にはもう入っているんでしょうか。","respondent":"松代都市計画課長","answer":"今、お話にありました鮫洲大山線につきましても、今の補助２６号線の整備がきちんと終わりました。従来あります鮫洲大山線が新しくできる補助２６号線に変わった時点で、区道に変わるという形で今話を進めております。","id":"exchange-152"},{"speaker":"松澤委員","kind":"質問","question":"あの境目の人から話を伺ったんですけれども、かむろ坂のほうは週に１回ぐらいきれいに清掃に来るけど、補助４６号線のほうは全然来ないよ、ごみの山だよ、何だい、あれは。まあ、完成したら都道だからどうなんですかねという話もしてきたんですけれども、今、区道に編入されるんじゃないかという話を聞きましたけれども、補助４６号線、武蔵小山の補助２６号線まで、目黒区側もありますよね。","respondent":"松代都市計画課長","answer":"補助４６号線の件ですけれども、もう既に収用手続に入っておりまして、もうしばらくですべて解決すると聞いております。","id":"exchange-153"},{"speaker":"松澤委員","kind":"質問","question":"補助４６号線は、あそこが都道で都が管理すると、防災避難道路として林試の森に近いですから、大変だななんて思っていたところ、区が管理するようになるというお話を伺って、安心をいたしました。じゃあ、これで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-154"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/779540?Template=document&Id=948#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":120891,"voices":391}}]);
